# Interface
# --------------------------------------------------------------------------

# --------------------------------------------------------------------------
# Boîte de sélection (fenêtre / capture, comme l'addon Cross Select)
def bake_negative_scale(obj):
    """Objet maillage miroir : on reporte l'inversion dans le maillage pour garder une échelle positive (sinon -1)."""
    try:
        if (obj.type != 'MESH' or obj.data.users != 1 or obj.children
                or obj.matrix_world.to_3x3().determinant() >= 0.0):
            return
        flip = Matrix.Scale(-1.0, 4, Vector((1.0, 0.0, 0.0)))
        mw = obj.matrix_world.copy()
        obj.data.transform(flip)
        bm = bmesh.new()
        bm.from_mesh(obj.data)
        bmesh.ops.reverse_faces(bm, faces=bm.faces[:])
        bm.to_mesh(obj.data)
        bm.free()
        obj.data.update()
        obj.matrix_world = mw @ flip
    except (RuntimeError, ReferenceError, ValueError):
        pass


class DESSIN_OT_miroir(DessinTransform):
    bl_idname = "dessin.mirror"
    bl_label = "Mirror"
    bl_description = ("Mirrors the selection about a plane: two points define the mirror line in the construction plane "
                      "(Shift: orthogonal, C: keep / replace the original)")

    TITLE = "Mirror"
    NEEDED = 2
    NUMFIELDS = 0
    MIRRORS = True
    NO_SELECTION = "Select the objects to mirror first"

    def invoke(self, context, event):
        result = super().invoke(context, event)
        self.center = True   # comme dans Rhino : le miroir garde l'original (C : le remplacer)
        if 'RUNNING_MODAL' in result:
            self.refresh(context)
        return result

    def prompt(self):
        if getattr(self, "selecting", False):
            return ""
        mode = "copy" if self.center else "replace"
        if not self.points:
            return f"start of the mirror line ({mode})   [C: copy / replace]"
        return f"end of the mirror line ({mode})   (Shift: orthogonal)   [C: copy / replace]"

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        a = self.points[0]
        u, v, nrm = plane_axes(self.axis)
        d = self.cur - a
        du, dv = d.dot(u), d.dot(v)
        if self.ortho:
            if abs(du) >= abs(dv):
                dv = 0.0
            else:
                du = 0.0
        L = math.hypot(du, dv)
        if L < 1e-9:
            return [], [], "", None
        e = (u * du + v * dv) / L
        m = nrm.cross(e)
        m.normalize()
        R3 = Matrix(((1 - 2 * m.x * m.x, -2 * m.x * m.y, -2 * m.x * m.z),
                     (-2 * m.y * m.x, 1 - 2 * m.y * m.y, -2 * m.y * m.z),
                     (-2 * m.z * m.x, -2 * m.z * m.y, 1 - 2 * m.z * m.z)))
        xform = Matrix.Translation(m * (2.0 * a.dot(m))) @ R3.to_4x4()
        ext = max(L, 1e-3) * 6.0
        info = f"Mirror line {self.fmt(L)}   ({'copy' if self.center else 'replace'})"
        return [], [[a - e * ext, a + e * ext]], info, ("xform", xform)

    def reverse_edit_faces(self):
        """Mode édition : un miroir retourne l'orientation des faces déplacées, on la rétablit."""
        for obj, idx, _w0 in self.items:
            try:
                bm = bmesh.from_edit_mesh(obj.data)
            except (ValueError, ReferenceError):
                continue
            bm.verts.ensure_lookup_table()
            vs = {bm.verts[i] for i in idx}
            faces = [f for f in bm.faces if all(x in vs for x in f.verts)]
            if faces:
                bmesh.ops.reverse_faces(bm, faces=faces)
            bmesh.update_edit_mesh(obj.data, loop_triangles=True, destructive=True)

    def build(self, context, spec):
        before = set(bpy.data.objects.keys())
        super().build(context, spec)
        if self.edit:
            if not self.center:
                self.reverse_edit_faces()   # (les copies sont retournées dans edit_move)
            return None
        if self.center:
            for name in set(bpy.data.objects.keys()) - before:
                bake_negative_scale(bpy.data.objects[name])
        else:
            for obj, _mw in self.items:
                bake_negative_scale(obj)
        return None


# --------------------------------------------------------------------------
# Array (rectangulaire, linéaire, polaire)
# --------------------------------------------------------------------------

ARRAY_STATE = {"nx": 3, "ny": 3, "nz": 1, "n_lin": 5, "n_pol": 6, "ang": 360.0}   # derniers réglages (comme Rhino)
ARRAY_MAX = 5000


class DessinArray(DessinTransform):
    """Base des outils Array : les copies sont des duplicatas de la sélection (classe non enregistrée)."""

    NUMFIELDS = 3
    HAS_CENTER = False
    EDIT_OK = True
    NO_SELECTION = "Select the objects to array first"
    PREVIEW_MAX = 250

    # ---- saisie sûre (la liste typed peut être plus courte que NUMFIELDS) ----
    def pad_typed(self):
        while len(self.typed) < 6:
            self.typed.append('')

    def typed_value(self, i):
        self.pad_typed()
        return super().typed_value(i)

    def typed_raw(self, i):
        self.pad_typed()
        return super().typed_raw(i)

    def traw(self, i):
        return self.typed_raw(i)

    def tval(self, i):
        return self.typed_value(i)

    def handle_typing(self, event):
        while len(self.typed) < 6:
            self.typed.append('')
        return super().handle_typing(event)

    def reset_state(self):
        super().reset_state()
        self.typed = [''] * 6

    def count(self, i, key):
        t = self.traw(i)
        if t is not None:
            return max(1, int(round(abs(t))))
        return ARRAY_STATE[key]

    def can_confirm_typed(self):
        return True

    # ---- aperçu : boîtes englobantes des copies ----
    def capture_ghost(self, max_edges=500000):
        self._bbox = None
        super().capture_ghost(max_edges)

    def item_bbox(self):
        if getattr(self, "_bbox", None) is not None:
            return self._bbox
        pts = []
        try:
            if self.edit:
                for _o, _idx, w0 in self.items:
                    if len(w0):
                        pts.append(np.min(w0, axis=0))
                        pts.append(np.max(w0, axis=0))
            else:
                for obj, _mw in self.items:
                    mw = obj.matrix_world
                    pts += [mw @ Vector(c) for c in obj.bound_box]
        except ReferenceError:
            pass
        if not pts:
            self._bbox = ()
            return self._bbox
        arr = np.array([tuple(p) for p in pts], dtype=np.float64)
        lo, hi = arr.min(axis=0), arr.max(axis=0)
        x0, y0, z0 = lo
        x1, y1, z1 = hi
        self._bbox = tuple(Vector(p) for p in (
            (x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0),
            (x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1)))
        return self._bbox

    @staticmethod
    def box_path(c, X):
        p = [X @ q for q in c]
        order = (0, 1, 2, 3, 0, 4, 5, 6, 7, 4, 5, 1, 2, 6, 7, 3)
        return [p[i] for i in order]

    def instance_guides(self, mats):
        bb = self.item_bbox()
        if not bb:
            return []
        center = sum(bb, Vector()) / 8.0
        out = []
        for M in mats[:self.PREVIEW_MAX]:
            X = M(center) if callable(M) else M
            out.append(self.box_path(bb, X))
        return out

    def refresh(self, context):
        if self.selecting:
            self.refresh_selecting(context)
            return
        DessinBase.refresh(self, context)   # pas de déplacement en direct des originaux : seules les copies s'affichent

    # ---- construction ----
    def finish_shape(self, context):
        _, _, _, spec = self.compute()
        if spec is None:
            self.refresh(context)
            return
        self.build(context, spec)
        self.store_state()
        self.finished = True
        self.reset_state()

    def store_state(self):
        pass

    def build(self, context, spec):
        mats = spec[1]
        if len(mats) > ARRAY_MAX:
            self.report({'WARNING'}, f"Too many copies ({len(mats)}), limit {ARRAY_MAX}")
            return None
        if self.edit:
            cen = Vector()
            n = 0
            for _o, _idx, w0 in self.items:
                for p in w0:
                    cen += Vector(p)
                    n += 1
            cen = cen / n if n else cen
            for M in mats:
                self.edit_move(M(cen) if callable(M) else M, duplicate=True)
        else:
            for M in mats:
                for obj, mw in self.items:
                    dup = duplicate_hierarchy(obj)
                    X = M(mw.translation) if callable(M) else M
                    dup.matrix_world = X @ mw
        self.committed = True
        return None


class DESSIN_OT_array_rect(DessinArray):
    bl_idname = "dessin.array_rect"
    bl_label = "Array: Rectangular"
    bl_description = ("Rectangular array of the selection: base corner then opposite corner of the unit cell "
                      "(type X count, Tab, Y count, Tab, Z count, Tab, X / Y / Z spacing)")

    TITLE = "Array"
    NUMFIELDS = 6
    PLANAR = True

    @property
    def NEEDED(self):
        return 3 if self.count(2, "nz") > 1 else 2

    def height_stage(self):
        return (not getattr(self, "selecting", False) and len(self.points) == 2 and self.count(2, "nz") > 1)

    ARROW_KEYS = {'RIGHT_ARROW': ("nx", 1, 0), 'LEFT_ARROW': ("nx", -1, 0),
                  'UP_ARROW': ("ny", 1, 1), 'DOWN_ARROW': ("ny", -1, 1),
                  'PAGE_UP': ("nz", 1, 2), 'PAGE_DOWN': ("nz", -1, 2)}

    def modal(self, context, event):
        k = self.ARROW_KEYS.get(event.type)
        if (k and event.value == 'PRESS' and not getattr(self, "selecting", False)
                and self.area is not None and context.area is not None
                and find_window_region(self.area, event.mouse_x, event.mouse_y) is not None
                and not self.mouse_over_ui(event)):
            key, step, idx = k
            self.pad_typed()
            self.typed[idx] = ''          # la flèche remplace une valeur tapée
            ARRAY_STATE[key] = max(1, min(100, ARRAY_STATE[key] + step))
            self.refresh(context)
            return {'RUNNING_MODAL'}
        return super().modal(context, event)

    def lock_allowed(self):
        return self.LOCK_OK and not self.height_stage()

    def prompt(self):
        if getattr(self, "selecting", False):
            return ""
        nx, ny, nz = self.count(0, "nx"), self.count(1, "ny"), self.count(2, "nz")
        cnt = f"{nx}×{ny}×{nz}"
        if not self.points:
            return f"first corner of the unit cell ({cnt})"
        if len(self.points) == 1:
            return (f"opposite corner of the unit cell ({cnt})   "
                    "(arrows: ←→ X count, ↑↓ Y count, PgUp/PgDn Z count; or type counts with Tab)")
        return "Z spacing   (top view: type the spacing then Enter)"

    def update_cursor(self, context, event):
        if not self.height_stage():
            return super().update_cursor(context, event)
        region = find_window_region(self.area, event.mouse_x, event.mouse_y)
        if region is None or self.mouse_over_ui(event):
            self.snap_screen = None
            self.snap_kind = None
            return
        self.region = region
        rv3d = region_rv3d(region, self.area)
        mx, my = event.mouse_x - region.x, event.mouse_y - region.y
        o = self.points[0]
        _, _, n = plane_axes(self.axis)
        last = self.points[-1]
        base = last - n * (last - o).dot(n)
        self.track_lines = []
        self.track_label = ""
        self.track_screen = None
        h = None
        snap = self.find_snap(mx, my, region, rv3d)
        if snap is not None:
            p, self.snap_screen, self.snap_kind = snap
            self._snap_pt = p.copy()
            h = (p - o).dot(n)
        else:
            self.snap_screen = None
            self.snap_kind = None
            self._snap_pt = None
            coord = Vector((mx, my))
            ro = region_2d_to_origin_3d(region, rv3d, coord)
            rv = region_2d_to_vector_3d(region, rv3d, coord)
            res = geometry.intersect_line_line(base, base + n, ro, ro + rv)
            if res:
                h = (res[0] - o).dot(n)
        if h is not None:
            self.cur = base + n * h
        elif self.cur is None:
            self.cur = base.copy()
        self.refresh(context)

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        o = self.points[0]
        u, v, n = plane_axes(self.axis)
        pts = self.points + [self.cur]
        stage = len(self.points)
        nx, ny, nz = self.count(0, "nx"), self.count(1, "ny"), self.count(2, "nz")
        d = pts[1] - o
        du, dv = d.dot(u), d.dot(v)
        sx = self.sized(3, du, du)
        sy = self.sized(4, dv, dv)
        if stage >= 2:
            dz = (pts[2] - o).dot(n)
            sz = self.sized(5, dz, dz)
        else:
            sz = self.sized(5, 0.0, 1.0)
        total = nx * ny * nz
        info = f"{nx}×{ny}×{nz} = {total} items   Spacing {self.fmt(abs(sx))} × {self.fmt(abs(sy))}"
        if nz > 1:
            info += f" × {self.fmt(abs(sz))}"
        ok = ((nx == 1 or abs(sx) > 1e-9) and (ny == 1 or abs(sy) > 1e-9)
              and (nz == 1 or abs(sz) > 1e-9) and total > 1)
        cell = [o, o + u * sx, o + u * sx + v * sy, o + v * sy, o]
        if not ok:
            return cell, [], info, None
        mats = []
        for k in range(nz):
            for j in range(ny):
                for i in range(nx):
                    if i == j == k == 0:
                        continue
                    mats.append(Matrix.Translation(u * (sx * i) + v * (sy * j) + n * (sz * k)))
        return cell, self.instance_guides(mats), info, ("array", mats)

    def store_state(self):
        ARRAY_STATE["nx"] = self.count(0, "nx")
        ARRAY_STATE["ny"] = self.count(1, "ny")
        ARRAY_STATE["nz"] = self.count(2, "nz")


class DESSIN_OT_array_linear(DessinArray):
    bl_idname = "dessin.array_linear"
    bl_label = "Array: Linear"
    bl_description = ("Linear array: base point then a second point (spacing, or total length with D); "
                      "type the count, Tab, the spacing (Shift: orthogonal)")

    TITLE = "Array (linear)"
    NEEDED = 2
    NUMFIELDS = 2
    PLANAR = False
    HAS_MODE = True
    MODES = ("spacing = base → point", "total length = base → point")

    def invoke(self, context, event):
        self.mode = 0
        return super().invoke(context, event)

    def prompt(self):
        if getattr(self, "selecting", False):
            return ""
        n = self.count(0, "n_lin")
        if not self.points:
            return f"base point ({n} items)"
        return (f"second point: {self.MODES[self.mode]}   (type count, Tab, spacing, Enter)   "
                "[D: spacing / total length, Shift: orthogonal]")

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        a = self.points[0]
        u, v, _ = plane_axes(self.axis)
        d = self.cur - a
        if self.ortho:
            du, dv = d.dot(u), d.dot(v)
            d = u * du if abs(du) >= abs(dv) else v * dv
        n = self.count(0, "n_lin")
        if n < 2:
            return [], [], "", None
        length = d.length
        direction = d / length if length > 1e-9 else u.copy()
        t = self.tval(1)
        if t is not None:
            step = direction * abs(t)
        elif self.mode == 1:
            step = d / (n - 1)
        else:
            step = d
        if step.length < 1e-9:
            return [], [[a, self.cur]], "", None
        mats = [Matrix.Translation(step * k) for k in range(1, n)]
        info = f"{n} items   Spacing {self.fmt(step.length)}   Total {self.fmt(step.length * (n - 1))}"
        return [], [[a, a + step * (n - 1)]] + self.instance_guides(mats), info, ("array", mats)

    def store_state(self):
        ARRAY_STATE["n_lin"] = self.count(0, "n_lin")


class DESSIN_OT_array_polar(DessinArray):
    bl_idname = "dessin.array_polar"
    bl_label = "Array: Polar"
    bl_description = ("Polar array around an axis perpendicular to the construction plane: click the center, "
                      "type the count and the angle (D: rotate items or not, F: other direction)")

    TITLE = "Array (polar)"
    NEEDED = 2
    NUMFIELDS = 2
    HAS_MODE = True
    HAS_FLIP = True
    MODES = ("rotate items", "keep orientation")

    def invoke(self, context, event):
        self.mode = 0
        return super().invoke(context, event)

    def prompt(self):
        if getattr(self, "selecting", False):
            return ""
        n = self.count(0, "n_pol")
        if not self.points:
            return f"center of the polar array ({n} items, {ARRAY_STATE['ang']:g}°)"
        return ("click to confirm   (type count, Tab, angle, Enter)   "
                f"[D: {self.MODES[self.mode]}, F: other direction]")

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        c = self.points[0]
        u, v, nrm = plane_axes(self.axis)
        n = self.count(0, "n_pol")
        ang = self.traw(1)
        if ang is None:
            ang = ARRAY_STATE["ang"]
        if n < 2 or abs(ang) < 1e-9:
            return [], [[c, self.cur]], "", None
        full = abs(abs(ang) - 360.0) < 1e-6
        step = math.radians(ang) / (n if full else (n - 1))
        if self.flip:
            step = -step
        mats = []
        for k in range(1, n):
            R = Matrix.Translation(c) @ Matrix.Rotation(step * k, 4, nrm) @ Matrix.Translation(-c)
            if self.mode == 0:
                mats.append(R)
            else:
                mats.append(lambda p, R=R: Matrix.Translation((R @ p) - p))
        info = f"{n} items   {ang:g}°   {self.MODES[self.mode]}"
        radius = (self.cur - c).length
        ring = arc_samples(c, u, v, max(radius, 1e-6), 0.0, TAU, 64) if radius > 1e-9 else []
        return [], [[c, self.cur], ring] + self.instance_guides(mats), info, ("array", mats)

    def store_state(self):
        ARRAY_STATE["n_pol"] = self.count(0, "n_pol")
        a = self.traw(1)
        if a is not None:
            ARRAY_STATE["ang"] = a


# --------------------------------------------------------------------------
# Cut (solides)
# --------------------------------------------------------------------------

def cut_mesh_by_plane(obj, co, no, keep):
    """Coupe un maillage avec un plan monde (co, no). keep : 'pos', 'neg' ou 'both'.
    Retourne la liste des objets résultants (l'original reste le premier)."""
    mw = obj.matrix_world
    inv = mw.inverted()
    lco = inv @ co
    lno = (mw.to_3x3().transposed() @ no).normalized()

    def run(me, clear_inner, clear_outer):
        bm = bmesh.new()
        bm.from_mesh(me)
        closed = all(len(e.link_faces) == 2 for e in bm.edges) and len(bm.faces) > 0
        ret = bmesh.ops.bisect_plane(bm, geom=list(bm.verts) + list(bm.edges) + list(bm.faces),
                                     dist=1e-7, plane_co=lco, plane_no=lno,
                                     clear_inner=clear_inner, clear_outer=clear_outer)
        if closed:
            cut = [g for g in ret["geom_cut"] if isinstance(g, bmesh.types.BMEdge) and g.is_valid]
            if cut:
                try:
                    bmesh.ops.holes_fill(bm, edges=cut, sides=0)
                except (RuntimeError, ValueError, TypeError):
                    try:
                        bmesh.ops.triangle_fill(bm, edges=cut, use_beauty=True)
                    except (RuntimeError, ValueError, TypeError):
                        pass
        bm.normal_update()
        out = bm.verts and len(bm.faces) + len(bm.edges) > 0
        bm.to_mesh(me)
        bm.free()
        me.update()
        return bool(out)

    src = obj.data
    results = []
    if keep == 'both':
        other = obj.copy()
        other.data = src.copy()
        for coll in obj.users_collection:
            coll.objects.link(other)
        obj.data = src.copy()
        if run(obj.data, True, False):    # côté positif conservé (on enlève l'intérieur = négatif)
            results.append(obj)
        if run(other.data, False, True):
            results.append(other)
        else:
            bpy.data.objects.remove(other)
        return results
    obj.data = src.copy()
    run(obj.data, keep == 'pos', keep == 'neg')
    return [obj]


class DESSIN_OT_cut(DessinArray):
    bl_idname = "dessin.cut"
    bl_label = "Split"
    bl_description = ("Splits solids into separate parts with a vertical plane defined by a line (two points) "
                      "and closes the cut faces")
    TITLE = "Split"
    NEEDED = 2
    NUMFIELDS = 0
    EDIT_OK = False
    HAS_MODE = False
    HAS_FLIP = False
    PLANAR = True
    MODES = ("keep both parts", "keep one side", "keep the other side")
    NO_SELECTION = "Select the solids to split first"

    def invoke(self, context, event):
        if context.mode == 'EDIT_MESH':
            try:
                bpy.ops.object.mode_set(mode='OBJECT')
            except RuntimeError:
                self.report({'WARNING'}, "Switch to Object mode")
                return {'CANCELLED'}
        self.mode = 0
        return super().invoke(context, event)

    def pick_line(self, context):
        """Segment (A, B monde) de la ligne existante sous la souris (courbe, polyligne ou contour), ou None."""
        mouse = _CMD["mouse"].get(self.area.as_pointer()) if self.area is not None else None
        if mouse is None or self.region is None:
            return None
        rv3d = region_rv3d(self.region, self.area)
        if rv3d is None:
            return None
        persp = np.array(rv3d.perspective_matrix, dtype=np.float64)
        skip = {o.name for o, _mw in self.items}
        dg = context.evaluated_depsgraph_get()
        m = np.array(mouse, dtype=np.float64)
        best, best_d = None, 8.0 * px_scale()
        for obj in context.view_layer.objects:
            try:
                if obj.name in skip or obj.type not in {'CURVE', 'MESH'} or not obj.visible_get():
                    continue
                if obj.type == 'MESH' and len(obj.data.polygons):
                    continue
                paths = object_paths(obj, dg)
            except (RuntimeError, ReferenceError):
                continue
            for P, closed in paths:
                Q = np.vstack((P, P[:1])) if closed else P
                if len(Q) < 2:
                    continue
                sx, sy, ok = _project_region(Q, persp, self.region)
                S = np.stack((sx, sy), axis=1)
                A, B = S[:-1], S[1:]
                good = ok[:-1] & ok[1:]
                AB = B - A
                L2 = np.maximum((AB * AB).sum(axis=1), 1e-9)
                t = np.clip(((m - A) * AB).sum(axis=1) / L2, 0.0, 1.0)
                d = np.linalg.norm(A + AB * t[:, None] - m, axis=1)
                d = np.where(good, d, 1e9)
                i = int(np.argmin(d))
                if d[i] < best_d:
                    best_d = d[i]
                    best = (Vector(Q[i]), Vector(Q[i + 1]))
        return best

    def click(self, context):
        if (not self.selecting and not self.points and not self.edit
                and (self.snap_screen is None or self.snap_kind == 7)):
            seg = self.pick_line(context)
            if seg is not None and (seg[1] - seg[0]).length > 1e-9:
                self.flush_pending(context)
                if not self.sync_selection(context):
                    return
                self.points = [seg[0]]
                self.cur = seg[1]
                self.finish_shape(context)
                return
        super().click(context)

    def prompt(self):
        if getattr(self, "selecting", False):
            return ""
        if not self.points:
            return "first point of the splitting line (or click an existing line)"
        return "second point"

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        a = self.points[0]
        u, v, n = plane_axes(self.axis)
        d = self.cur - a
        d = d - n * d.dot(n)
        if d.length < 1e-9:
            return [], [], "", None
        d.normalize()
        pn = d.cross(n)
        if self.flip:
            pn = -pn
        bb = self.item_bbox()
        ext = 1.0
        z0, z1 = 0.0, 1.0
        if bb:
            ext = max((q - a).length for q in bb) * 1.5 + 1e-6
            zs = [(q - a).dot(n) for q in bb]
            z0, z1 = min(zs), max(zs)
        e0, e1 = a - d * ext, a + d * ext
        rect = [e0 + n * z0, e1 + n * z0, e1 + n * z1, e0 + n * z1, e0 + n * z0]
        mid = a + d * ((self.cur - a).dot(d) / 2.0)
        tick = [mid, mid + pn * ext * 0.15]
        guides = [rect, tick]
        if self.mode == 0:
            guides.append([mid, mid - pn * ext * 0.15])
        keep = ('both', 'pos', 'neg')[self.mode]
        info = "Split: both parts kept"
        return [a, a + d * ((self.cur - a).dot(d))], guides, info, ("cut", a, pn, keep)

    def build(self, context, spec):
        _, co, no, keep = spec
        made = []
        for obj, _mw in self.items:
            try:
                if obj.type != 'MESH':
                    continue
                made.extend(cut_mesh_by_plane(obj, co, no, keep))
            except ReferenceError:
                continue
        self.committed = True
        if not made:
            self.report({'WARNING'}, "No mesh solid to split")
        return None

    def store_state(self):
        pass


# --------------------------------------------------------------------------
# Fillet Edge (congé sur arêtes de maillages)
# --------------------------------------------------------------------------

FILLET_STATE = {"radius": 0.05, "segments": 8}
CHAMFER_STATE = {"radius": 0.02, "segments": 1}


def mesh_edge_geometry(obj):
    """(coordonnées monde des sommets, arêtes) d'un maillage, ou None."""
    me = obj.data
    nv, ne = len(me.vertices), len(me.edges)
    if nv == 0 or ne == 0 or ne > 400000:
        return None
    co = np.empty(nv * 3, dtype=np.float32)
    me.vertices.foreach_get('co', co)
    ed = np.empty(ne * 2, dtype=np.int32)
    me.edges.foreach_get('vertices', ed)
    mw = np.array(obj.matrix_world, dtype=np.float64)
    wco = co.reshape(-1, 3).astype(np.float64) @ mw[:3, :3].T + mw[:3, 3]
    return wco, ed.reshape(-1, 2)


class DessinEdgeRound(DessinBase):
    """Base de Fillet Edge / Chamfer Edge (classe non enregistrée)."""

    STATE = FILLET_STATE
    CHAMFER = False
    WORD = "radius"

    TITLE = "Fillet Edge"
    NEEDED = 2
    NUMFIELDS = 2
    EDIT_OK = True
    HAS_CENTER = False
    PLANAR = False
    LOCK_OK = False
    PICK_PX = 12.0

    # ---- cycle de vie ----
    def invoke(self, context, event):
        self.reenter_edit = False
        pre = {}
        if context.mode == 'EDIT_MESH':
            try:
                for o in context.objects_in_mode_unique_data:
                    if o.type == 'MESH':
                        o.update_from_editmode()
                        pre[o.name] = {e.index for e in o.data.edges if e.select}
            except (AttributeError, RuntimeError):
                pre = {}
            try:
                bpy.ops.object.mode_set(mode='OBJECT')
                self.reenter_edit = True
            except RuntimeError:
                self.report({'WARNING'}, "Switch to Object mode")
                return {'CANCELLED'}
        self.sel = {}
        self.hilite = []
        self.box = None
        self._press = None
        self.phase = 'pick'
        self.orig = {}
        self.work = {}
        self.geo = {}
        self.committed = False
        self.anchor = None
        self.mouse_moved = False
        result = super().invoke(context, event)
        if 'RUNNING_MODAL' not in result:
            if self.reenter_edit:
                try:
                    bpy.ops.object.mode_set(mode='EDIT')
                except RuntimeError:
                    pass
            return result
        for name, idx in pre.items():
            if idx:
                self.sel[name] = set(idx)
        if self.total_selected():
            self.begin_radius(context)
        else:
            self.refresh(context)
        return result

    def reset_state(self):
        self.restore_all()
        self.phase = 'pick'
        self.anchor = None
        self.mouse_moved = False
        super().reset_state()

    def cleanup(self, context):
        if not self.committed:
            self.restore_all()
        super().cleanup(context)
        if self.reenter_edit:
            try:
                bpy.ops.object.mode_set(mode='EDIT')
            except RuntimeError:
                pass

    def after_finish(self, context):
        if self.tool_id:
            try:
                idle_tool()
            except (RuntimeError, TypeError):
                pass

    # ---- sélection des arêtes ----
    def total_selected(self):
        return sum(len(v) for v in self.sel.values())

    def candidates(self, context):
        objs = [o for o in context.view_layer.objects if o.type == 'MESH' and o.visible_get()]
        chosen = [o for o in objs if o.select_get()]
        return chosen or objs

    def geometry(self, obj):
        g = self.geo.get(obj.name)
        if g is None and obj.name not in self.geo:
            g = mesh_edge_geometry(obj)
            self.geo[obj.name] = g
        return g

    def pick_edge(self, context):
        """(objet, indice d'arête) sous la souris, ou None."""
        if getattr(self, "_mouse", None) is None or self.region is None:
            return None
        rv3d = region_rv3d(self.region, self.area)
        if rv3d is None:
            return None
        P = np.array(rv3d.perspective_matrix, dtype=np.float64)
        W, H = self.region.width, self.region.height
        mx, my = self._mouse
        limit = self.PICK_PX * px_scale()
        best = None
        for obj in self.candidates(context):
            g = self.geometry(obj)
            if g is None:
                continue
            wco, ed = g
            clip = np.hstack((wco, np.ones((len(wco), 1)))) @ P.T
            w = clip[:, 3]
            ok = w > 1e-9
            ws = np.where(ok, w, 1.0)
            sx = (clip[:, 0] / ws * 0.5 + 0.5) * W
            sy = (clip[:, 1] / ws * 0.5 + 0.5) * H
            a, b = ed[:, 0], ed[:, 1]
            ax, ay, bx, by = sx[a], sy[a], sx[b], sy[b]
            dx, dy = bx - ax, by - ay
            L2 = dx * dx + dy * dy
            t = np.where(L2 > 1e-12, ((mx - ax) * dx + (my - ay) * dy) / np.where(L2 > 1e-12, L2, 1.0), 0.0)
            t = np.clip(t, 0.0, 1.0)
            dist = np.hypot(ax + dx * t - mx, ay + dy * t - my)
            dist = np.where(ok[a] & ok[b], dist, np.inf)
            score = dist + 0.01 * (ws[a] + ws[b]) * 0.5
            i = int(np.argmin(score))
            if dist[i] <= limit and (best is None or score[i] < best[0]):
                best = (float(score[i]), obj, i)
        return None if best is None else (best[1], best[2])

    def box_select(self, context, remove):
        """Zone vers la droite : arêtes entièrement dedans ; vers la gauche : arêtes touchées (comme la sélection Rhino)."""
        x0, y0, x1, y1 = self.box
        crossing = x1 < x0
        xmin, xmax, ymin, ymax = min(x0, x1), max(x0, x1), min(y0, y1), max(y0, y1)
        rv3d = region_rv3d(self.region, self.area)
        if rv3d is None:
            return 0
        P = np.array(rv3d.perspective_matrix, dtype=np.float64)
        W, H = self.region.width, self.region.height
        n = 0
        for obj in self.candidates(context):
            g = self.geometry(obj)
            if g is None:
                continue
            wco, ed = g
            clip = np.hstack((wco, np.ones((len(wco), 1)))) @ P.T
            w = clip[:, 3]
            ok = w > 1e-9
            ws = np.where(ok, w, 1.0)
            sx = (clip[:, 0] / ws * 0.5 + 0.5) * W
            sy = (clip[:, 1] / ws * 0.5 + 0.5) * H
            a, b = ed[:, 0], ed[:, 1]
            valid = ok[a] & ok[b]
            if crossing:
                hit = _segments_hit_rect(sx[a], sy[a], sx[b], sy[b], xmin, ymin, xmax, ymax)
            else:
                ina = (sx[a] >= xmin) & (sx[a] <= xmax) & (sy[a] >= ymin) & (sy[a] <= ymax)
                inb = (sx[b] >= xmin) & (sx[b] <= xmax) & (sy[b] >= ymin) & (sy[b] <= ymax)
                hit = ina & inb
            idx = np.nonzero(hit & valid)[0]
            if not len(idx):
                continue
            s = self.sel.setdefault(obj.name, set())
            for i in idx.tolist():
                if remove:
                    s.discard(i)
                else:
                    s.add(i)
            n += len(idx)
        return n

    def box_select_from(self, context, box, remove):
        self.box = box
        try:
            return self.box_select(context, remove)
        finally:
            self.box = None

    def update_cursor(self, context, event):
        region = find_window_region(self.area, event.mouse_x, event.mouse_y) if self.area is not None else None
        if region is not None:
            self._mouse = (event.mouse_x - region.x, event.mouse_y - region.y)
        super().update_cursor(context, event)

    def edge_lines(self, items):
        out = []
        for name, idx in items:
            obj = bpy.data.objects.get(name)
            if obj is None:
                continue
            g = self.geometry(obj)
            if g is None:
                continue
            wco, ed = g
            for i in idx:
                if i < len(ed):
                    out.append([Vector(wco[ed[i][0]]), Vector(wco[ed[i][1]])])
        return out

    # ---- rayon ----
    def radius_now(self):
        t = self.typed_value(0)
        if t is not None:
            return abs(t)
        return self.STATE["radius"]

    def segments_now(self):
        if self.CHAMFER:
            return 1
        t = self.typed_raw(1)
        if t is not None:
            return int(max(1, min(64, round(t))))
        return self.STATE["segments"]

    def begin_radius(self, context):
        if not self.total_selected():
            return False
        self.phase = 'radius'
        self.anchor = self.cur.copy() if self.cur is not None else Vector()
        self.points = [self.anchor.copy()]
        self.mouse_moved = False
        self.typed = ['', '']
        self.apply_preview()
        self.refresh(context)
        return True

    def prompt(self):
        if self.phase == 'pick':
            return (f"click or drag a box to select the edges ({self.total_selected()} selected), then Enter   "
                    "[box to the right: inside, to the left: touching, Ctrl: deselect, click a selected edge: remove it]")
        if self.CHAMFER:
            return f"type the distance <{self.fmt(self.STATE['radius'])}>, Enter to confirm"
        return (f"type the radius <{self.fmt(self.STATE['radius'])}>, Tab, segments, Enter to confirm   "
                "[↑/↓: segments]")

    def compute(self):
        if self.phase == 'pick':
            sel = self.edge_lines((n, s) for n, s in self.sel.items())
            hit = None
            try:
                if self._press is None:
                    hit = self.pick_edge(bpy.context)
            except (ReferenceError, RuntimeError):
                pass
            prev = []
            if hit is not None:
                prev = self.edge_lines([(hit[0].name, [hit[1]])])
                prev = prev[0] if prev else []
            self.hilite = sel[:3000]
            return prev, [], f"{self.total_selected()} edge(s) selected", None
        self.hilite = []
        r, n = self.radius_now(), self.segments_now()
        guides = self.edge_lines((nm, s) for nm, s in self.sel.items())[:3000]
        if self.CHAMFER:
            return [], guides, f"distance {self.fmt(r)}", ("fillet", r, n)
        return [], guides, f"radius {self.fmt(r)}   {n} segments", ("fillet", r, n)

    def refresh(self, context):
        super().refresh(context)
        if self.phase == 'radius':
            self.apply_preview()

    # ---- application sur les maillages ----
    def apply_preview(self):
        r, n = self.radius_now(), self.segments_now()
        for name, idx in self.sel.items():
            obj = bpy.data.objects.get(name)
            if obj is None or not idx:
                continue
            if name not in self.orig:
                self.orig[name] = obj.data
                self.work[name] = obj.data.copy()
                obj.data = self.work[name]
            fillet_mesh(self.orig[name], self.work[name], idx, r, n, self.CHAMFER)

    def restore_all(self):
        for name, orig in list(self.orig.items()):
            obj = bpy.data.objects.get(name)
            work = self.work.get(name)
            try:
                if obj is not None:
                    obj.data = orig
                if work is not None:
                    bpy.data.meshes.remove(work)
            except (ReferenceError, RuntimeError):
                pass
        self.orig = {}
        self.work = {}
        self.geo = {}

    def finish_shape(self, context):
        if self.phase != 'radius':
            return
        self.STATE["radius"] = self.radius_now()
        self.STATE["segments"] = self.segments_now()
        self.apply_preview()
        for name, orig in self.orig.items():
            work = self.work.get(name)
            obj = bpy.data.objects.get(name)
            if work is None or obj is None:
                continue
            base = orig.name
            if orig.users == 0:
                bpy.data.meshes.remove(orig)
                work.name = base
        self.committed = True
        self.finished = True

    # ---- événements ----
    def click(self, context):
        if self.phase == 'radius':
            return      # le rayon se tape au clavier (Entrée valide), un clic n'a pas d'effet
        hit = self.pick_edge(context)
        if hit is None:
            return
        obj, i = hit
        s = self.sel.setdefault(obj.name, set())
        if i in s:
            s.discard(i)
        else:
            s.add(i)
        self.refresh(context)

    def modal(self, context, event):
        inside = (self.area is not None and context.area is not None
                  and find_window_region(self.area, event.mouse_x, event.mouse_y) is not None
                  and not self.mouse_over_ui(event))
        if self.phase == 'pick' and self.area is not None and context.area is not None:
            region = find_window_region(self.area, event.mouse_x, event.mouse_y)
            if (event.type == 'LEFTMOUSE' and event.value == 'PRESS' and inside
                    and not (event.alt or event.oskey)):
                self._press = (event.mouse_x - region.x, event.mouse_y - region.y)
                self._press_ctrl = event.ctrl
                self.box = None
                return {'RUNNING_MODAL'}
            if self._press is not None:
                if event.type == 'ESC' and event.value == 'PRESS':
                    self._press = None
                    self.box = None
                    self.refresh(context)
                    return {'RUNNING_MODAL'}
                if event.type in {'MOUSEMOVE', 'INBETWEEN_MOUSEMOVE'} and region is not None:
                    mx, my = event.mouse_x - region.x, event.mouse_y - region.y
                    px0, py0 = self._press
                    if self.box is not None or math.hypot(mx - px0, my - py0) > 5.0 * px_scale():
                        self.box = (px0, py0, mx, my)
                        try:
                            self.area.tag_redraw()
                        except ReferenceError:
                            pass
                    return {'RUNNING_MODAL'}
                if event.type == 'LEFTMOUSE' and event.value == 'RELEASE':
                    box, ctrl = self.box, self._press_ctrl
                    self._press = None
                    self.box = None
                    if box is not None:
                        n = self.box_select_from(context, box, ctrl)
                    else:
                        self.update_cursor(context, event)
                        self.click(context)
                    self.refresh(context)
                    return {'RUNNING_MODAL'}
        if inside and event.value == 'PRESS':
            if event.type in {'RET', 'NUMPAD_ENTER', 'SPACE'}:
                if self.phase == 'pick':
                    if not self.total_selected() or not self.begin_radius(context):
                        return self.exit(context)
                    return {'RUNNING_MODAL'}
                self.finish_shape(context)
                return self.exit(context)
            if event.type in {'UP_ARROW', 'DOWN_ARROW'} and self.phase == 'radius' and not self.CHAMFER:
                step = 1 if event.type == 'UP_ARROW' else -1
                self.typed[1] = ''
                self.STATE["segments"] = max(1, min(64, self.STATE["segments"] + step))
                self.refresh(context)
                return {'RUNNING_MODAL'}
            if event.type == 'ESC' and self.phase == 'radius':
                return self.exit(context)
        return super().modal(context, event)


def fillet_mesh(src, dst, edge_idx, radius, segments, chamfer=False):
    """dst = src dont les arêtes edge_idx sont arrondies (congé de rayon `radius`)."""
    bm = bmesh.new()
    bm.from_mesh(src)
    bm.edges.ensure_lookup_table()
    edges = [bm.edges[i] for i in edge_idx if i < len(bm.edges)]
    if edges:
        offs = []
        for e in edges:
            if len(e.link_faces) == 2:
                a = e.link_faces[0].normal.angle(e.link_faces[1].normal, 0.0)
                offs.append(radius if chamfer else (radius * math.tan(a / 2.0) if a > 1e-3 else 0.0))
            else:
                offs.append(radius)
        off = sum(offs) / len(offs)
        if off > 1e-9:
            try:
                ret = bmesh.ops.bevel(bm, geom=edges, offset=off, offset_type='OFFSET', segments=segments,
                                      profile=0.5, affect='EDGES', clamp_overlap=True, loop_slide=True)
                for f in ret.get("faces", []):
                    if f.is_valid:
                        f.smooth = not chamfer
            except (RuntimeError, ValueError, TypeError):
                pass
    bm.normal_update()
    bm.to_mesh(dst)
    bm.free()
    dst.update()


class DESSIN_OT_fillet_edge(DessinEdgeRound):
    bl_idname = "dessin.fillet_edge"
    bl_label = "Fillet Edge"
    bl_description = ("Rounds the edges of solids: click the edges or drag a box (right: inside, left: touching, "
                      "Ctrl: deselect), Enter, then type the radius (↑/↓: segments). "
                      "In Edit mode the selected edges are used")


class DESSIN_OT_chamfer_edge(DessinEdgeRound):
    bl_idname = "dessin.chamfer_edge"
    bl_label = "Chamfer Edge"
    bl_description = ("Bevels the edges of solids with a flat cut: click the edges or drag a box (right: inside, "
                      "left: touching, Ctrl: deselect), Enter, then type the distance. "
                      "In Edit mode the selected edges are used")
    TITLE = "Chamfer Edge"
    NUMFIELDS = 1
    STATE = CHAMFER_STATE
    CHAMFER = True


# --------------------------------------------------------------------------
# Offset Edge (copie parallèle d'arêtes de maillage ou de courbes)
# --------------------------------------------------------------------------

OFFSET_STATE = {"dist": 0.05}


def curve_edge_geometry(obj):
    """(sommets monde, arêtes) de la courbe évaluée, ou None."""
    try:
        dg = bpy.context.evaluated_depsgraph_get()
        me = bpy.data.meshes.new_from_object(obj.evaluated_get(dg))
    except (RuntimeError, ReferenceError, TypeError):
        return None
    try:
        nv, ne = len(me.vertices), len(me.edges)
        if nv == 0 or ne == 0 or ne > 400000:
            return None
        co = np.empty(nv * 3, dtype=np.float32)
        me.vertices.foreach_get('co', co)
        ed = np.empty(ne * 2, dtype=np.int32)
        me.edges.foreach_get('vertices', ed)
    finally:
        bpy.data.meshes.remove(me)
    mw = np.array(obj.matrix_world, dtype=np.float64)
    wco = co.reshape(-1, 3).astype(np.float64) @ mw[:3, :3].T + mw[:3, 3]
    return wco, ed.reshape(-1, 2)


def edge_chains(wco, edges, picked):
    """Assemble les arêtes choisies en chaînes continues : [(points Vector, fermée)]."""
    key = {}
    pts = []
    vid = {}

    def vkey(i):
        k = tuple(np.round(wco[i], 6))
        if k not in key:
            key[k] = len(pts)
            pts.append(Vector(wco[i]))
        vid[i] = key[k]
        return key[k]
    segs = []
    for e in picked:
        a, b = vkey(int(edges[e][0])), vkey(int(edges[e][1]))
        if a != b:
            segs.append((a, b))
    adj = {}
    for si, (a, b) in enumerate(segs):
        adj.setdefault(a, []).append(si)
        adj.setdefault(b, []).append(si)
    used = [False] * len(segs)
    out = []

    def walk(start, first):
        path = [start]
        cur, si = start, first
        while si is not None and not used[si]:
            used[si] = True
            a, b = segs[si]
            nxt = b if a == cur else a
            path.append(nxt)
            cur = nxt
            more = [x for x in adj[cur] if not used[x]]
            si = more[0] if (len(adj[cur]) == 2 and more) else None
        return path
    for v, lst in adj.items():          # chaînes ouvertes : on part des extrémités
        if len(lst) != 2:
            for si in lst:
                if not used[si]:
                    out.append((walk(v, si), False))
    for si in range(len(segs)):         # le reste : boucles fermées
        if not used[si]:
            path = walk(segs[si][0], si)
            out.append((path, path[0] == path[-1]))
    res = []
    for path, closed in out:
        P = [pts[i] for i in path]
        if closed and len(P) > 1 and (P[0] - P[-1]).length < 1e-9:
            P = P[:-1]
        clean = [P[0]]
        for q in P[1:]:
            if (q - clean[-1]).length > 1e-9:
                clean.append(q)
        if closed and len(clean) > 2 and (clean[0] - clean[-1]).length < 1e-9:
            clean.pop()
        if len(clean) >= 2:
            res.append((clean, closed and len(clean) >= 3))
    return res


def chain_normal(P, closed, fallback):
    """Normale du plan d'une chaîne (méthode de Newell) ; `fallback` si elle est alignée."""
    n = Vector()
    m = len(P)
    for i in range(m):
        a, b = P[i], P[(i + 1) % m]
        n += a.cross(b)
    if n.length < 1e-9 * max(1.0, sum((q - P[0]).length for q in P)):
        return fallback.copy()
    n.normalize()
    if n.dot(fallback) < 0:
        n.negate()
    return n


def offset_polyline(P, closed, n, d):
    """Décale la chaîne P (plan de normale n) de d vers la gauche du sens de parcours (angles en onglet)."""
    m = len(P)
    cnt = m if closed else m - 1
    L = []
    for i in range(cnt):
        t = P[(i + 1) % m] - P[i]
        t.normalize()
        L.append(n.cross(t))
    out = []
    for i in range(m):
        if not closed and i == 0:
            out.append(P[0] + L[0] * d)
        elif not closed and i == m - 1:
            out.append(P[i] + L[-1] * d)
        else:
            l0, l1 = L[(i - 1) % cnt], L[i % cnt]
            den = 1.0 + l0.dot(l1)
            if den < 0.1:
                out.append(P[i] + l0 * d)
                out.append(P[i] + l1 * d)
            else:
                out.append(P[i] + (l0 + l1) * (d / den))
    return out


def nearest_on_chain(P, closed, q):
    """(indice du segment, point le plus proche) de q sur la chaîne."""
    m = len(P)
    cnt = m if closed else m - 1
    best = None
    for i in range(cnt):
        a, b = P[i], P[(i + 1) % m]
        ab = b - a
        t = max(0.0, min(1.0, (q - a).dot(ab) / ab.dot(ab))) if ab.length_squared > 1e-18 else 0.0
        c = a + ab * t
        d2 = (q - c).length_squared
        if best is None or d2 < best[0]:
            best = (d2, i, c)
    return best[1], best[2]


class DESSIN_OT_offset_edge(DessinEdgeRound):
    bl_idname = "dessin.offset_edge"
    bl_label = "Offset Edge"
    bl_description = ("Parallel copy of edges or curves: click the edges (or a curve) or drag a box, Enter, then move the mouse "
                      "to choose the side and type the distance. In Edit mode the selected edges are used")

    TITLE = "Offset Edge"
    NUMFIELDS = 1
    STATE = OFFSET_STATE
    CHAMFER = True      # pas de segments / flèches ↑ ↓

    # ---- sélection : meshes et courbes (une courbe entière à la fois) ----
    def candidates(self, context):
        # tous les objets visibles (pas seulement ceux déjà sélectionnés) : on peut piocher plusieurs formes à la zone
        return [o for o in context.view_layer.objects if o.type in {'MESH', 'CURVE'} and o.visible_get()]

    def geometry(self, obj):
        if obj.name in self.geo:
            return self.geo[obj.name]
        g = curve_edge_geometry(obj) if obj.type == 'CURVE' else mesh_edge_geometry(obj)
        self.geo[obj.name] = g
        return g

    def all_edges(self, obj):
        g = self.geometry(obj)
        return range(len(g[1])) if g is not None else range(0)

    def click(self, context):
        if self.phase == 'radius':
            self.finish_shape(context)
            return
        hit = self.pick_edge(context)
        if hit is None:
            return
        obj, i = hit
        s = self.sel.setdefault(obj.name, set())
        if obj.type == 'CURVE':
            if s:
                s.clear()
            else:
                s.update(self.all_edges(obj))
        elif i in s:
            s.discard(i)
        else:
            s.add(i)
        self.refresh(context)

    def box_select(self, context, remove):
        before = {k: len(v) for k, v in self.sel.items()}
        n = super().box_select(context, remove)
        for name, s in self.sel.items():
            obj = bpy.data.objects.get(name)
            if obj is None or obj.type != 'CURVE':
                continue
            if remove and len(s) < before.get(name, 0):
                s.clear()
            elif not remove and len(s) > before.get(name, 0):
                s.update(self.all_edges(obj))
        return n

    # ---- phase « distance » ----
    def begin_radius(self, context):
        if not self.total_selected():
            return False
        self.phase = 'radius'
        self.anchor = self.cur.copy() if self.cur is not None else Vector()
        self.points = [self.anchor.copy()]
        self.typed = ['', '', '']
        self.refresh(context)
        return True

    def prompt(self):
        if self.phase == 'pick':
            return (f"click the edges / a curve or drag a box ({self.total_selected()} selected), then Enter   "
                    "[box to the right: inside, to the left: touching, Ctrl: deselect]")
        return "move the mouse to choose the side and the distance, or type the distance   (click / Enter: confirm)"

    def source_chains(self):
        """[(nom objet, points, fermée)] des arêtes choisies."""
        out = []
        for name, idx in self.sel.items():
            obj = bpy.data.objects.get(name)
            g = self.geometry(obj) if obj is not None else None
            if g is None or not idx:
                continue
            for P, closed in edge_chains(g[0], g[1], sorted(idx)):
                out.append((name, P, closed))
        return out

    def offset_chains(self):
        """[(nom objet, points décalés, fermée)] d'après la souris (côté) et la saisie (distance)."""
        fallback = plane_axes(self.axis)[2]
        t = self.typed_value(0)
        res = []
        for name, P, closed in self.source_chains():
            n = chain_normal(P, closed, fallback)
            seg, c = nearest_on_chain(P, closed, self.cur)
            m = len(P)
            tvec = P[(seg + 1) % m] - P[seg]
            if tvec.length < 1e-12:
                continue
            tvec.normalize()
            left = n.cross(tvec)
            v = self.cur - c
            v -= n * v.dot(n)
            side = 1.0 if v.dot(left) >= 0 else -1.0
            d = abs(t) if t is not None else v.length
            if d < 1e-9:
                continue
            Q = offset_polyline(P, closed, n, side * d)
            res.append((name, Q, closed, d))
        return res

    def compute(self):
        if self.phase == 'pick':
            self.preview_extra = []
            return super().compute()
        self.hilite = []
        self.preview_extra = []
        if self.cur is None:
            return [], [], "", None
        res = self.offset_chains()
        for _nm, Q, closed, _d in res:
            self.preview_extra.append(Q + [Q[0]] if closed else Q)
        guides = self.edge_lines((nm, s) for nm, s in self.sel.items())[:3000]
        info = f"distance {self.fmt(res[0][3])}" if res else "distance 0"
        return [], guides, info, ("offset", res) if res else None

    def apply_preview(self):
        pass

    def restore_all(self):
        self.geo = {}

    def finish_shape(self, context):
        if self.phase != 'radius' or self.cur is None:
            return
        res = self.offset_chains()
        if not res:
            self.report({'WARNING'}, "Distance is zero")
            return
        self.STATE["dist"] = res[0][3]
        by_obj = {}
        for name, Q, closed, _d in res:
            by_obj.setdefault(name, []).append((Q, closed))
        for name, chains in by_obj.items():
            src = bpy.data.objects.get(name)
            if src is None:
                continue
            if src.type == 'CURVE':
                build_polylines(context, "Offset", chains)
            elif self.reenter_edit:
                self.append_edges(src, chains)
            else:
                build_edge_object(context, "Offset", chains)
        self.committed = True
        self.finished = True

    @staticmethod
    def append_edges(obj, chains):
        """Ajoute les chaînes (coordonnées monde) au maillage de l'objet (en mode Objet : on retourne ensuite en Édition)."""
        inv = obj.matrix_world.inverted()
        bm = bmesh.new()
        bm.from_mesh(obj.data)
        for Q, closed in chains:
            vs = [bm.verts.new(inv @ q) for q in Q]
            pairs = list(zip(vs, vs[1:])) + ([(vs[-1], vs[0])] if closed and len(vs) > 2 else [])
            for a, b in pairs:
                try:
                    bm.edges.new((a, b))
                except ValueError:
                    pass
        bm.to_mesh(obj.data)
        bm.free()
        obj.data.update()


def build_polylines(context, name, chains):
    cu = bpy.data.curves.new(name, 'CURVE')
    cu.dimensions = '3D'
    for Q, closed in chains:
        sp = cu.splines.new('POLY')
        sp.points.add(len(Q) - 1)
        for pt, q in zip(sp.points, Q):
            pt.co = (q.x, q.y, q.z, 1.0)
        sp.use_cyclic_u = closed
    return _link_object(context, name, cu)


def build_edge_object(context, name, chains):
    verts, edges = [], []
    for Q, closed in chains:
        base = len(verts)
        verts += [tuple(q) for q in Q]
        edges += [(base + i, base + i + 1) for i in range(len(Q) - 1)]
        if closed and len(Q) > 2:
            edges.append((base + len(Q) - 1, base))
    me = bpy.data.meshes.new(name)
    me.from_pydata(verts, edges, [])
    me.update()
    return _link_object(context, name, me)


# --------------------------------------------------------------------------
# Booléens : Union, Difference, Intersection, Split
# --------------------------------------------------------------------------

def _link_like(obj, like):
    colls = list(like.users_collection) or [bpy.context.view_layer.active_layer_collection.collection]
    for c in colls:
        c.objects.link(obj)


def boolean_mesh(base, operands, operation):
    """Maillage résultant de `base` combiné (UNION / DIFFERENCE / INTERSECT) avec `operands`, dans l'espace local de base."""
    mods = []
    for o in operands:
        m = base.modifiers.new("cad_bool", 'BOOLEAN')
        m.operation = operation
        m.operand_type = 'OBJECT'
        m.object = o
        m.solver = 'EXACT'
        mods.append(m)
    try:
        bpy.context.view_layer.update()
        dg = bpy.context.evaluated_depsgraph_get()
        ev = base.evaluated_get(dg)
        me = bpy.data.meshes.new_from_object(ev, preserve_all_data_layers=True, depsgraph=dg)
    finally:
        for m in mods:
            base.modifiers.remove(m)
    return me


def _temp_union(objs):
    """Objet temporaire = union de plusieurs objets (ou l'objet lui-même s'il est seul). (objet, est_temporaire)."""
    if len(objs) == 1:
        return objs[0], False
    me = boolean_mesh(objs[0], objs[1:], 'UNION')
    tmp = bpy.data.objects.new("cad_tmp", me)
    tmp.matrix_world = objs[0].matrix_world.copy()
    _link_like(tmp, objs[0])
    return tmp, True


def _drop_temp(tmp, is_tmp):
    if is_tmp and tmp is not None:
        me = tmp.data
        bpy.data.objects.remove(tmp)
        if me.users == 0:
            bpy.data.meshes.remove(me)


def _discard_inputs(objs):
    for o in objs:
        try:
            me = o.data
            bpy.data.objects.remove(o)
            if me is not None and me.users == 0:
                bpy.data.meshes.remove(me)
        except (ReferenceError, RuntimeError):
            pass


def run_boolean(kind, A, B, delete_inputs=True):
    """Exécute l'opération ; retourne (objets créés, message d'erreur)."""
    results = []          # (nom, maillage, matrice, objet modèle pour la collection)
    tmpA = tmpB = None
    isA = isB = False
    try:
        if kind == 'UNION':
            if len(A) < 2:
                return [], "Select at least two objects to join"
            me = boolean_mesh(A[0], A[1:], 'UNION')
            results.append((A[0].name, me, A[0].matrix_world.copy(), A[0]))
            used_B = []
        else:
            if not A or not B:
                return [], "Select the objects on both steps"
            tmpB, isB = _temp_union(B)
            if kind == 'DIFFERENCE':
                for a in A:
                    results.append((a.name, boolean_mesh(a, [tmpB], 'DIFFERENCE'), a.matrix_world.copy(), a))
            elif kind == 'INTERSECT':
                tmpA, isA = _temp_union(A)
                results.append((A[0].name, boolean_mesh(tmpA, [tmpB], 'INTERSECT'), tmpA.matrix_world.copy(), A[0]))
            elif kind == 'SPLIT':
                for a in A:
                    inside = boolean_mesh(a, [tmpB], 'INTERSECT')
                    outside = boolean_mesh(a, [tmpB], 'DIFFERENCE')
                    results.append((a.name, outside, a.matrix_world.copy(), a))
                    results.append((a.name, inside, a.matrix_world.copy(), a))
            used_B = B
    finally:
        _drop_temp(tmpA, isA)
        _drop_temp(tmpB, isB)
    good = []
    for name, me, mw, like in results:
        if len(me.polygons) == 0:
            bpy.data.meshes.remove(me)
        else:
            good.append((name, me, mw, like))
    if not good:
        return [], "No result: the objects do not overlap"
    colls = {id(like): list(like.users_collection) for _n, _m, _w, like in good}
    if kind == 'SPLIT':
        _discard_inputs(list(A))          # les pièces remplacent les objets coupés ; les objets de coupe restent
    elif delete_inputs:
        _discard_inputs(list(A) + list(used_B))
    created = []
    for name, me, mw, like in good:
        obj = bpy.data.objects.new(name, me)
        obj.matrix_world = mw
        cs = colls.get(id(like)) or [bpy.context.view_layer.active_layer_collection.collection]
        for c in cs:
            c.objects.link(obj)
        created.append(obj)
    return created, ""


class DessinBoolean(DessinBase):
    """Base des outils booléens (classe non enregistrée) : sélection par clics, Entrée valide chaque étape."""

    NEEDED = 2
    NUMFIELDS = 0
    EDIT_OK = False
    LOCK_OK = False
    KIND = 'UNION'
    TWO_SETS = False
    STEP_TEXT = ("select the objects to join",)
    DELETE_DEFAULT = True

    def invoke(self, context, event):
        self.stage = 0
        self.setA = []
        self.delete_inputs = self.DELETE_DEFAULT
        self.committed = False
        self._ev = event
        return super().invoke(context, event)

    def selected_meshes(self, context):
        out = []
        for o in context.view_layer.objects:
            try:
                if o.type == 'MESH' and o.select_get() and o.visible_get():
                    out.append(o)
            except RuntimeError:
                pass
        return out

    def prompt(self):
        return ""

    def refresh(self, context):
        n = len(self.selected_meshes(context))
        txt = (f"{self.TITLE} : {self.STEP_TEXT[min(self.stage, len(self.STEP_TEXT) - 1)]}   "
               f"(click: select / deselect, A: all)   |   {n} selected   |   "
               f"Enter/Space: confirm   D: delete input = {'yes' if self.delete_inputs else 'no'}   Esc: cancel")
        try:
            set_prompt(self.area, txt)
            self.area.tag_redraw()
        except ReferenceError:
            pass

    def update_cursor(self, context, event):
        self._ev = event
        self.snap_screen = None
        self.snap_kind = None
        self.cur = Vector()
        self.refresh(context)

    def click(self, context):
        ev = self._ev
        region = find_window_region(self.area, ev.mouse_x, ev.mouse_y)
        if region is None:
            return
        try:
            with context.temp_override(area=self.area, region=region):
                bpy.ops.view3d.select(location=(ev.mouse_x - region.x, ev.mouse_y - region.y), toggle=True)
        except (RuntimeError, TypeError):
            pass
        self.refresh(context)

    def select_all_meshes(self, context):
        for o in context.view_layer.objects:
            try:
                if o.type == 'MESH' and o.visible_get():
                    o.select_set(True)
            except RuntimeError:
                pass

    def confirm(self, context):
        sel = self.selected_meshes(context)
        if self.TWO_SETS and self.stage == 0:
            if not sel:
                self.report({'WARNING'}, "Select at least one object")
                return {'RUNNING_MODAL'}
            self.setA = [o.name for o in sel]
            for o in context.view_layer.objects:
                try:
                    o.select_set(False)
                except RuntimeError:
                    pass
            self.stage = 1
            self.refresh(context)
            return {'RUNNING_MODAL'}
        names = set(self.setA)
        A = [bpy.data.objects[n] for n in self.setA if n in bpy.data.objects] if self.TWO_SETS else sel
        B = [o for o in sel if o.name not in names] if self.TWO_SETS else []
        if not self.TWO_SETS and len(A) < 2:
            self.report({'WARNING'}, "Select at least two objects")
            return {'RUNNING_MODAL'}
        if self.TWO_SETS and not B:
            self.report({'WARNING'}, "Select at least one object in this step")
            return {'RUNNING_MODAL'}
        created, err = run_boolean(self.KIND, A, B, self.delete_inputs)
        if err:
            self.report({'WARNING'}, err)
            return {'RUNNING_MODAL'}
        context.view_layer.update()
        for o in context.view_layer.objects:
            try:
                o.select_set(False)
            except (RuntimeError, AttributeError):
                pass
        for o in created:
            o.select_set(True)
        context.view_layer.objects.active = created[0]
        self.finished = True
        return self.exit(context)

    def modal(self, context, event):
        if self.area is None or context.area is None:
            self.cleanup(context)
            return {'CANCELLED'}
        if self.tool_id and self.tool_changed(context):
            self.cleanup(context)
            return {'CANCELLED', 'PASS_THROUGH'}
        et = event.type
        if et == 'TIMER':
            return {'PASS_THROUGH'}
        inside = (find_window_region(self.area, event.mouse_x, event.mouse_y) is not None
                  and not self.mouse_over_ui(event))
        if et in {'MOUSEMOVE', 'INBETWEEN_MOUSEMOVE'}:
            if inside:
                self.update_cursor(context, event)
                return {'RUNNING_MODAL'}
            return {'PASS_THROUGH'}
        if not inside:
            return {'PASS_THROUGH'}
        if et == 'LEFTMOUSE':
            if event.alt or event.oskey:
                return {'PASS_THROUGH'}
            if event.value == 'PRESS' and not event.ctrl:
                self._ev = event
                self.click(context)
            return {'RUNNING_MODAL'}
        if event.value != 'PRESS':
            return {'PASS_THROUGH'}
        if et == 'ESC':
            return self.exit(context)
        if et in {'RET', 'NUMPAD_ENTER', 'SPACE'}:
            return self.confirm(context)
        if et == 'A' and not (event.ctrl or event.alt or event.oskey):
            self.select_all_meshes(context)
            self.refresh(context)
            return {'RUNNING_MODAL'}
        if et == 'D' and not (event.ctrl or event.alt or event.oskey):
            self.delete_inputs = not self.delete_inputs
            self.refresh(context)
            return {'RUNNING_MODAL'}
        if et == 'TAB':
            return {'RUNNING_MODAL'}
        return {'PASS_THROUGH'}

    def after_finish(self, context):
        if self.tool_id:
            try:
                idle_tool()
            except (RuntimeError, TypeError):
                pass


