_EXT_CACHE = {"t": 0.0, "sig": None, "dir": None}


def extrude_direction(context):
    """Direction (monde) d'extrusion des faces / arêtes sélectionnées, ou None ; calculée au plus 4 fois par seconde."""
    now = time.monotonic()
    try:
        sig = tuple((o.name, o.data.total_face_sel, o.data.total_edge_sel, o.data.total_vert_sel)
                    for o in context.objects_in_mode_unique_data if o.type == 'MESH')
    except (AttributeError, ReferenceError):
        return None
    if sig == _EXT_CACHE["sig"] and now - _EXT_CACHE["t"] < 0.25:
        return _EXT_CACHE["dir"]
    dsum = Vector()
    for obj in context.objects_in_mode_unique_data:
        if obj.type != 'MESH':
            continue
        try:
            bm = bmesh.from_edit_mesh(obj.data)
        except ValueError:
            continue
        nm = obj.matrix_world.to_3x3().inverted_safe().transposed()
        faces = [f for f in bm.faces if f.select]
        if faces:
            for f in faces:
                dsum += (nm @ f.normal).normalized() * f.calc_area()
        else:
            for e in bm.edges:
                if e.select:
                    for f in e.link_faces:
                        dsum += (nm @ f.normal).normalized()
    out = dsum.normalized() if dsum.length > 1e-9 else Vector((0.0, 0.0, 1.0))
    _EXT_CACHE.update(t=now, sig=sig, dir=out)
    return out


def extrude_info(context):
    """(faces, arêtes) sélectionnées en mode édition (nombres), pour savoir si la poignée d'extrusion s'affiche."""
    nf = ne = 0
    try:
        for o in context.objects_in_mode_unique_data:
            if o.type == 'MESH':
                nf += o.data.total_face_sel
                ne += o.data.total_edge_sel
    except (AttributeError, ReferenceError):
        pass
    return nf, ne


class DESSIN_OT_gumball_extrude(GumballBase):
    bl_idname = "dessin.gumball_extrude"
    bl_label = "Extrude"
    bl_description = ("Extrudes the selected faces (or edges) along their normal: drag, or click without dragging, "
                      "type the distance and press Enter")

    NO_COPY = True
    kind = 'MOVE'
    axis = 0

    @classmethod
    def poll(cls, context):
        return context.mode == 'EDIT_MESH' and context.area is not None and context.area.type == 'VIEW_3D'

    def setup_selection(self, context):
        self.backups = []
        items = []
        dsum = Vector()
        pts = []
        for obj in context.objects_in_mode_unique_data:
            if obj.type != 'MESH':
                continue
            bm = bmesh.from_edit_mesh(obj.data)
            faces = [f for f in bm.faces if f.select]
            edges = [] if faces else [e for e in bm.edges if e.select]
            if not faces and not edges:
                continue
            nm = obj.matrix_world.to_3x3().inverted_safe().transposed()
            if faces:
                for f in faces:
                    dsum += (nm @ f.normal).normalized() * f.calc_area()
            else:
                for e in edges:
                    for f in e.link_faces:
                        dsum += (nm @ f.normal).normalized()
            tmp = bpy.data.meshes.new("dessin_extrude_backup")
            bm.to_mesh(tmp)                      # copie de secours (pour Échap)
            self.backups.append((obj, tmp))
            if faces:
                ret = bmesh.ops.extrude_face_region(bm, geom=faces)
            else:
                ret = bmesh.ops.extrude_edge_only(bm, edges=edges)
            geom = ret["geom"]
            new_verts = [g for g in geom if isinstance(g, bmesh.types.BMVert)]
            for v in bm.verts:
                v.select_set(False)
            for g in geom:
                g.select_set(True)
            bm.select_flush_mode()
            bm.verts.ensure_lookup_table()
            bm.verts.index_update()
            mw = np.array(obj.matrix_world, dtype=np.float64)
            co = np.array([tuple(v.co) for v in new_verts], dtype=np.float64)
            w0 = co @ mw[:3, :3].T + mw[:3, 3]
            items.append((obj, [v.index for v in new_verts], w0))
            pts.append(w0)
            bmesh.update_edit_mesh(obj.data, loop_triangles=True, destructive=True)
        if not items:
            return False
        if dsum.length < 1e-9:
            dsum = Vector((0.0, 0.0, 1.0))
        allp = np.vstack(pts)
        self.pivot = Vector((allp.min(axis=0) + allp.max(axis=0)) / 2.0)
        self.edit = True
        self.items = items
        self.dir = dsum.normalized()
        return True

    def drop_backups(self):
        for _o, tmp in self.backups:
            try:
                bpy.data.meshes.remove(tmp)
            except (ReferenceError, RuntimeError):
                pass
        self.backups = []

    def label(self):
        return f"Extrude: {self.value / self.unit_f:.3f} {self.unit_label}".strip()

    def cancel_all(self, context):
        for obj, tmp in self.backups:               # on revient au maillage d'avant l'extrusion
            try:
                bm = bmesh.from_edit_mesh(obj.data)
                bm.clear()
                bm.from_mesh(tmp)
                bmesh.update_edit_mesh(obj.data, loop_triangles=True, destructive=True)
            except (ReferenceError, RuntimeError, ValueError):
                pass
        self.drop_backups()
        self.finish_ui(context)
        return {'CANCELLED'}

    def commit(self, context):
        if abs(self.value) < 1e-9:                  # distance nulle : pas d'extrusion
            return self.cancel_all(context)
        self.drop_backups()
        self.finish_ui(context)
        return {'FINISHED'}


# --------------------------------------------------------------------------
# Offset Surface (objet) et Extrude (mode édition)
# --------------------------------------------------------------------------

def offset_coords(obj, dist):
    """(coordonnées locales d'origine, coordonnées décalées de dist monde le long des normales).
    Chaque sommet est placé à la distance dist de toutes les faces qui l'entourent (angles vifs respectés)."""
    me = obj.data
    nv, npoly = len(me.vertices), len(me.polygons)
    co = np.empty(nv * 3)
    me.vertices.foreach_get('co', co)
    co = co.reshape(-1, 3)
    fn = np.empty(npoly * 3)
    me.polygons.foreach_get('normal', fn)
    fn = fn.reshape(-1, 3)
    lt = np.empty(npoly, dtype=np.int64)
    me.polygons.foreach_get('loop_total', lt)
    lv = np.empty(len(me.loops), dtype=np.int64)
    me.loops.foreach_get('vertex_index', lv)
    M = np.array(obj.matrix_world.to_3x3(), dtype=np.float64)
    Minv = np.linalg.inv(M)
    fnw = fn @ Minv          # normale monde = (M^-1)^T n
    ln = np.linalg.norm(fnw, axis=1)
    fnw = fnw / np.where(ln > 1e-12, ln, 1.0)[:, None]
    N = fnw[np.repeat(np.arange(npoly), lt)]
    A = np.zeros((nv, 3, 3))
    b = np.zeros((nv, 3))
    np.add.at(A, lv, N[:, :, None] * N[:, None, :])
    np.add.at(b, lv, N)
    dw = (np.linalg.pinv(A, rcond=1e-3) @ b[:, :, None])[:, :, 0] * dist
    length = np.linalg.norm(dw, axis=1)
    cap = 4.0 * abs(dist)
    dw *= np.where(length > cap, cap / np.where(length > 1e-12, length, 1.0), 1.0)[:, None]
    return co, co + dw @ Minv.T


def offset_surface_mesh(obj, dist, solid, both=False):
    """Nouveau maillage : la surface de obj décalée de dist (signe = sens). solid : fermé en épaisseur ;
    both + solid : épaisseur centrée sur la surface (de -|dist| à +|dist|)."""
    me = obj.data
    if solid and both:
        co, newco = offset_coords(obj, abs(dist))
        _c, co = offset_coords(obj, -abs(dist))
        dist = abs(dist)
    else:
        co, newco = offset_coords(obj, dist)
    if not solid:
        out = me.copy()
        out.name = "Offset " + me.name
        out.vertices.foreach_set('co', newco.ravel())
        out.update()
        return out
    bm = bmesh.new()
    vo = [bm.verts.new(c) for c in co]
    vn = [bm.verts.new(c) for c in newco]
    outer, inner = (vn, vo) if dist >= 0 else (vo, vn)
    count = {}
    for p in me.polygons:
        vs = list(p.vertices)
        for k in range(len(vs)):
            a_, b_ = vs[k], vs[(k + 1) % len(vs)]
            count.setdefault((min(a_, b_), max(a_, b_)), []).append((a_, b_))
        try:
            f1 = bm.faces.new([outer[i] for i in vs])
            f2 = bm.faces.new([inner[i] for i in reversed(vs)])
            f1.material_index = f2.material_index = p.material_index
        except ValueError:
            pass
    for lst in count.values():
        if len(lst) != 1:
            continue
        a_, b_ = lst[0]
        quad = [vn[b_], vn[a_], vo[a_], vo[b_]] if dist >= 0 else [vo[b_], vo[a_], vn[a_], vn[b_]]
        try:
            bm.faces.new(quad)
        except ValueError:
            pass
    out = bpy.data.meshes.new("Offset " + me.name)
    bm.to_mesh(out)
    bm.free()
    for m in me.materials:
        out.materials.append(m)
    return out


def offset_arrows(targets, limit=8):
    """[(position monde, normale monde)] : quelques flèches réparties sur les plus grandes faces."""
    cands = []
    for obj in targets:
        me = obj.data
        n = len(me.polygons)
        if not n:
            continue
        areas = np.empty(n)
        me.polygons.foreach_get('area', areas)
        cen = np.empty(n * 3)
        me.polygons.foreach_get('center', cen)
        nor = np.empty(n * 3)
        me.polygons.foreach_get('normal', nor)
        cen, nor = cen.reshape(-1, 3), nor.reshape(-1, 3)
        idx = np.where(areas >= 0.3 * areas.max())[0]
        if len(idx) > 300:
            idx = idx[::len(idx) // 300 + 1]
        M = np.array(obj.matrix_world, dtype=np.float64)
        Mi = np.linalg.inv(M[:3, :3])
        pw = cen[idx] @ M[:3, :3].T + M[:3, 3]
        nw = nor[idx] @ Mi
        nw /= np.maximum(np.linalg.norm(nw, axis=1), 1e-12)[:, None]
        cands.extend(zip(pw, nw))
    if not cands:
        return []
    chosen = [0]
    P = np.array([c[0] for c in cands])
    dmin = np.linalg.norm(P - P[0], axis=1)
    while len(chosen) < min(limit, len(cands)):
        j = int(np.argmax(dmin))
        if dmin[j] < 1e-9:
            break
        chosen.append(j)
        dmin = np.minimum(dmin, np.linalg.norm(P - P[j], axis=1))
    return [(Vector(cands[j][0]), Vector(cands[j][1])) for j in chosen]


_OFFSET_ACTIVE = []


def back_to_idle():
    """Retour à Select / Move (Échap dans un outil de la barre)."""
    if not pref("auto_idle"):
        return
    for name in (IDLE_TOOL, IDLE_FALLBACK):
        try:
            bpy.ops.wm.tool_set_by_id(name=name)
            return
        except (RuntimeError, TypeError):
            continue


def draw_offset_cb(op):
    ctx = bpy.context
    try:
        if ctx.area != op.area or ctx.region_data is None:
            return
    except ReferenceError:
        return
    if op not in _OFFSET_ACTIVE:
        return
    rv3d, region = ctx.region_data, ctx.region
    shader = get_shader('2D')
    sc = px_scale()
    gpu.state.blend_set('ALPHA')
    both = op.both
    items = [(i, p, n * sg) for i, (p, n) in enumerate(op.arrows) for sg in ((1.0, -1.0) if both else (op.sign,))]
    for i, p, d in items:
        a = project_px(rv3d, region, p)
        b = project_px(rv3d, region, p + d * op.arrow_len)
        if a is None or b is None:
            continue
        hot = (i == op.hover)
        col = (1.0, 1.0, 0.4, 1.0) if hot else (1.0, 0.55, 0.1, 1.0)
        gpu.state.line_width_set((4.0 if hot else 2.5) * sc)
        shader.bind()
        shader.uniform_float("color", col)
        batch_for_shader(shader, 'LINES', {"pos": [tuple(a), tuple(b)]}).draw(shader)
        v = b - a
        if v.length > 2.0:
            v.normalize()
            h = 11.0 * sc
            perp = Vector((-v.y, v.x))
            tri = [tuple(b + v * h * 0.6), tuple(b - v * h * 0.6 + perp * h * 0.55), tuple(b - v * h * 0.6 - perp * h * 0.55)]
            batch_for_shader(shader, 'TRIS', {"pos": tri}).draw(shader)
    gpu.state.line_width_set(1.0)
    gpu.state.blend_set('NONE')


class DESSIN_OT_offset_surface(bpy.types.Operator):
    bl_idname = "dessin.offset_surface"
    bl_label = "Offset Surface"
    bl_description = ("Offsets a surface (or a whole object) along its normals, like OffsetSrf: click it (or select it first), "
                      "click an arrow to flip the direction, type the distance, Enter or Space to validate")
    bl_options = {'REGISTER', 'UNDO'}

    @classmethod
    def poll(cls, context):
        return context.mode == 'OBJECT' and context.area is not None and context.area.type == 'VIEW_3D'

    def pick_targets(self, context, event):
        region = find_window_region(context.area, event.mouse_x, event.mouse_y)
        hit = None
        if region is not None:
            rv3d = context.area.spaces.active.region_3d
            m = Vector((event.mouse_x - region.x, event.mouse_y - region.y))
            try:
                ro = region_2d_to_origin_3d(region, rv3d, m)
                rv = region_2d_to_vector_3d(region, rv3d, m)
                ok, _loc, _nor, _idx, ob, _mat = context.scene.ray_cast(context.evaluated_depsgraph_get(), ro, rv)
                hit = ob if ok and ob is not None and ob.type == 'MESH' else None
            except (AttributeError, RuntimeError, TypeError):
                hit = None
        if hit is not None:
            return [hit]
        return [o for o in context.selected_objects if o.type == 'MESH' and len(o.data.polygons)]

    def header(self, context):
        unit = self.unit_label
        d = (self.typed + "_") if self.typed else f"{self.dist / self.unit_f:.4g}"
        txt = (f"Offset Surface: {d} {unit}   |   direction: {'normal' if self.sign > 0 else 'opposite'}   |   "
               f"S: solid {'ON' if self.solid else 'off'}   B: both sides {'ON' if self.both else 'off'}   X: delete input {'ON' if self.delete else 'off'}   "
               f"|   click an arrow (or F): flip   type the distance   Enter / Space: validate   Esc: cancel").strip()
        try:
            set_prompt(context.area, txt)
            context.area.tag_redraw()
        except (AttributeError, ReferenceError):
            pass

    def rebuild(self):
        self.remove_created()
        for obj in self.targets:
            sides = (1.0, -1.0) if (self.both and not self.solid) else (self.sign,)
            for sd in sides:
                me = offset_surface_mesh(obj, sd * self.dist, self.solid, self.both)
                new = bpy.data.objects.new("Offset " + obj.name, me)
                new.matrix_world = obj.matrix_world.copy()
                cols = obj.users_collection or [bpy.context.scene.collection]
                for c in cols:
                    c.objects.link(new)
                self.created.append((obj, new))

    def remove_created(self):
        for _old, new in self.created:
            try:
                me = new.data
                bpy.data.objects.remove(new)
                if me is not None and me.users == 0:
                    bpy.data.meshes.remove(me)
            except (ReferenceError, RuntimeError):
                pass
        self.created = []

    def abort(self):
        """Interrompt cette instance (une nouvelle commande démarre)."""
        self.remove_created()
        try:
            self.finish_ui(bpy.context)
        except (AttributeError, ReferenceError):
            pass

    def finish_ui(self, context):
        if self in _OFFSET_ACTIVE:
            _OFFSET_ACTIVE.remove(self)
        if self._handle is not None:
            try:
                bpy.types.SpaceView3D.draw_handler_remove(self._handle, 'WINDOW')
            except (ValueError, RuntimeError):
                pass
            self._handle = None
        try:
            set_prompt(self.area, None)
            self.area.tag_redraw()
        except (AttributeError, ReferenceError):
            pass

    def invoke(self, context, event):
        self._handle = None
        self.targets = self.pick_targets(context, event)
        if not self.targets:
            self.report({'INFO'}, "Select a surface or an object to offset (or click it)")
            return {'CANCELLED', 'PASS_THROUGH'}
        st = context.scene.dessin
        self.area = context.area
        self.unit_f, self.unit_label = unit_info(context.scene)
        self.dist = max(st.offset_surf_dist, 1e-6)
        self.solid = st.offset_surf_solid
        self.both = st.offset_surf_both
        self.delete = st.offset_surf_delete
        self.sign = 1.0
        self.typed = ""
        self.hover = -1
        self.created = []
        for other in list(_OFFSET_ACTIVE):          # une seule instance à la fois (pas de flèches fantômes)
            other.abort()
        _OFFSET_ACTIVE.append(self)
        self.arrows = offset_arrows(self.targets)
        diag = 0.0
        for o in self.targets:
            dim = o.dimensions
            diag = max(diag, math.sqrt(dim.x ** 2 + dim.y ** 2 + dim.z ** 2))
        self.arrow_len = max(0.15 * diag, 1e-3)
        self.rebuild()
        self._handle = bpy.types.SpaceView3D.draw_handler_add(draw_offset_cb, (self,), 'WINDOW', 'POST_PIXEL')
        context.window_manager.modal_handler_add(self)
        self.header(context)
        return {'RUNNING_MODAL'}

    def release_refs(self):
        """Plus aucune référence vers des objets Blender une fois la commande terminée (l'annulation les invalide)."""
        self.created = []
        self.targets = []
        self.arrows = []

    def cancel_all(self, context):
        self.remove_created()
        self.finish_ui(context)
        self.release_refs()
        return {'CANCELLED'}

    def commit(self, context):
        if not self.created or self.dist < 1e-9:
            return self.cancel_all(context)
        st = context.scene.dessin
        st.offset_surf_dist = self.dist
        st.offset_surf_solid = self.solid
        st.offset_surf_both = self.both
        st.offset_surf_delete = self.delete
        for o in context.view_layer.objects:
            o.select_set(False)
        last = None
        for _old, new in self.created:
            new.select_set(True)
            last = new
        if self.delete:
            for old in self.targets:
                try:
                    bpy.data.objects.remove(old)
                except (ReferenceError, RuntimeError):
                    pass
        if last is not None:
            context.view_layer.objects.active = last
        self.finish_ui(context)
        self.release_refs()
        return {'FINISHED'}

    def arrow_under(self, context, event):
        region = find_window_region(context.area, event.mouse_x, event.mouse_y)
        if region is None:
            return -1
        rv3d = context.area.spaces.active.region_3d
        m = Vector((event.mouse_x - region.x, event.mouse_y - region.y))
        best, best_d = -1, 16.0 * px_scale()
        for i, (p, n) in enumerate(self.arrows):
            a = project_px(rv3d, region, p)
            b = project_px(rv3d, region, p + n * self.sign * self.arrow_len)
            if a is None or b is None:
                continue
            ab = b - a
            t = 0.0 if ab.length < 1e-6 else max(0.0, min(1.0, (m - a).dot(ab) / ab.length_squared))
            d = (m - (a + ab * t)).length
            if d < best_d:
                best, best_d = i, d
        return best

    def sync_settings(self, context):
        st = context.scene.dessin
        if (st.offset_surf_solid != self.solid or st.offset_surf_delete != self.delete
                or st.offset_surf_both != self.both
                or (not self.typed and abs(st.offset_surf_dist - self.dist) > 1e-9)):
            self.solid, self.delete, self.both = st.offset_surf_solid, st.offset_surf_delete, st.offset_surf_both
            if not self.typed:
                self.dist = max(st.offset_surf_dist, 1e-6)
            self.rebuild()
            self.header(context)

    def modal(self, context, event):
        et = event.type
        if self.area is None or context.area is None:
            return self.cancel_all(context)
        if et in {'Z', 'Y'} and event.value == 'PRESS' and (event.ctrl or event.oskey):
            # Annuler / rétablir pendant la commande : on libère nos objets AVANT que Blender ne les remplace (sinon plantage)
            self.remove_created()
            self.finish_ui(context)
            self.release_refs()
            return {'CANCELLED', 'PASS_THROUGH'}
        tid = DessinBase.active_tool_id(context)
        if tid is not None and tid != "dessin.offset_surface_tool":
            self.remove_created()
            self.finish_ui(context)
            return {'CANCELLED', 'PASS_THROUGH'}
        if et in {'MOUSEMOVE', 'INBETWEEN_MOUSEMOVE'}:
            h = self.arrow_under(context, event)
            if h != self.hover:
                self.hover = h
                context.area.tag_redraw()
            self.sync_settings(context)
            return {'PASS_THROUGH'}
        if find_window_region(context.area, event.mouse_x, event.mouse_y) is None or area_over_ui(context.area, event.mouse_x, event.mouse_y):
            return {'PASS_THROUGH'}
        if event.value != 'PRESS':
            return {'RUNNING_MODAL'} if et == 'LEFTMOUSE' else {'PASS_THROUGH'}
        if et == 'ESC':
            r = self.cancel_all(context)
            back_to_idle()
            return r
        if et in {'RET', 'NUMPAD_ENTER', 'SPACE'}:
            return self.commit(context)
        if et == 'LEFTMOUSE':
            if event.alt or event.oskey:
                return {'PASS_THROUGH'}
            if self.arrow_under(context, event) >= 0:
                self.sign = -self.sign
                self.rebuild()
                self.header(context)
                context.area.tag_redraw()
            return {'RUNNING_MODAL'}
        changed = False
        if et == 'F' and not event.ctrl:
            self.sign = -self.sign
            changed = True
        elif et == 'S' and not (event.ctrl or event.alt):
            context.scene.dessin.offset_surf_solid = self.solid = not self.solid
            changed = True
        elif et == 'B' and not (event.ctrl or event.alt):
            context.scene.dessin.offset_surf_both = self.both = not self.both
            changed = True
        elif et == 'X' and not (event.ctrl or event.alt):
            context.scene.dessin.offset_surf_delete = self.delete = not self.delete
        elif et == 'BACK_SPACE':
            self.typed = self.typed[:-1]
            changed = True
        elif event.unicode and event.unicode in "0123456789.,-" and not (event.ctrl or event.alt):
            ch = "." if event.unicode == "," else event.unicode
            if ch == '-':
                self.sign = -self.sign
            else:
                self.typed += ch
            changed = True
        else:
            return {'PASS_THROUGH'}
        if self.typed:
            try:
                self.dist = max(float(self.typed) * self.unit_f, 1e-6)
            except ValueError:
                pass
        if changed:
            self.rebuild()
        self.header(context)
        context.area.tag_redraw()
        return {'RUNNING_MODAL'}


class DESSIN_OT_extrude(GumballBase):
    bl_idname = "dessin.extrude"
    bl_label = "Extrude"
    bl_description = ("Extrudes the selected faces (or edges) along their normal: click, move the mouse (or type the "
                      "distance) and click / Enter / Space to validate")

    kind = 'MOVE'
    axis = 0

    NO_COPY = True
    setup_selection = DESSIN_OT_gumball_extrude.setup_selection
    drop_backups = DESSIN_OT_gumball_extrude.drop_backups
    label = DESSIN_OT_gumball_extrude.label
    cancel_all = DESSIN_OT_gumball_extrude.cancel_all
    commit = DESSIN_OT_gumball_extrude.commit

    @classmethod
    def poll(cls, context):
        return context.mode == 'EDIT_MESH' and context.area is not None and context.area.type == 'VIEW_3D'

    def header(self, context):
        if self.mode == 'type':
            txt = f"{self.label()}   |   type the distance: {self.typed or '_'} {self.unit_label}   |   Enter / Space / click: apply   Esc: cancel"
        else:
            txt = f"{self.label()}   |   move the mouse, or type the distance   |   click / Enter / Space: apply   Esc: cancel"
        try:
            set_prompt(context.area, txt)
        except (AttributeError, ReferenceError):
            pass

    def invoke(self, context, event):
        if context.region is None or context.region_data is None:
            return {'CANCELLED', 'PASS_THROUGH'}
        if not self.setup_selection(context):
            self.report({'INFO'}, "Select faces or edges to extrude")
            return {'CANCELLED', 'PASS_THROUGH'}
        self.bu = self.dir.orthogonal().normalized()
        self.bv = self.dir.cross(self.bu)
        self.unit_f, self.unit_label = unit_info(context.scene)
        self.press = self.mouse(context, event)
        self.mode = 'follow'
        self.typed = ''
        self.uniform = False
        self.value = 0.0
        self.acc = 0.0
        s0 = self.sample(context, event)
        if s0 is None:
            return self.cancel_all(context)
        self.ref = s0
        self.last = s0
        context.window_manager.modal_handler_add(self)
        self.header(context)
        return {'RUNNING_MODAL'}

    def modal(self, context, event):
        et = event.type
        if et in {'MOUSEMOVE', 'INBETWEEN_MOUSEMOVE'}:
            if self.mode == 'follow':
                self.value = self.value_from_sample(self.sample(context, event), event.shift)
                self.apply(self.value)
                self.header(context)
            return {'RUNNING_MODAL'}
        if et == 'LEFTMOUSE':
            if event.alt or event.oskey:
                return {'PASS_THROUGH'}
            if event.value == 'PRESS':
                return self.commit(context)
            if event.value == 'RELEASE' and (self.mouse(context, event) - self.press).length > 5.0 * px_scale():
                return self.commit(context)     # on a glissé : le relâchement valide
            return {'RUNNING_MODAL'}
        if event.value == 'PRESS':
            if et in {'ESC', 'RIGHTMOUSE'}:
                r = self.cancel_all(context)
                if et == 'ESC':
                    back_to_idle()
                return r
            if et in {'RET', 'NUMPAD_ENTER', 'SPACE'}:
                return self.commit(context)
            if et == 'BACK_SPACE' and self.typed:
                self.typed = self.typed[:-1]
            elif event.unicode and event.unicode in "0123456789.,-" and not (event.ctrl or event.alt):
                ch = "." if event.unicode == "," else event.unicode
                if ch == '-':
                    self.typed = self.typed[1:] if self.typed.startswith('-') else '-' + self.typed
                else:
                    self.typed += ch
            else:
                return {'PASS_THROUGH'}
            self.mode = 'type'
            self.value = self.typed_value()
            self.apply(self.value)
            self.header(context)
            return {'RUNNING_MODAL'}
        return {'PASS_THROUGH'}


# --------------------------------------------------------------------------
# Trim : supprime la partie d'un tracé comprise entre deux intersections avec les courbes de coupe
# --------------------------------------------------------------------------

def is_xline(obj):
    """Ligne de construction (très longue) : à ignorer dans les calculs de tolérance liés à la taille de la scène."""
    try:
        return bool(obj.get("cad_xline")) or (obj.get("cad_noGrab") and obj.name.startswith("Construction Line"))
    except (ReferenceError, AttributeError):
        return False


def curve_wire_direct(obj):
    """Contour d'une courbe POLY / Bézier sans modificateur, calculé directement depuis ses points (sans passer par le graphe
    d'évaluation) : arcs et cercles échantillonnés finement, bevel et extrusion sans effet. None si la courbe n'est pas de ce type."""
    cu = obj.data
    if obj.modifiers or any(sp.type not in {'POLY', 'BEZIER'} for sp in cu.splines):
        return None
    mw = np.array(obj.matrix_world, dtype=np.float64)
    flat = cu.dimensions == '2D'
    n_seg = max(16, 2 * int(cu.resolution_u))
    verts, edges = [], []
    ts = np.linspace(0.0, 1.0, n_seg + 1)[1:]
    for sp in cu.splines:
        if sp.type == 'POLY':
            P = np.array([tuple(q.co[:3]) for q in sp.points], dtype=np.float64).reshape(-1, 3)
        else:
            bp = sp.bezier_points
            m = len(bp)
            co = np.array([tuple(q.co) for q in bp], dtype=np.float64).reshape(-1, 3)
            hl = np.array([tuple(q.handle_left) for q in bp], dtype=np.float64).reshape(-1, 3)
            hr = np.array([tuple(q.handle_right) for q in bp], dtype=np.float64).reshape(-1, 3)
            P_list = [co[0]]
            last = m if sp.use_cyclic_u else m - 1
            for i in range(last):
                j = (i + 1) % m
                p0, p1, p2, p3 = co[i], hr[i], hl[j], co[j]
                d = p3 - p0
                dd = float(d @ d)
                straight = dd < 1e-24 or (np.linalg.norm(np.cross(p1 - p0, d)) <= 1e-7 * dd
                                          and np.linalg.norm(np.cross(p2 - p0, d)) <= 1e-7 * dd)
                if straight:
                    P_list.append(p3)
                else:
                    t = ts[:, None]
                    B = ((1 - t) ** 3) * p0 + 3 * ((1 - t) ** 2) * t * p1 + 3 * (1 - t) * t * t * p2 + (t ** 3) * p3
                    P_list.extend(B)
            P = np.array(P_list, dtype=np.float64)
            if sp.use_cyclic_u and len(P) > 1:
                P = P[:-1]                 # le dernier point retombe sur le premier
        if len(P) < 2:
            continue
        if flat:
            P = P.copy()
            P[:, 2] = 0.0
        W = P @ mw[:3, :3].T + mw[:3, 3]
        base = len(verts)
        verts.extend(Vector(tuple(w)) for w in W)
        k = len(W)
        edges.extend((base + i, base + i + 1) for i in range(k - 1))
        if sp.use_cyclic_u and k > 2:
            edges.append((base + k - 1, base))
    return (verts, edges) if edges else None


def wire_graph(obj, depsgraph):
    """(sommets monde [Vector], arêtes [(i, j)]) d'un contour (maillage sans face ou courbe), ou None."""
    if obj.type == 'MESH':
        me = obj.data
        if len(me.polygons) or not len(me.edges):
            return None
        mw = obj.matrix_world
        verts = [mw @ v.co for v in me.vertices]
        edges = [tuple(e.vertices) for e in me.edges]
        return verts, edges
    if obj.type == 'CURVE' and "dessin_cotation" not in obj.keys() and len(obj.data.splines):
        cu = obj.data
        direct_res = curve_wire_direct(obj)
        if direct_res is not None:
            return direct_res
        tmp = None
        try:
            if cu.bevel_depth != 0.0 or cu.extrude != 0.0 or cu.bevel_object is not None:
                # courbe épaissie (bevel / extrusion) : la version évaluée a déjà la section, la remettre à zéro ne la recalcule pas.
                # On évalue une copie sans épaisseur : le fil de la courbe, une arête par segment.
                tmp = obj.copy()
                tmp.data = cu.copy()
                tmp.data.bevel_depth = 0.0
                tmp.data.extrude = 0.0
                tmp.data.bevel_object = None
                tmp.data.taper_object = None
                bpy.context.scene.collection.objects.link(tmp)
                depsgraph = bpy.context.evaluated_depsgraph_get()
                src = tmp
            else:
                src = obj
            ev = src.evaluated_get(depsgraph)
            me = ev.to_mesh()
            mw = obj.matrix_world
            verts = [mw @ v.co for v in me.vertices]
            edges = [tuple(e.vertices) for e in me.edges]
            ev.to_mesh_clear()
        finally:
            if tmp is not None:
                data = tmp.data
                bpy.data.objects.remove(tmp)
                bpy.data.curves.remove(data)
        return (verts, edges) if edges else None
    return None


def wire_chain(edges, e0):
    """Chaîne d'arêtes autour de l'arête e0 (on s'arrête aux extrémités et aux carrefours).
    Retourne (sommets ordonnés, arêtes ordonnées, fermée, position de e0 dans la chaîne)."""
    adj = {}
    for k, (a, b) in enumerate(edges):
        adj.setdefault(a, []).append(k)
        adj.setdefault(b, []).append(k)
    a0, b0 = edges[e0]
    vs, es = [a0, b0], [e0]
    seen = {e0}
    closed = False
    cur_v, cur_e = b0, e0
    while len(adj[cur_v]) == 2:
        nxt = [k for k in adj[cur_v] if k != cur_e]
        if not nxt:
            break
        k = nxt[0]
        if k in seen:
            closed = True
            break
        seen.add(k)
        a, b = edges[k]
        v = b if a == cur_v else a
        es.append(k)
        vs.append(v)
        cur_v, cur_e = v, k
    if closed:
        vs.pop()               # le dernier sommet est le premier
        return vs, es, True, 0
    cur_v, cur_e = a0, e0
    back_v, back_e = [], []
    while len(adj[cur_v]) == 2:
        nxt = [k for k in adj[cur_v] if k != cur_e]
        if not nxt or nxt[0] in seen:
            break
        k = nxt[0]
        seen.add(k)
        a, b = edges[k]
        v = b if a == cur_v else a
        back_e.append(k)
        back_v.append(v)
        cur_v, cur_e = v, k
    vs = back_v[::-1] + vs
    es = back_e[::-1] + es
    return vs, es, False, len(back_e)


def trim_params(P0, P1, Q0, Q1, tol):
    """Paramètres s (sur P0->P1) des intersections avec les segments Q0->Q1 (tableaux (n,3)) à tol près."""
    d1 = P1 - P0
    a = float(d1 @ d1)
    if a < 1e-18 or len(Q0) == 0:
        return []
    d2 = Q1 - Q0
    r = P0 - Q0
    e = np.einsum('ij,ij->i', d2, d2)
    b = d2 @ d1
    c = float(d1 @ r.T) if False else r @ d1
    f = np.einsum('ij,ij->i', d2, r)
    den = a * e - b * b
    ok = (den > 1e-12 * a * np.maximum(e, 1e-18)) & (e > 1e-18)
    den_s = np.where(ok, den, 1.0)
    s = (b * f - c * e) / den_s
    t = (a * f - b * c) / den_s
    eps_s = tol / math.sqrt(a)
    eps_t = tol / np.sqrt(np.maximum(e, 1e-18))
    ok &= (s >= -eps_s) & (s <= 1 + eps_s) & (t >= -eps_t) & (t <= 1 + eps_t)
    if not ok.any():
        return []
    s = np.clip(s, 0.0, 1.0)
    t = np.clip(t, 0.0, 1.0)
    pa = P0 + np.outer(s, d1)
    pb = Q0 + d2 * t[:, None]
    ok &= np.linalg.norm(pa - pb, axis=1) <= tol
    return [float(x) for x in s[ok]]


def trim_wire(verts, edges, e0, tcl, cutters, own_ids, tol, mesh_cut=None):
    """Retire la partie de la chaîne de e0 autour du point de clic (paramètre tcl le long de e0) entre deux intersections.
    cutters : (Q0, Q1, ids) segments de coupe (ids : (a, b) sommets du même objet, -1 sinon).
    Retourne (verts, edges) modifiés, ou None / un message si rien à couper."""
    vs, es, closed, k0 = wire_chain(edges, e0)
    n = len(es)
    Q0, Q1, qa, qb = cutters
    us = []
    for i in range(n):
        va, vb = vs[i], vs[(i + 1) % len(vs)] if closed else vs[i + 1]
        keep = ~((qa == va) | (qa == vb) | (qb == va) | (qb == vb))
        if own_ids is None:
            keep[:] = True
        for s in trim_params(np.array(verts[va], dtype=np.float64), np.array(verts[vb], dtype=np.float64), Q0[keep], Q1[keep], tol):
            us.append(i + s)
        if mesh_cut is not None:
            for s in mesh_cut(verts[va], verts[vb]):
                us.append(i + s)
    if not us:
        return "No intersection with the cutting curves"
    us.sort()
    merged = [us[0]]
    for u in us[1:]:
        if u - merged[-1] > 1e-7:
            merged.append(u)
    us = merged
    if closed and len(us) > 1 and us[-1] - us[0] > n - 1e-7:
        us.pop()
    uc = k0 + tcl
    if closed:
        if len(us) < 2:
            return "A closed curve needs two intersections to be trimmed"
        below = [u for u in us if u < uc - 1e-9]
        above = [u for u in us if u > uc + 1e-9]
        L = below[-1] if below else us[-1]
        U = above[0] if above else us[0]
    else:
        below = [u for u in us if u < uc - 1e-9]
        above = [u for u in us if u > uc + 1e-9]
        L = below[-1] if below else None
        U = above[0] if above else None
    new_verts = list(verts)

    def point_at(u):
        i = min(int(math.floor(u + 1e-12)), n - 1)
        fr = u - i
        va, vb = vs[i], vs[(i + 1) % len(vs)] if closed else vs[i + 1]
        return verts[va].lerp(verts[vb], fr)

    def vid(p):
        for j in set(vs):
            if (verts[j] - p).length <= tol:
                return j
        new_verts.append(p.copy())
        return len(new_verts) - 1

    def piece(items):
        ids = []
        for it in items:
            j = it if isinstance(it, int) else vid(it)
            if not ids or ids[-1] != j:
                ids.append(j)
        return ids

    pieces = []
    if closed:
        Lw = L + n if L < U else L
        items = [point_at(U)] + [vs[j % n] for j in range(int(math.floor(U + 1e-12)) + 1, int(math.floor(Lw + 1e-12)) + 1)] + [point_at(L)]
        pieces.append(piece(items))
    else:
        if L is not None:
            items = [vs[j] for j in range(0, int(math.floor(L + 1e-12)) + 1)] + [point_at(L)]
            pieces.append(piece(items))
        if U is not None:
            items = [point_at(U)] + [vs[j] for j in range(int(math.floor(U + 1e-12)) + 1, len(vs))]
            pieces.append(piece(items))
    chain_edges = set(es)
    new_edges = [e for k, e in enumerate(edges) if k not in chain_edges]
    for ids in pieces:
        for a, b in zip(ids, ids[1:]):
            new_edges.append((a, b))
    used = {v for e in new_edges for v in e}
    chain_v = set(vs)
    keep_v = [j for j in range(len(new_verts)) if j in used or j not in chain_v]
    remap = {old: k for k, old in enumerate(keep_v)}
    return [new_verts[j] for j in keep_v], [(remap[a], remap[b]) for a, b in new_edges]


def wire_paths(n_verts, edges):
    """Décompose un graphe d'arêtes en chemins [(sommets, fermé)]."""
    adj = {}
    for k, (a, b) in enumerate(edges):
        adj.setdefault(a, []).append((k, b))
        adj.setdefault(b, []).append((k, a))
    used = set()
    paths = []

    def walk(start, first):
        path = [start]
        cur, e = start, first
        while True:
            used.add(e[0])
            cur = e[1]
            path.append(cur)
            if len(adj[cur]) != 2:
                return path, False
            nxt = [x for x in adj[cur] if x[0] != e[0] and x[0] not in used]
            if not nxt:
                return path, cur == start
            e = nxt[0]
            if e[1] == start and len(adj[start]) == 2:
                used.add(e[0])
                return path, True

    for v in adj:
        if len(adj[v]) != 2:
            for e in adj[v]:
                if e[0] not in used:
                    paths.append(walk(v, e))
    for v in adj:
        for e in adj[v]:
            if e[0] not in used:
                path, closed = walk(v, e)
                if closed and path[0] == path[-1]:
                    path.pop()
                paths.append((path, closed))
    out = []
    for path, closed in paths:
        if closed and len(path) > 1 and path[0] == path[-1]:
            path = path[:-1]
        out.append((path, closed))
    return out


def circle_hints(obj):
    """Cercles / arcs de Bézier de la courbe obj (avant une coupe) : [(centre, rayon, normale, e1, e2)] en coordonnées monde."""
    out = []
    if obj.type != 'CURVE':
        return out
    try:
        g = curve_wire_direct(obj)
    except (RuntimeError, ReferenceError):
        return out
    if g is None:
        return out
    cu = obj.data
    if not any(sp.type == 'BEZIER' for sp in cu.splines):
        return out
    verts, edges = g
    V = np.array([tuple(v) for v in verts], dtype=np.float64)
    for path, closed in wire_paths(len(verts), edges):
        if len(path) < 6:
            continue
        P = V[path]
        fit = fit_circle_points(P)
        if fit is None:
            continue
        c, r, n, e1, e2 = fit
        if np.abs(np.linalg.norm(P - c, axis=1) - r).max() > 0.002 * r:
            continue                # un vrai arc de Bézier colle au cercle à moins de 0,03 % : un contour libre est laissé tel quel
        out.append((np.asarray(c, dtype=np.float64), float(r), np.asarray(n), np.asarray(e1), np.asarray(e2)))
    return out


def _arc_spline_from_path(cu, inv, P, closed, hint):
    """Écrit le tracé P (points monde ordonnés, sur le cercle `hint`) comme vrai arc / cercle de Bézier. False si les points
    ne tiennent pas sur ce cercle."""
    c, r, n, e1, e2 = hint
    d = P - c
    x, y, z = d @ e1, d @ e2, d @ n
    rad = np.hypot(x, y)
    if np.abs(rad - r).max() > 0.012 * r or np.abs(z).max() > 0.012 * r:
        return False
    ang = np.arctan2(y, x)
    steps = np.diff(ang)
    steps = (steps + math.pi) % (2 * math.pi) - math.pi
    if closed:
        sweep = TAU if steps.sum() >= 0 else -TAU
        t0 = float(ang[0])
    else:
        sweep = float(steps.sum())
        t0 = float(ang[0])
        if abs(sweep) < 1e-6:
            return False
    cc, u, v = Vector(tuple(c)), Vector(tuple(e1)), Vector(tuple(e2))
    data = arc_bezier_data(cc, u, v, r, t0, sweep)
    if closed:
        first_left = data[-1][1]
        data = data[:-1]
        data[0] = (data[0][0], first_left, data[0][2])
    sp = cu.splines.new('BEZIER')
    sp.bezier_points.add(len(data) - 1)
    for bp, (pos, hl, hr) in zip(sp.bezier_points, data):
        bp.handle_left_type = bp.handle_right_type = 'FREE'
        bp.co, bp.handle_left, bp.handle_right = inv @ pos, inv @ hl, inv @ hr
    sp.use_cyclic_u = bool(closed)
    return True


def write_wire(obj, verts, edges, hints=None):
    """Remplace le contour de obj par (verts monde, edges)."""
    inv = obj.matrix_world.inverted()
    local = [inv @ v for v in verts]
    if obj.type == 'MESH':
        me = obj.data
        me.clear_geometry()
        me.from_pydata([tuple(v) for v in local], edges, [])
        me.update()
        return
    cu = obj.data
    cu.splines.clear()
    for path, closed in wire_paths(len(local), edges):
        if len(path) < 2:
            continue
        if closed and len(path) > 1 and path[-1] == path[0]:
            path = path[:-1]
        if hints and len(path) >= 3:
            Pw = np.array([tuple(verts[j]) for j in path], dtype=np.float64)
            if any(_arc_spline_from_path(cu, obj.matrix_world.inverted(), Pw, closed, h) for h in hints):
                continue
        sp = cu.splines.new('POLY')
        sp.points.add(len(path) - 1)
        for pt, j in zip(sp.points, path):
            q = local[j]
            pt.co = (q.x, q.y, q.z, 1.0)
        sp.use_cyclic_u = closed


def _point_in_poly2(pt, poly):
    x, y = pt
    inside = False
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        if (y1 > y) != (y2 > y):
            if x < (x2 - x1) * (y - y1) / (y2 - y1) + x1:
                inside = not inside
    return inside


def surface_trim(obj, paths, persp_np, hit_local):
    """Retire de la surface de obj la partie cernée par les contours `paths` ([(points monde, fermé)]) vus depuis la caméra.
    Les contours sont projetés sur la surface le long de la vue (orthogonale ou perspective), la face cliquée (hit_local)
    et tout ce qui l'entoure jusqu'au contour est supprimé. Retourne None si c'est fait, sinon un message."""
    from mathutils.bvhtree import BVHTree
    mw = obj.matrix_world
    inv = obj.matrix_world.inverted()
    Pm = np.asarray(persp_np, dtype=np.float64)
    Pinv = np.linalg.inv(Pm)
    me = obj.data
    bm = bmesh.new()
    bm.from_mesh(me)
    clicked_pt = Vector(hit_local)

    def unproject(x, y, z):
        v = Pinv @ np.array((x, y, z, 1.0))
        return Vector((v[0] / v[3], v[1] / v[3], v[2] / v[3]))

    cache = {}

    def v2(v):
        r = cache.get(v)
        if r is None:
            w = mw @ v.co
            c = Pm @ np.array((w.x, w.y, w.z, 1.0))
            r = (c[0] / c[3], c[1] / c[3]) if c[3] > 1e-9 else False
            cache[v] = r
        return r

    # --- contours en 2D (coordonnées écran normalisées)
    P2 = []
    for pts, closed in paths:
        q = []
        ok = True
        for w in pts:
            c = Pm @ np.array((w.x, w.y, w.z, 1.0))
            if c[3] <= 1e-9:
                ok = False
                break
            xy = (c[0] / c[3], c[1] / c[3])
            if not q or math.hypot(xy[0] - q[-1][0], xy[1] - q[-1][1]) > 1e-9:
                q.append(xy)
        if closed and len(q) > 1 and math.hypot(q[0][0] - q[-1][0], q[0][1] - q[-1][1]) <= 1e-9:
            q.pop()
        if ok and len(q) >= 2 and (not closed or len(q) >= 3):
            P2.append({"pts": q, "closed": closed})
    if not P2:
        bm.free()
        return "The cutting curves are not visible from this view"
    allx = [c[0] for p in P2 for c in p["pts"]]
    ally = [c[1] for p in P2 for c in p["pts"]]
    bx0, bx1, by0, by1 = min(allx) - 1e-4, max(allx) + 1e-4, min(ally) - 1e-4, max(ally) + 1e-4

    tracked = set()
    for f in bm.faces:
        pts = [v2(v) for v in f.verts]
        if any(p is False for p in pts):
            continue
        xs, ys = [p[0] for p in pts], [p[1] for p in pts]
        if max(xs) >= bx0 and min(xs) <= bx1 and max(ys) >= by0 and min(ys) <= by1:
            tracked.update(f.verts)
    if not tracked:
        bm.free()
        return "The cutting curves do not cross this surface"

    def active_faces():
        return list({f for v in tracked if v.is_valid for f in v.link_faces})

    def find_events(edges):
        """Croisements (arête, t, chemin, position le long du chemin) entre les arêtes et les contours."""
        m = len(edges)
        C0 = np.empty((m, 3))
        C1 = np.empty((m, 3))
        valid = np.ones(m, dtype=bool)
        for k, e in enumerate(edges):
            for arr, v in ((C0, e.verts[0]), (C1, e.verts[1])):
                w = mw @ v.co
                c = Pm @ np.array((w.x, w.y, w.z, 1.0))
                arr[k] = (c[0], c[1], c[3])
        valid = (C0[:, 2] > 1e-9) & (C1[:, 2] > 1e-9)
        out = []
        for pid, p in enumerate(P2):
            pts, closed = p["pts"], p["closed"]
            n = len(pts)
            for j in range(n if closed else n - 1):
                ax, ay = pts[j]
                bx_, by_ = pts[(j + 1) % n]
                dx, dy = bx_ - ax, by_ - ay
                f0 = dy * (C0[:, 0] - ax * C0[:, 2]) - dx * (C0[:, 1] - ay * C0[:, 2])
                f1 = dy * (C1[:, 0] - ax * C1[:, 2]) - dx * (C1[:, 1] - ay * C1[:, 2])
                cross = valid & ((f0 > 0) != (f1 > 0))
                if not cross.any():
                    continue
                idx = np.nonzero(cross)[0]
                t = f0[idx] / (f0[idx] - f1[idx])
                X = C0[idx, 0] + t * (C1[idx, 0] - C0[idx, 0])
                Y = C0[idx, 1] + t * (C1[idx, 1] - C0[idx, 1])
                W = C0[idx, 2] + t * (C1[idx, 2] - C0[idx, 2])
                u = ((X / W - ax) * dx + (Y / W - ay) * dy) / (dx * dx + dy * dy)
                good = (u >= 0.0) & (u < 1.0)
                for k, tt, uu in zip(idx[good], t[good], u[good]):
                    out.append((int(k), float(tt), pid, j + float(uu)))
        return out

    seam_edges = set()
    for _it in range(3):
        faces = active_faces()
        edges = list({e for f in faces for e in f.edges})
        events = find_events(edges)
        hit_edges = {}
        for k, _t, pid, _pos in events:
            hit_edges.setdefault(pid, set()).add(edges[k])
        seams = []
        for pid, p in enumerate(P2):
            if not p["closed"]:
                continue
            for f in faces:
                poly = [v2(v) for v in f.verts]
                if any(q is False for q in poly) or not _point_in_poly2(p["pts"][0], poly):
                    continue
                if not any(e in hit_edges.get(pid, ()) for e in f.edges):
                    seams.append((pid, f))
        if not seams:
            break
        for pid, f in seams:
            if not f.is_valid:
                continue
            ys = [c[1] for c in P2[pid]["pts"]]
            yc = 0.5 * (min(ys) + max(ys))
            a, b, c = unproject(-1.0, yc, -1.0), unproject(1.0, yc, -1.0), unproject(-1.0, yc, 1.0)
            nrm = (b - a).cross(c - a)
            if nrm.length < 1e-12:
                continue
            ret = bmesh.ops.bisect_plane(bm, geom=[f] + list(f.edges) + list(f.verts), dist=1e-7,
                                         plane_co=inv @ a, plane_no=(mw.to_3x3().transposed() @ nrm).normalized(),
                                         clear_inner=False, clear_outer=False)
            for g in ret.get("geom_cut", ()):
                if isinstance(g, bmesh.types.BMEdge):
                    seam_edges.add(g)
                elif isinstance(g, bmesh.types.BMVert):
                    tracked.add(g)
    faces = active_faces()
    edges = list({e for f in faces for e in f.edges})
    events = find_events(edges)
    if not events:
        bm.free()
        return "The cutting curves do not cross this surface"
    # --- on coupe les arêtes aux croisements
    by_edge = {}
    for k, t, pid, pos in events:
        by_edge.setdefault(k, []).append((t, pid, pos))
    crossings = []                     # (pid, pos, sommet)
    for k, lst in by_edge.items():
        e = edges[k]
        lst.sort()
        cur_e, start = e, e.verts[0]
        tprev = 0.0
        for t, pid, pos in lst:
            tr = (t - tprev) / (1.0 - tprev) if tprev < 1.0 else 1.0
            other = cur_e.other_vert(start)
            if tr <= 1e-6:
                vert = start
            elif tr >= 1.0 - 1e-6:
                vert = other
            else:
                _ne, vert = bmesh.utils.edge_split(cur_e, start, tr)
                tracked.add(vert)
                start, tprev = vert, t
            crossings.append((pid, pos, vert))
    for _p, _pos, v in crossings:
        tracked.add(v)
    # --- pour chaque face : les croisements s'apparient (entrée / sortie) le long du contour
    by_face = {}
    for pid, pos, v in crossings:
        for f in v.link_faces:
            by_face.setdefault((f, pid), []).append((pos, v))
    pairs = []
    for (f, pid), lst in by_face.items():
        poly = [v2(v) for v in f.verts]
        if any(q is False for q in poly) or len(poly) < 3:
            continue
        p = P2[pid]
        lst = sorted({(pos, v) for pos, v in lst}, key=lambda a: a[0])
        merged = []
        for pos, v in lst:                     # un croisement exactement sur un sommet du contour est compté une seule fois
            if merged and merged[-1][1] is v and abs(merged[-1][0] - pos) < 1e-6:
                continue
            merged.append((pos, v))
        lst = merged
        q_pos = lst[0][0] - 1e-6              # juste avant le premier croisement : dans la face (=> c'est une sortie) ou non
        n_pts = len(p["pts"])
        if q_pos < 0.0:
            q_pos = q_pos + n_pts if p["closed"] else 0.0
        jj = int(math.floor(q_pos)) % n_pts
        fr = q_pos - math.floor(q_pos)
        a_pt, b_pt = p["pts"][jj], p["pts"][(jj + 1) % n_pts]
        inside0 = _point_in_poly2((a_pt[0] * (1 - fr) + b_pt[0] * fr, a_pt[1] * (1 - fr) + b_pt[1] * fr), poly)
        if p["closed"]:
            if len(lst) % 2:
                continue
            seq = lst[1:] + lst[:1] if inside0 else lst
        else:
            seq = lst[1:] if inside0 else lst
            if len(seq) % 2:
                seq = seq[:-1]
        for a in range(0, len(seq) - 1, 2):
            (pa, va), (pb, vb) = seq[a], seq[a + 1]
            if va is not vb:
                pairs.append((pid, pa, va, pb, vb))
    barrier = set()
    n_cut = 0
    for pid, pa, va, pb, vb in pairs:
        p = P2[pid]
        n = len(p["pts"])
        if pa < pb:
            ks = [k for k in range(n) if pa + 1e-6 < k < pb - 1e-6]
        else:
            ks = [k for k in range(n) if k > pa + 1e-6 or k < pb - 1e-6]
            ks.sort(key=lambda k: (k <= pa, k))
        mid_pos = 0.5 * (pa + pb) if pa < pb else ((pa + pb + n) * 0.5) % n
        j0 = int(mid_pos) % n
        j1 = (j0 + 1) % n
        fr = mid_pos - int(mid_pos)
        mid2 = (p["pts"][j0][0] * (1 - fr) + p["pts"][j1][0] * fr, p["pts"][j0][1] * (1 - fr) + p["pts"][j1][1] * fr)
        cands = [f for f in va.link_faces if f.is_valid and f in vb.link_faces]
        face = None
        if len(cands) == 1:
            face = cands[0]
        else:
            for f in cands:
                poly = [v2(v) for v in f.verts]
                if not any(q is False for q in poly) and _point_in_poly2(mid2, poly):
                    face = f
                    break
        if face is None:
            continue
        coords = []
        for k in ks:
            a_, b_ = unproject(p["pts"][k][0], p["pts"][k][1], -1.0), unproject(p["pts"][k][0], p["pts"][k][1], 1.0)
            hit = geometry.intersect_line_plane(inv @ a_, inv @ b_, face.verts[0].co, face.normal)
            coords.append(tuple(hit if hit is not None else face.calc_center_median()))
        if not coords and bm.edges.get((va, vb)) is not None:
            barrier.add(bm.edges.get((va, vb)))
            continue
        try:
            bmesh.utils.face_split(face, va, vb, coords=coords)
        except (ValueError, RuntimeError):
            continue
        n_cut += 1
        # arêtes créées : va -> c1 -> ... -> vb
        chain = [va]
        if coords:
            prev, cur = va, None
            nodes = []
            back = vb
            seq_v = []
            for c in reversed(coords):
                found = None
                for e in back.link_edges:
                    o = e.other_vert(back)
                    if o is not va and (o.co - Vector(c)).length < 1e-5 and len(o.link_edges) == 2:
                        found = o
                        break
                if found is None:
                    break
                seq_v.append(found)
                back = found
            chain = [va] + seq_v[::-1] + [vb]
            for v_ in seq_v:
                tracked.add(v_)
        else:
            chain = [va, vb]
        for a_v, b_v in zip(chain, chain[1:]):
            e = bm.edges.get((a_v, b_v))
            if e is not None:
                barrier.add(e)
    if not n_cut and not barrier:
        bm.free()
        return "The cutting curves do not cross this surface"
    bm.verts.ensure_lookup_table()
    bm.edges.ensure_lookup_table()
    bm.faces.ensure_lookup_table()
    bvh = BVHTree.FromBMesh(bm)
    found = bvh.find_nearest(clicked_pt)
    if found is None or found[2] is None:
        bm.free()
        return "Click on the surface"
    start = bm.faces[found[2]]

    def flood(block):
        seen = {start}
        stack = [start]
        while stack:
            f = stack.pop()
            for e in f.edges:
                if e in block:
                    continue
                for g in e.link_faces:
                    if g not in seen:
                        seen.add(g)
                        stack.append(g)
        return seen
    region = flood(barrier)
    whole = flood(set())
    if len(region) == len(whole):
        bm.free()
        return "The cutting curves do not split this surface (the outline must cross it or be closed)"
    bmesh.ops.delete(bm, geom=list(region), context='FACES')
    extra = [e for e in seam_edges if e.is_valid and e not in barrier]
    if extra:
        try:
            bmesh.ops.dissolve_edges(bm, edges=extra, use_verts=False, use_face_split=False)
        except (RuntimeError, ValueError):
            pass
    bm.to_mesh(me)
    me.update()
    bm.free()
    return None



def trim_mesh_cutters(context, exclude=()):
    """Maillages à faces sélectionnés (hors objets exclus) : ils servent de cutters au Trim."""
    return [o for o in context.selected_objects
            if o.type == 'MESH' and len(o.data.polygons) and o not in exclude]


def trim_mesh_cut_fn(objs, depsgraph, tol):
    """Fonction (A, B) -> [s] : paramètres où le segment A->B traverse la surface des maillages objs."""
    if not objs:
        return None
    bvh = make2d_collect(objs, depsgraph)[1]
    if bvh is None:
        return None

    def cut(A, B):
        d = B - A
        L = d.length
        if L < 1e-12:
            return []
        d = d / L
        out = []
        pos = 0.0
        for _ in range(64):
            hit = bvh.ray_cast(A + d * pos, d, L - pos + tol)
            if hit[0] is None:
                break
            dist = pos + hit[3]
            if dist > L + tol:
                break
            out.append(min(max(dist / L, 0.0), 1.0))
            pos = dist + max(tol * 2.0, 1e-7)
            if pos >= L:
                break
        return out
    return cut


_CURVE_PTS = {"handle": None}


def curve_points_cb():
    """Points de contrôle des courbes sélectionnées (comme « Points On » de Rhino) : visibles dès que la courbe est cliquée."""
    if not pref("curve_points"):
        return
    try:
        ctx = bpy.context
        if ctx.mode != 'OBJECT' or ctx.region_data is None:
            return
        objs = [o for o in ctx.selected_objects if o.type == 'CURVE' and o.visible_get()]
        if not objs:
            return
        pts, poly = [], []
        for o in objs:
            mw = o.matrix_world
            for sp in o.data.splines:
                if sp.type == 'BEZIER':
                    pts += [mw @ bp.co for bp in sp.bezier_points]
                else:
                    cv = [mw @ Vector(p.co[:3]) for p in sp.points]
                    pts += cv
                    if sp.type == 'NURBS':      # polygone de contrôle
                        for a, b in zip(cv, cv[1:]):
                            poly += [tuple(a), tuple(b)]
                        if sp.use_cyclic_u and len(cv) > 2:
                            poly += [tuple(cv[-1]), tuple(cv[0])]
                if len(pts) > 4000:
                    break
            if len(pts) > 4000:
                break
        if not pts:
            return
        shader = get_shader('3D')
        gpu.state.blend_set('ALPHA')
        gpu.state.depth_test_set('NONE')
        if poly:
            shader.bind()
            gpu.state.line_width_set(1.0)
            shader.uniform_float("color", (0.9, 0.9, 0.9, 0.55))
            batch_for_shader(shader, 'LINES', {"pos": poly}).draw(shader)
        draw_px_points(pts, 9.0 * px_scale(0.35), (0.0, 0.0, 0.0, 1.0))
        draw_px_points(pts, 6.0 * px_scale(0.35), (1.0, 1.0, 1.0, 1.0))
        gpu.state.blend_set('NONE')
    except (AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
        pass


_TRIM_HL = {"handle": None}
TRIM_HL_COLOR = (1.0, 0.1, 0.75, 1.0)


def trim_highlight_cb():
    """Surligne les cutters (objets sélectionnés) tant que l'outil Trim est actif."""
    context = bpy.context
    try:
        if context.mode != 'OBJECT' or DessinBase.active_tool_id(context) != "dessin.trim_tool":
            return
        dg = context.evaluated_depsgraph_get()
        objs = list(context.selected_objects)
    except (AttributeError, RuntimeError, ReferenceError):
        return
    pts = []
    for o in objs:
        try:
            if o.type == 'MESH' and len(o.data.polygons):
                me = o.data
                mw = o.matrix_world
                for e in me.edges:
                    pts.append(mw @ me.vertices[e.vertices[0]].co)
                    pts.append(mw @ me.vertices[e.vertices[1]].co)
            elif o.type in {'MESH', 'CURVE'} and "dessin_cotation" not in o.keys():
                ev = o.evaluated_get(dg)
                me = ev.to_mesh()
                mw = o.matrix_world
                for e in me.edges:
                    pts.append(mw @ me.vertices[e.vertices[0]].co)
                    pts.append(mw @ me.vertices[e.vertices[1]].co)
                ev.to_mesh_clear()
        except (RuntimeError, AttributeError, ReferenceError):
            continue
        if len(pts) > 400000:
            break
    if not pts:
        return
    shader = get_shader('3D')
    shader.bind()
    gpu.state.blend_set('ALPHA')
    gpu.state.depth_test_set('NONE')
    gpu.state.line_width_set(3.0)
    shader.uniform_float("color", TRIM_HL_COLOR)
    batch_for_shader(shader, 'LINES', {"pos": [tuple(p) for p in pts]}).draw(shader)
    gpu.state.line_width_set(1.0)
    gpu.state.depth_test_set('NONE')
    gpu.state.blend_set('NONE')


class DESSIN_OT_trim(bpy.types.Operator):
    bl_idname = "dessin.trim"
    bl_label = "Trim"
    bl_description = ("Trims curves, outlines and surfaces like Trim: the selected objects are the cutters - curves, outlines or solid / surface meshes (nothing selected: all curves); "
                      "click the part to remove: of a curve (between two intersections) or of a surface (the outline is projected along the view); "
                      "drag a box to remove every part it touches")
    bl_options = {'REGISTER', 'UNDO'}

    @classmethod
    def poll(cls, context):
        return context.mode == 'OBJECT' and context.area is not None and context.area.type == 'VIEW_3D'

    def invoke(self, context, event):
        if event.type == 'LEFTMOUSE' and event.value == 'PRESS' and context.area is not None and cmd_click_idle(context, event):
            return {'CANCELLED'}
        region = find_window_region(context.area, event.mouse_x, event.mouse_y)
        if region is None:
            return {'CANCELLED', 'PASS_THROUGH'}
        if event.type != 'LEFTMOUSE' or event.value != 'PRESS':
            return self.click(context, event)
        # clic simple = Trim d'une portion ; glisser = cadre de sélection (fenêtre / capture) qui retire toutes les portions touchées
        self.area = context.area
        self.region = region
        self.start = (event.mouse_x - region.x, event.mouse_y - region.y)
        self.press_ev = types.SimpleNamespace(mouse_x=event.mouse_x, mouse_y=event.mouse_y)
        self.box = None
        try:
            self.fence = context.scene.dessin.trim_mode == 'FENCE'
        except (AttributeError, ReferenceError):
            self.fence = True
        self.handle = bpy.types.SpaceView3D.draw_handler_add(draw_fence_cb if self.fence else draw_box_cb, (self,), 'WINDOW', 'POST_PIXEL')
        context.window_manager.modal_handler_add(self)
        return {'RUNNING_MODAL'}

    def end_modal(self):
        if getattr(self, "handle", None) is not None:
            bpy.types.SpaceView3D.draw_handler_remove(self.handle, 'WINDOW')
            self.handle = None
        try:
            self.area.tag_redraw()
        except (AttributeError, ReferenceError):
            pass

    def modal(self, context, event):
        if event.type in {'ESC', 'RIGHTMOUSE'} and event.value == 'PRESS':
            self.end_modal()
            return {'CANCELLED'}
        if event.type == 'MOUSEMOVE':
            x, y = event.mouse_x - self.region.x, event.mouse_y - self.region.y
            thr = 6.0 * px_scale()
            if self.box is not None or abs(x - self.start[0]) > thr or abs(y - self.start[1]) > thr:
                self.box = (self.start[0], self.start[1], x, y)
                self.area.tag_redraw()
            return {'RUNNING_MODAL'}
        if event.type == 'LEFTMOUSE' and event.value == 'RELEASE':
            box, ev = self.box, self.press_ev
            self.end_modal()
            if box is None:
                return self.click(context, ev)
            if getattr(self, "fence", False):
                return self.fence_trim(context, box)
            return self.box_trim(context, box)
        return {'RUNNING_MODAL'}

    def graphs_now(self, context):
        dg = context.evaluated_depsgraph_get()
        graphs = {}
        for obj in context.visible_objects:
            g = wire_graph(obj, dg)
            if g is not None and g[1]:
                graphs[obj] = g
        return dg, graphs

    def trim_edge(self, context, dg, graphs, target, e0, tcl):
        """Retire la portion de target portant l'arête e0 (paramètre tcl). Retourne True si quelque chose a été coupé, sinon un message (str) ou None."""
        mesh_objs = trim_mesh_cutters(context)
        cutter_objs = [o for o in context.selected_objects if o in graphs] or ([] if mesh_objs else list(graphs))
        Q0, Q1, QA, QB = [], [], [], []
        extent = 0.0
        all_ext = 0.0
        for o in cutter_objs:
            verts, edges = graphs[o]
            V = np.array([tuple(v) for v in verts], dtype=np.float64)
            E = np.array(edges, dtype=np.int64)
            Q0.append(V[E[:, 0]])
            Q1.append(V[E[:, 1]])
            if o is target:
                QA.append(E[:, 0])
                QB.append(E[:, 1])
            else:
                QA.append(np.full(len(E), -1))
                QB.append(np.full(len(E), -1))
            ext_o = float(np.linalg.norm(V.max(axis=0) - V.min(axis=0)))
            all_ext = max(all_ext, ext_o)
            if not is_xline(o):
                extent = max(extent, ext_o)
        verts, edges = graphs[target]
        V = np.array([tuple(v) for v in verts], dtype=np.float64)
        ext_t = float(np.linalg.norm(V.max(axis=0) - V.min(axis=0)))
        all_ext = max(all_ext, ext_t)
        if not is_xline(target):
            extent = max(extent, ext_t)
        if extent <= 0.0:
            extent = all_ext         # seulement des lignes de construction : on n'a pas mieux
        tol = max(1e-6, 1e-4 * extent)
        if Q0:
            cutters = (np.vstack(Q0), np.vstack(Q1), np.concatenate(QA), np.concatenate(QB))
        else:
            cutters = (np.zeros((0, 3)), np.zeros((0, 3)), np.zeros(0, dtype=np.int64), np.zeros(0, dtype=np.int64))
        res = trim_wire(verts, edges, e0, tcl, cutters, True, tol, trim_mesh_cut_fn(mesh_objs, dg, tol))
        if isinstance(res, str) or res is None:
            return res
        hints = circle_hints(target)
        write_wire(target, res[0], res[1], hints=hints)
        return True

    def multi_trim(self, context, hits_fn, what):
        """Retire, une à une, toutes les portions de courbes désignées par hits_fn(ax, ay, bx, by) -> (vivants, paramètre milieu)
        (les arêtes changent après chaque coupe)."""
        region = self.region
        rv3d = region_rv3d(region, self.area)
        failed = set()
        done = 0
        t_end = time.monotonic() + 8.0
        while done < 400 and time.monotonic() < t_end:
            dg, graphs = self.graphs_now(context)
            persp = np.array(rv3d.perspective_matrix, dtype=np.float64)
            cand = []
            for obj, (verts, edges) in graphs.items():
                V = np.array([tuple(v) for v in verts], dtype=np.float64)
                E = np.array(edges, dtype=np.int64)
                sx, sy, ok = _project_region(V, persp, region)
                ax, ay, bx, by = sx[E[:, 0]], sy[E[:, 0]], sx[E[:, 1]], sy[E[:, 1]]
                good = ok[E[:, 0]] & ok[E[:, 1]]
                alive, tmid = hits_fn(ax, ay, bx, by)
                alive &= good
                for k in np.nonzero(alive)[0]:
                    tm = float(tmid[k])
                    mid = tuple(np.round(V[E[k, 0]] + (V[E[k, 1]] - V[E[k, 0]]) * tm, 4))
                    key = (obj.name, mid)
                    if key not in failed:
                        cand.append((obj, int(k), tm, key))
            hit = False
            for obj, k, tm, key in cand:
                try:
                    res = self.trim_edge(context, dg, graphs, obj, k, tm)
                except (RuntimeError, ReferenceError, ValueError):
                    res = None
                if res is True:
                    done += 1
                    hit = True
                    context.view_layer.update()
                    break
                failed.add(key)
            if not hit:
                break
        if not done:
            self.report({'INFO'}, f"Nothing to trim {what} (the parts must cross a cutting curve)")
            return {'CANCELLED'}
        self.report({'INFO'}, f"Trimmed {done} part(s)")
        return {'FINISHED'}

    def box_trim(self, context, box):
        """Cadre (Crossing) : toutes les portions de courbes touchées par le cadre sont retirées."""
        x0, x1 = sorted((box[0], box[2]))
        y0, y1 = sorted((box[1], box[3]))

        def hits(ax, ay, bx, by):
            # Liang-Barsky : part du segment à l'intérieur du cadre
            dx, dy = bx - ax, by - ay
            t0 = np.zeros(len(ax))
            t1 = np.ones(len(ax))
            alive = np.ones(len(ax), dtype=bool)
            for pp, qq in ((-dx, ax - x0), (dx, x1 - ax), (-dy, ay - y0), (dy, y1 - ay)):
                par = np.abs(pp) < 1e-12
                alive &= ~(par & (qq < 0))
                with np.errstate(divide='ignore', invalid='ignore'):
                    r = np.where(par, 0.0, qq / np.where(par, 1.0, pp))
                neg, pos = (pp < 0) & ~par, (pp > 0) & ~par
                t0 = np.where(neg, np.maximum(t0, r), t0)
                t1 = np.where(pos, np.minimum(t1, r), t1)
            alive &= t0 <= t1
            return alive, (t0 + t1) * 0.5
        return self.multi_trim(context, hits, "in the box")

    def fence_trim(self, context, line):
        """Ligne de coupe (Fence) : toutes les portions de courbes que la ligne traverse sont retirées."""
        fx0, fy0, fx1, fy1 = line
        fdx, fdy = fx1 - fx0, fy1 - fy0

        def hits(ax, ay, bx, by):
            dx, dy = bx - ax, by - ay
            den = dx * fdy - dy * fdx
            par = np.abs(den) < 1e-12
            with np.errstate(divide='ignore', invalid='ignore'):
                u = np.where(par, 0.0, ((fx0 - ax) * fdy - (fy0 - ay) * fdx) / np.where(par, 1.0, den))     # sur l'arête
                v = np.where(par, 0.0, ((fx0 - ax) * dy - (fy0 - ay) * dx) / np.where(par, 1.0, den))       # sur la ligne de coupe
            alive = ~par & (u >= 0.0) & (u <= 1.0) & (v >= 0.0) & (v <= 1.0)
            return alive, np.clip(u, 0.0, 1.0)
        return self.multi_trim(context, hits, "along the fence")

    def click(self, context, event):
        region = find_window_region(context.area, event.mouse_x, event.mouse_y)
        if region is None:
            return {'CANCELLED'}
        rv3d = context.area.spaces.active.region_3d
        dg = context.evaluated_depsgraph_get()
        persp = np.array(rv3d.perspective_matrix, dtype=np.float64)
        mx, my = event.mouse_x - region.x, event.mouse_y - region.y
        graphs = {}
        for obj in context.visible_objects:
            g = wire_graph(obj, dg)
            if g is not None and g[1]:
                graphs[obj] = g
        # arête cliquée : la plus proche du curseur à l'écran
        best = None
        best_d = 14.0 * px_scale()
        for obj, (verts, edges) in graphs.items():
            V = np.array([tuple(v) for v in verts], dtype=np.float64)
            E = np.array(edges, dtype=np.int64)
            sx, sy, ok = _project_region(V, persp, region)
            ax, ay, bx, by = sx[E[:, 0]], sy[E[:, 0]], sx[E[:, 1]], sy[E[:, 1]]
            dx, dy = bx - ax, by - ay
            l2 = dx * dx + dy * dy
            t = np.clip(((mx - ax) * dx + (my - ay) * dy) / np.where(l2 > 1e-12, l2, 1.0), 0.0, 1.0)
            dist = np.hypot(ax + t * dx - mx, ay + t * dy - my)
            dist[~(ok[E[:, 0]] & ok[E[:, 1]])] = np.inf
            k = int(np.argmin(dist))
            if dist[k] < best_d:
                best, best_d = (obj, k, float(t[k])), float(dist[k])
        if best is None:
            return self.try_surface(context, event, region, rv3d, graphs, "Click the part of a curve or of a surface to trim")
        target, e0, tcl = best
        res = self.trim_edge(context, dg, graphs, target, e0, tcl)
        if res is not True:
            return self.try_surface(context, event, region, rv3d, graphs, res or "Nothing to trim")
        return {'FINISHED'}

    def try_surface(self, context, event, region, rv3d, graphs, fallback_msg):
        """Trim d'une surface (maillage à faces) : les courbes de coupe sont projetées le long de la vue."""
        mx, my = event.mouse_x - region.x, event.mouse_y - region.y
        ro = region_2d_to_origin_3d(region, rv3d, Vector((mx, my)))
        rd = region_2d_to_vector_3d(region, rv3d, Vector((mx, my)))
        best = None
        for obj in context.visible_objects:
            if obj.type != 'MESH' or not len(obj.data.polygons) or obj in graphs:
                continue
            inv = obj.matrix_world.inverted()
            ok, loc, _nor, _idx = obj.ray_cast(inv @ ro, inv.to_3x3() @ rd)[:4]
            if ok:
                dist = (obj.matrix_world @ loc - ro).length
                if best is None or dist < best[0]:
                    best = (dist, obj, loc)
        if best is None:
            self.report({'INFO'}, fallback_msg)
            return {'CANCELLED'}
        _d, target, loc = best
        cutter_objs = [o for o in context.selected_objects if o in graphs] or list(graphs)
        paths = []
        for o in cutter_objs:
            verts, edges = graphs[o]
            for path, closed in wire_paths(len(verts), edges):
                if len(path) >= 2:
                    paths.append(([verts[j] for j in path], closed))
        if not paths:
            self.report({'INFO'}, "Select the curve(s) that cut the surface (or draw one in front of it)")
            return {'CANCELLED'}
        msg = surface_trim(target, paths, np.array(rv3d.perspective_matrix, dtype=np.float64), loc)
        if msg:
            self.report({'INFO'}, msg)
            return {'CANCELLED'}
        return {'FINISHED'}


class DESSIN_OT_trim_mode(bpy.types.Operator):
    bl_idname = "dessin.trim_mode"
    bl_label = "Trim: Fence / Crossing"
    bl_description = "Chooses how Trim cuts when you drag: with a fence line or with a crossing box"
    bl_options = {'INTERNAL'}

    mode: bpy.props.EnumProperty(items=(('FENCE', "Fence", ""), ('CROSSING', "Crossing", "")), default='FENCE', options={'SKIP_SAVE'})

    @classmethod
    def poll(cls, context):
        # utilisable en mode Objet comme en mode Édition (EDIT_MESH : la touche reste telle quelle dans la barre d'outils)
        return context.area is not None and context.area.type == 'VIEW_3D'

    def execute(self, context):
        context.scene.dessin.trim_mode = self.mode
        self.report({'INFO'}, "Trim: " + ("Fence line" if self.mode == 'FENCE' else "Crossing box"))
        for win in context.window_manager.windows:
            for a in win.screen.areas:
                if a.type == 'VIEW_3D':
                    a.tag_redraw()
        return {'FINISHED'}


class DESSIN_OT_tool_from_edit(bpy.types.Operator):
    """Outil de la barre du mode édition dont la commande ne travaille qu'en mode objet : quitte l'édition puis la lance."""
    bl_idname = "dessin.tool_from_edit"
    bl_label = "Leave Edit Mode and run the tool"
    bl_options = {'INTERNAL'}

    cmd: bpy.props.StringProperty()
    tool: bpy.props.StringProperty()

    def invoke(self, context, event):
        if context.mode.startswith('EDIT'):
            try:
                bpy.ops.object.mode_set(mode='OBJECT')
            except RuntimeError:
                self.report({'WARNING'}, "Switch to Object mode to use this tool")
                return {'CANCELLED'}
        try:
            bpy.ops.wm.tool_set_by_id(name=self.tool)
        except (RuntimeError, TypeError):
            pass
        f = getattr(bpy.ops.dessin, self.cmd, None)
        if f is not None:
            try:
                f('INVOKE_DEFAULT')
            except RuntimeError:
                pass
        return {'FINISHED'}


def _edit_native(op_id, mode='EDIT_MESH'):
    """La commande tourne-t-elle telle quelle en mode édition (ou bascule-t-elle d'elle-même) ?"""
    if mode != 'EDIT_MESH':
        return False        # édition de courbe : toute commande quitte d'abord l'édition (elles travaillent sur des objets)
    c = globals().get("DESSIN_OT_" + op_id.split(".", 1)[-1])
    if c is None or issubclass(c, DessinBase):
        return True
    poll = getattr(c, "poll", None)
    if poll is None:
        return True
    try:
        import inspect
        return "EDIT_MESH" in inspect.getsource(getattr(poll, "__func__", poll))
    except (OSError, TypeError):
        return False


def _edit_variant(cls, mode='EDIT_MESH'):
    """Même outil pour la barre du mode édition : les commandes réservées au mode objet passent par tool_from_edit."""
    km = []
    main = next((i[0] for i in cls.bl_keymap if i[0] not in ("dessin.pick_object", "dessin.tool_exit", "dessin.grs_key")), None)
    for item in cls.bl_keymap:
        op = item[0]
        if op == "dessin.rclick_run":
            continue
        if mode != 'EDIT_MESH':
            if op in ("dessin.tool_exit", "dessin.grs_key"):
                km.append(item)
            elif op == "dessin.trim_mode":
                km.append(item)
            elif item[1].get("type") != 'MOUSEMOVE':
                cmd = main if op == "dessin.pick_object" else op
                if cmd:
                    km.append(("dessin.tool_from_edit", item[1], {"properties": [("cmd", cmd.split(".", 1)[1]), ("tool", cls.bl_idname)]}))
            continue
        if op == "dessin.pick_object":
            # on reste en mode édition pendant la sélection (zone, clic) ; Entrée / Espace quitte l'édition et lance la commande
            km.append(("dessin.select_loop", {"type": 'LEFTMOUSE', "value": 'DOUBLE_CLICK', "any": True}, None))
            km.append(("view3d.select_box", {"type": 'LEFTMOUSE', "value": 'CLICK_DRAG', "shift": True}, {"properties": [("mode", 'ADD')]}))
            km.append(("view3d.select_box", {"type": 'LEFTMOUSE', "value": 'CLICK_DRAG', "ctrl": True}, {"properties": [("mode", 'SUB')]}))
            km.append(("view3d.select_box", {"type": 'LEFTMOUSE', "value": 'CLICK_DRAG'}, {"properties": [("mode", 'SET')]}))
        elif op.startswith("dessin.") and op not in ("dessin.tool_exit", "dessin.grs_key") and not _edit_native(op):
            if item[1].get("type") == 'MOUSEMOVE':
                continue           # le survol seul ne doit pas faire quitter le mode édition
            km.append(("dessin.tool_from_edit", item[1],
                       {"properties": [("cmd", op.split(".", 1)[1]), ("tool", cls.bl_idname)]}))
        else:
            km.append(item)
    suffix = "_edit" if mode == 'EDIT_MESH' else "_crv"
    return type(cls.__name__ + suffix, (cls,), {"bl_context_mode": mode, "bl_keymap": tuple(km)})


class DESSIN_OT_bar_click(bpy.types.Operator):
    """Clic sur une puce de la barre du bas (Quick Type, OSnap, Gumball...) avec un outil de sélection natif de Blender."""
    bl_idname = "dessin.bar_click"
    bl_label = "Command bar click"
    bl_options = {'INTERNAL'}

    @classmethod
    def poll(cls, context):
        return context.area is not None and context.area.type == 'VIEW_3D'

    def invoke(self, context, event):
        if cmd_click_idle(context, event):
            return {'FINISHED'}
        return {'CANCELLED', 'PASS_THROUGH'}


class DESSIN_OT_rclick_run(bpy.types.Operator):
    """Outils « on désigne les objets, puis Entrée » (Join, Explode...) : clic droit rapide = Entrée (option des préférences)."""
    bl_idname = "dessin.rclick_run"
    bl_label = "Right click = Enter"
    bl_options = {'INTERNAL'}

    cmd: bpy.props.StringProperty()

    def invoke(self, context, event):
        if not pref("rclick_enter") or context.area is None or context.area.type != 'VIEW_3D':
            return {'PASS_THROUGH'}          # option décochée : le clic droit garde son rôle (orbite, menu...)
        self._x, self._y = event.mouse_x, event.mouse_y
        context.window_manager.modal_handler_add(self)
        return {'RUNNING_MODAL'}

    def modal(self, context, event):
        if event.type in {'MOUSEMOVE', 'INBETWEEN_MOUSEMOVE'}:
            tol = max(1, pref("mouse_menu_tol"))
            if abs(event.mouse_x - self._x) > tol or abs(event.mouse_y - self._y) > tol:
                if not start_navigation(context):
                    try:
                        bpy.ops.view3d.rotate('INVOKE_DEFAULT')
                    except RuntimeError:
                        pass
                return {'FINISHED'}
            return {'RUNNING_MODAL'}
        if event.type == 'RIGHTMOUSE' and event.value == 'RELEASE':
            f = getattr(bpy.ops.dessin, self.cmd, None)
            if f is not None:
                try:
                    f('INVOKE_DEFAULT')
                except RuntimeError:
                    pass
            return {'FINISHED'}
        if event.type == 'ESC':
            return {'CANCELLED'}
        return {'RUNNING_MODAL'}


class DESSIN_OT_tool_exit(bpy.types.Operator):
    bl_idname = "dessin.tool_exit"
    bl_label = "Leave the tool"
    bl_options = {'INTERNAL'}

    def execute(self, context):
        back_to_idle()
        return {'FINISHED'}


# --------------------------------------------------------------------------
# Join / Explode (comme dans Rhino : on désigne les objets, puis Entrée)
# --------------------------------------------------------------------------

JOIN_TOL = 1e-4          # tolérance de jonction (unités Blender)
EXPLODE_LIMIT = 2000     # nombre maximal de morceaux créés par un Explode


def _spline_nodes(sp):
    """Nœuds d'une spline POLY ou BEZIER sous forme commune : dicts co / hl / hr / tl / tr (poignées + types)."""
    nodes = []
    if sp.type == 'BEZIER':
        for q in sp.bezier_points:
            nodes.append({"co": q.co.copy(), "hl": q.handle_left.copy(), "hr": q.handle_right.copy(),
                          "tl": q.handle_left_type, "tr": q.handle_right_type, "r": q.radius})
    else:
        for q in sp.points:
            c = Vector(q.co[:3])
            nodes.append({"co": c, "hl": c.copy(), "hr": c.copy(), "tl": 'VECTOR', "tr": 'VECTOR', "r": q.radius})
    return nodes


def _rev_nodes(nodes):
    return [{"co": n["co"], "hl": n["hr"], "hr": n["hl"], "tl": n["tr"], "tr": n["tl"], "r": n["r"]} for n in reversed(nodes)]


def _join_poly_splines(cu, tol):
    """Raccorde bout à bout les splines ouvertes POLY et BEZIER (arcs, cercles ouverts, lignes) de la courbe cu dont les
    extrémités coïncident. Des polylignes seules donnent une polyligne ; dès qu'un arc est présent, le résultat est une
    spline de Bézier : les arcs restent de vrais arcs et les segments gardent des poignées vectorielles."""
    sps = [sp for sp in cu.splines if sp.type in {'POLY', 'BEZIER'} and not sp.use_cyclic_u
           and (len(sp.points) if sp.type == 'POLY' else len(sp.bezier_points)) >= 2]
    if len(sps) < 1:
        return
    chains = [{"nodes": _spline_nodes(sp), "bez": sp.type == 'BEZIER'} for sp in sps]
    changed = True
    while changed and len(chains) > 1:
        changed = False
        for i in range(len(chains)):
            for j in range(i + 1, len(chains)):
                for ra in (False, True):
                    for rb in (False, True):
                        x = _rev_nodes(chains[i]["nodes"]) if ra else chains[i]["nodes"]
                        y = _rev_nodes(chains[j]["nodes"]) if rb else chains[j]["nodes"]
                        if (x[-1]["co"] - y[0]["co"]).length <= tol:
                            joint = dict(x[-1])
                            joint["hr"], joint["tr"] = y[0]["hr"], y[0]["tr"]
                            chains[i] = {"nodes": x[:-1] + [joint] + y[1:], "bez": chains[i]["bez"] or chains[j]["bez"]}
                            del chains[j]
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break
    for sp in sps:
        cu.splines.remove(sp)
    for ch in chains:
        nodes = ch["nodes"]
        closed = (nodes[0]["co"] - nodes[-1]["co"]).length <= tol and len(nodes) >= (3 if ch["bez"] else 4)
        if closed:
            first = dict(nodes[0])
            first["hl"], first["tl"] = nodes[-1]["hl"], nodes[-1]["tl"]
            nodes = [first] + nodes[1:-1]
        if not ch["bez"]:
            sp = cu.splines.new('POLY')
            sp.points.add(len(nodes) - 1)
            for pt, n in zip(sp.points, nodes):
                pt.co = (n["co"].x, n["co"].y, n["co"].z, 1.0)
            sp.use_cyclic_u = closed
        else:
            sp = cu.splines.new('BEZIER')
            sp.bezier_points.add(len(nodes) - 1)
            for pt, n in zip(sp.bezier_points, nodes):
                pt.co = n["co"]
                pt.handle_left_type = pt.handle_right_type = 'FREE'
                pt.handle_left, pt.handle_right = n["hl"], n["hr"]
                pt.handle_left_type, pt.handle_right_type = n["tl"], n["tr"]
                pt.radius = n["r"]
            sp.use_cyclic_u = closed


class DESSIN_OT_join(bpy.types.Operator):
    bl_idname = "dessin.join"
    bl_label = "Join"
    bl_description = ("Joins the selected curves end to end, or the selected surfaces / outlines into one object "
                      "(points closer than the tolerance are merged)")
    bl_options = {'REGISTER', 'UNDO'}

    @classmethod
    def poll(cls, context):
        return context.mode == 'OBJECT' and context.area is not None and context.area.type == 'VIEW_3D'

    def execute(self, context):
        objs = [o for o in context.selected_objects if o.type in {'MESH', 'CURVE'}]
        if not objs:
            self.report({'INFO'}, "Select the curves or surfaces to join (click them, then Enter)")
            return {'CANCELLED'}
        kinds = {o.type for o in objs}
        if len(kinds) > 1:
            self.report({'WARNING'}, "Join works on curves only or on meshes only")
            return {'CANCELLED'}
        kind = kinds.pop()
        active = context.view_layer.objects.active
        if active not in objs:
            active = objs[0]
            context.view_layer.objects.active = active
        if len(objs) > 1:
            try:
                bpy.ops.object.join()
            except RuntimeError as err:
                self.report({'WARNING'}, f"Join failed: {err}")
                return {'CANCELLED'}
            active = context.view_layer.objects.active
        if kind == 'MESH':
            bm = bmesh.new()
            bm.from_mesh(active.data)
            n0 = len(bm.verts)
            bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=JOIN_TOL)
            n1 = len(bm.verts)
            bm.to_mesh(active.data)
            bm.free()
            active.data.update()
            self.report({'INFO'}, f"Joined: {len(objs)} object(s), {n0 - n1} point(s) merged")
        else:
            before = len(active.data.splines)
            _join_poly_splines(active.data, JOIN_TOL)
            self.report({'INFO'}, f"Joined: {before} curve(s) -> {len(active.data.splines)}")
        for o in list(context.view_layer.objects):
            if o is not None:
                o.select_set(o is active)
        return {'FINISHED'}


def _new_object_like(src, data, name):
    obj = bpy.data.objects.new(name, data)
    obj.matrix_world = src.matrix_world.copy()
    for c in (src.users_collection or [bpy.context.scene.collection]):
        c.objects.link(obj)
    return obj


class DESSIN_OT_explode(bpy.types.Operator):
    bl_idname = "dessin.explode"
    bl_label = "Explode"
    bl_description = ("Explodes the selected objects: polylines into segments, curves with several parts into separate curves, "
                      "meshes into one object per face (or per edge for outlines)")
    bl_options = {'REGISTER', 'UNDO'}

    @classmethod
    def poll(cls, context):
        return context.mode == 'OBJECT' and context.area is not None and context.area.type == 'VIEW_3D'

    def explode_mesh(self, obj):
        me = obj.data
        out = []
        verts = [tuple(v.co) for v in me.vertices]
        in_face = set()
        for p in me.polygons:
            in_face.update(e for e in p.edge_keys)
        total = len(me.polygons) + sum(1 for e in me.edges if tuple(sorted(e.vertices)) not in in_face)
        if total <= 1:
            return None
        if total > EXPLODE_LIMIT:
            self.report({'WARNING'}, f"{obj.name}: too many pieces ({total}, limit {EXPLODE_LIMIT})")
            return None
        for p in me.polygons:
            idx = list(p.vertices)
            nm = bpy.data.meshes.new(obj.name)
            nm.from_pydata([verts[i] for i in idx], [], [list(range(len(idx)))])
            for m in me.materials:
                nm.materials.append(m)
            nm.polygons[0].material_index = p.material_index
            nm.update()
            out.append(_new_object_like(obj, nm, obj.name))
        for e in me.edges:
            if tuple(sorted(e.vertices)) in in_face:
                continue
            nm = bpy.data.meshes.new(obj.name)
            nm.from_pydata([verts[e.vertices[0]], verts[e.vertices[1]]], [(0, 1)], [])
            nm.update()
            out.append(_new_object_like(obj, nm, obj.name))
        return out

    def explode_curve(self, obj):
        cu = obj.data
        pieces = []                       # [(type, points)]
        if len(cu.splines) > 1:
            for sp in cu.splines:
                pieces.append(sp)
            mode = 'SPLINES'
        elif len(cu.splines) == 1 and cu.splines[0].type in {'POLY', 'BEZIER'}:
            mode = 'SEGMENTS'
        else:
            return None
        out = []
        if mode == 'SPLINES':
            for sp in pieces:
                nc = bpy.data.curves.new(obj.name, 'CURVE')
                nc.dimensions = cu.dimensions
                for m in cu.materials:
                    nc.materials.append(m)
                ns_ = nc.splines.new(sp.type)
                if sp.type == 'BEZIER':
                    ns_.bezier_points.add(len(sp.bezier_points) - 1)
                    for a, b in zip(sp.bezier_points, ns_.bezier_points):
                        b.handle_left_type = b.handle_right_type = 'FREE'
                        b.co, b.handle_left, b.handle_right = a.co, a.handle_left, a.handle_right
                else:
                    ns_.points.add(len(sp.points) - 1)
                    for a, b in zip(sp.points, ns_.points):
                        b.co = a.co
                ns_.use_cyclic_u = sp.use_cyclic_u
                out.append(_new_object_like(obj, nc, obj.name))
            return out
        sp = cu.splines[0]
        if sp.type == 'POLY':
            pts = [Vector(p.co[:3]) for p in sp.points]
            n = len(pts)
            segs = [(pts[i], pts[(i + 1) % n]) for i in range(n if sp.use_cyclic_u else n - 1)]
            if len(segs) <= 1:
                return None
            if len(segs) > EXPLODE_LIMIT:
                self.report({'WARNING'}, f"{obj.name}: too many segments ({len(segs)})")
                return None
            for a, b in segs:
                nc = bpy.data.curves.new(obj.name, 'CURVE')
                nc.dimensions = cu.dimensions
                for m in cu.materials:
                    nc.materials.append(m)
                s2 = nc.splines.new('POLY')
                s2.points.add(1)
                s2.points[0].co = (a.x, a.y, a.z, 1.0)
                s2.points[1].co = (b.x, b.y, b.z, 1.0)
                out.append(_new_object_like(obj, nc, obj.name))
            return out
        bp = sp.bezier_points
        n = len(bp)
        count = n if sp.use_cyclic_u else n - 1
        if count <= 1:
            return None
        for i in range(count):
            a, b = bp[i], bp[(i + 1) % n]
            nc = bpy.data.curves.new(obj.name, 'CURVE')
            nc.dimensions = cu.dimensions
            for m in cu.materials:
                nc.materials.append(m)
            s2 = nc.splines.new('BEZIER')
            s2.bezier_points.add(1)
            for q, src in ((s2.bezier_points[0], a), (s2.bezier_points[1], b)):
                q.handle_left_type = q.handle_right_type = 'FREE'
                q.co, q.handle_left, q.handle_right = src.co, src.handle_left, src.handle_right
            out.append(_new_object_like(obj, nc, obj.name))
        return out

    def execute(self, context):
        objs = [o for o in context.selected_objects if o.type in {'MESH', 'CURVE'}]
        if not objs:
            self.report({'INFO'}, "Select the objects to explode (click them, then Enter)")
            return {'CANCELLED'}
        created = []
        for obj in objs:
            res = self.explode_mesh(obj) if obj.type == 'MESH' else self.explode_curve(obj)
            if not res:
                continue
            data = obj.data
            bpy.data.objects.remove(obj)
            if data.users == 0:
                (bpy.data.meshes if isinstance(data, bpy.types.Mesh) else bpy.data.curves).remove(data)
            created.extend(res)
        if not created:
            self.report({'INFO'}, "Nothing to explode")
            return {'CANCELLED'}
        for o in list(context.view_layer.objects):
            if o is not None:
                o.select_set(False)
        for o in created:
            if o is not None:
                o.select_set(True)
        context.view_layer.objects.active = created[-1]
        self.report({'INFO'}, f"Exploded into {len(created)} object(s)")
        return {'FINISHED'}


class DESSIN_OT_pick_object(bpy.types.Operator):
    bl_idname = "dessin.pick_object"
    bl_label = "Pick object"
    bl_description = "Adds the object under the cursor to the selection (click it again to remove it)"
    bl_options = {'REGISTER', 'UNDO'}

    @classmethod
    def poll(cls, context):
        return context.mode == 'OBJECT' and context.area is not None and context.area.type == 'VIEW_3D'

    def invoke(self, context, event):
        if event.type == 'LEFTMOUSE' and event.value == 'PRESS' and context.area is not None and cmd_click_idle(context, event):
            return {'CANCELLED'}
        region = find_window_region(context.area, event.mouse_x, event.mouse_y)
        if region is None:
            return {'CANCELLED', 'PASS_THROUGH'}
        rv3d = context.area.spaces.active.region_3d
        mx, my = event.mouse_x - region.x, event.mouse_y - region.y
        persp = np.array(rv3d.perspective_matrix, dtype=np.float64)
        dg = context.evaluated_depsgraph_get()
        best, best_d = None, 14.0 * px_scale()
        for obj in context.visible_objects:
            g = wire_graph(obj, dg)
            if g is None or not g[1]:
                continue
            V = np.array([tuple(v) for v in g[0]], dtype=np.float64)
            E = np.array(g[1], dtype=np.int64)
            sx, sy, ok = _project_region(V, persp, region)
            ax, ay, bx, by = sx[E[:, 0]], sy[E[:, 0]], sx[E[:, 1]], sy[E[:, 1]]
            dx, dy = bx - ax, by - ay
            l2 = dx * dx + dy * dy
            t = np.clip(((mx - ax) * dx + (my - ay) * dy) / np.where(l2 > 1e-12, l2, 1.0), 0.0, 1.0)
            dist = np.hypot(ax + t * dx - mx, ay + t * dy - my)
            dist[~(ok[E[:, 0]] & ok[E[:, 1]])] = np.inf
            d = float(dist.min())
            if d < best_d:
                best, best_d = obj, d
        if best is None:
            ro = region_2d_to_origin_3d(region, rv3d, Vector((mx, my)))
            rd = region_2d_to_vector_3d(region, rv3d, Vector((mx, my)))
            near = None
            for obj in context.visible_objects:
                if obj.type != 'MESH' or not len(obj.data.polygons):
                    continue
                inv = obj.matrix_world.inverted()
                ok, loc, _n, _i = obj.ray_cast(inv @ ro, inv.to_3x3() @ rd)[:4]
                if ok:
                    dist = (obj.matrix_world @ loc - ro).length
                    if near is None or dist < near[0]:
                        near = (dist, obj)
            best = near[1] if near else None
        if best is None:
            return {'CANCELLED'}
        best.select_set(not best.select_get())
        if best.name in _PICK_ORDER:
            _PICK_ORDER.remove(best.name)
        if best.select_get():
            _PICK_ORDER.append(best.name)
            context.view_layer.objects.active = best
        return {'FINISHED'}


# --------------------------------------------------------------------------
# Surfaces : Revolve / Loft / Sweep, et Align (options inspirées de Rhino)
# --------------------------------------------------------------------------

_PICK_ORDER = []          # noms des objets cliqués avec Join / Explode / Loft / Sweep / Align, dans l'ordre des clics


def ordered_selection(context, types=('MESH', 'CURVE')):
    """Objets sélectionnés, dans l'ordre où on les a cliqués (les autres ensuite, par nom)."""
    sel = {o.name: o for o in context.selected_objects if o.type in types}
    out = [sel.pop(n) for n in _PICK_ORDER if n in sel]
    out += [sel[n] for n in sorted(sel)]
    return out


def object_paths(obj, depsgraph):
    """Tous les contours d'un objet (courbe ou maillage sans face) : [(points monde (n,3), fermé)]."""
    g = wire_graph(obj, depsgraph)
    if not g or not g[1]:
        return []
    verts, edges = g
    out = []
    for path, closed in wire_paths(len(verts), edges):
        if len(path) < 2:
            continue
        P = np.array([tuple(verts[i]) for i in path], dtype=np.float64)
        keep = [0]
        for i in range(1, len(P)):
            if np.linalg.norm(P[i] - P[keep[-1]]) > 1e-9:
                keep.append(i)
        P = P[keep]
        if closed and len(P) > 1 and np.linalg.norm(P[0] - P[-1]) <= 1e-9:
            P = P[:-1]
        if len(P) >= 2:
            out.append((P, bool(closed) and len(P) >= 3))
    return out


def path_length(P, closed):
    Q = np.vstack([P, P[:1]]) if closed else P
    return float(np.linalg.norm(np.diff(Q, axis=0), axis=1).sum())


def object_profile(obj, depsgraph):
    """Le plus long contour de l'objet : (points (n,3), fermé) ou None."""
    paths = object_paths(obj, depsgraph)
    if not paths:
        return None
    return max(paths, key=lambda t: path_length(t[0], t[1]))


def refine_points(P, closed, n):
    """Ajoute des points (au milieu du plus long segment) jusqu'à n, sans bouger les points existants."""
    pts = [np.array(p, dtype=np.float64) for p in P]
    while len(pts) < n:
        m = len(pts)
        segs = m if closed else m - 1
        lens = [np.linalg.norm(pts[(i + 1) % m] - pts[i]) for i in range(segs)]
        i = int(np.argmax(lens))
        pts.insert(i + 1, (pts[i] + pts[(i + 1) % m]) * 0.5)
    return np.array(pts)


def newell_normal(P):
    return np.cross(P, np.roll(P, -1, axis=0)).sum(axis=0)


def align_sections(secs, closed):
    """Met les sections (même nombre de points) dans le même sens et sur la même couture (comme « Align direction »)."""
    out = [secs[0]]
    for S in secs[1:]:
        prev = out[-1]
        if closed:
            n1, n0 = newell_normal(S), newell_normal(prev)
            if np.linalg.norm(n1) > 1e-12 and np.linalg.norm(n0) > 1e-12 and n1.dot(n0) < 0:
                S = S[::-1]
            best, bk = None, 0
            for k in range(len(S)):
                dsum = float(np.linalg.norm(np.roll(S, -k, axis=0) - prev, axis=1).sum())
                if best is None or dsum < best:
                    best, bk = dsum, k
            S = np.roll(S, -bk, axis=0)
        else:
            a = float(np.linalg.norm(S - prev, axis=1).sum())
            b = float(np.linalg.norm(S[::-1] - prev, axis=1).sum())
            if b < a:
                S = S[::-1]
        out.append(S)
    return out


def catmull_rows(secs, closed, sub):
    """Interpole les sections (Catmull-Rom uniforme) : un lissage entre les profils, comme le Loft « Normal »."""
    A = np.array(secs)
    K = len(A)
    rows = []
    spans = K if closed else K - 1
    for i in range(spans):
        p0 = A[(i - 1) % K] if (closed or i > 0) else 2 * A[0] - A[1]
        p1, p2 = A[i % K], A[(i + 1) % K]
        p3 = A[(i + 2) % K] if (closed or i + 2 < K) else 2 * A[K - 1] - A[K - 2]
        for s in range(sub):
            t = s / sub
            rows.append(0.5 * (2 * p1 + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t
                               + (-p0 + 3 * p1 - 3 * p2 + p3) * t ** 3))
    if not closed:
        rows.append(A[-1])
    return np.array(rows)


def grid_mesh(rows, closed_profile, closed_rows, cap):
    """rows : (R, n, 3). Retourne (sommets (R*n, 3), faces) ; cap : n-gones aux deux bouts (profil fermé, lignes ouvertes)."""
    R, n = rows.shape[0], rows.shape[1]
    V = rows.reshape(-1, 3)
    F = []
    for r in range(R if closed_rows else R - 1):
        r2 = (r + 1) % R
        for j in range(n if closed_profile else n - 1):
            j2 = (j + 1) % n
            F.append((r * n + j, r * n + j2, r2 * n + j2, r2 * n + j))
    if cap and closed_profile and not closed_rows and n >= 3:
        F.append(tuple(range(n - 1, -1, -1)))
        F.append(tuple(range((R - 1) * n, R * n)))
    return V, F


def mesh_object_from_arrays(context, name, V, F, origin, fix_normals):
    """Crée l'objet maillage (sommets en coordonnées monde, origine de l'objet = origin)."""
    o = Vector(origin)
    me = bpy.data.meshes.new(name)
    me.from_pydata([tuple(Vector(p) - o) for p in V], [], [tuple(f) for f in F])
    me.update()
    bm = bmesh.new()
    bm.from_mesh(me)
    bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=1e-6)
    bm.faces.ensure_lookup_table()
    degenerate = [f for f in bm.faces if f.calc_area() < 1e-14]
    if degenerate:
        bmesh.ops.delete(bm, geom=degenerate, context='FACES_ONLY')
    loose = [e for e in bm.edges if not e.link_faces]
    if loose:
        bmesh.ops.delete(bm, geom=loose, context='EDGES')
    loose_v = [v for v in bm.verts if not v.link_edges]
    if loose_v:
        bmesh.ops.delete(bm, geom=loose_v, context='VERTS')
    if fix_normals:
        bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(me)
    bm.free()
    me.update()
    obj = _link_object(context, name, me)
    obj.location = o
    return obj


def deselect_all_objects(context):
    """Désélectionne tout (sans trébucher sur un objet qui vient d'être supprimé)."""
    for ob in list(context.view_layer.objects):
        try:
            if ob is not None:
                ob.select_set(False)
        except (ReferenceError, RuntimeError):
            pass


def delete_objects(objs):
    for o in objs:
        try:
            data = o.data
            bpy.data.objects.remove(o)
            if data is not None and data.users == 0:
                if isinstance(data, bpy.types.Mesh):
                    bpy.data.meshes.remove(data)
                elif isinstance(data, bpy.types.Curve):
                    bpy.data.curves.remove(data)
        except (ReferenceError, RuntimeError):
            pass


# ---- Loft ----

def loft_surface(profiles, closed_loft=False, smooth=True, cap=True, points=0):
    """profiles : [(points (n,3), fermé)] dans l'ordre. Retourne (sommets, faces) ou (None, message)."""
    if len(profiles) < 2:
        return None, "Loft needs at least two curves"
    kinds = {c for _p, c in profiles}
    if len(kinds) > 1:
        return None, "Loft: mix of open and closed curves"
    closed = kinds.pop()
    n = max([len(p) for p, _c in profiles] + [int(points) if points else 0, 3 if closed else 2])
    secs = [refine_points(p, closed, n) for p, _c in profiles]
    secs = align_sections(secs, closed)
    if len(secs) <= 2:
        closed_loft = False
    rows = catmull_rows(secs, closed_loft, 8) if (smooth and len(secs) > 2) else np.array(secs)
    V, F = grid_mesh(rows, closed, closed_loft, cap)
    return (V, F, closed), ""


# ---- Sweep ----

def rail_frames(R, closed, upright):
    """Repères le long du rail : tangentes T, normales N, binormales B, et mitre (direction, facteur) aux angles."""
    m = len(R)
    T = np.zeros((m, 3))
    md = np.zeros((m, 3))
    mk = np.ones(m)
    for i in range(m):
        a = R[i] - R[i - 1] if (closed or i > 0) else None
        b = R[(i + 1) % m] - R[i] if (closed or i < m - 1) else None
        ta = a / np.linalg.norm(a) if a is not None and np.linalg.norm(a) > 1e-12 else None
        tb = b / np.linalg.norm(b) if b is not None and np.linalg.norm(b) > 1e-12 else None
        if ta is not None and tb is not None:
            t = ta + tb
            if np.linalg.norm(t) < 1e-9:
                t = ta
            t = t / np.linalg.norm(t)
            ch = float(t.dot(ta))
            turn = tb - ta
            if np.linalg.norm(turn) > 1e-9 and ch > 0.2:
                md[i] = turn / np.linalg.norm(turn)
                mk[i] = 1.0 / ch
        else:
            t = ta if ta is not None else tb
            if t is None:       # points confondus : on garde la tangente précédente
                t = T[i - 1] if i > 0 else np.array((1.0, 0.0, 0.0))
        T[i] = t
    z = np.array((0.0, 0.0, 1.0))
    N = np.zeros((m, 3))
    if upright:
        prev = np.array((1.0, 0.0, 0.0))
        for i in range(m):
            n = z - T[i] * z.dot(T[i])
            if np.linalg.norm(n) < 1e-6:
                n = prev - T[i] * prev.dot(T[i])
            N[i] = n / np.linalg.norm(n)
            prev = N[i]
    else:
        n0 = z - T[0] * z.dot(T[0])
        if np.linalg.norm(n0) < 1e-6:
            n0 = np.array((1.0, 0.0, 0.0)) - T[0] * T[0][0]
        N[0] = n0 / np.linalg.norm(n0)

        def transport(r, x0, x1, t0, t1):
            v1 = x1 - x0
            c1 = v1.dot(v1)
            if c1 < 1e-18:
                return r
            rl = r - (2.0 / c1) * v1.dot(r) * v1
            tl = t0 - (2.0 / c1) * v1.dot(t0) * v1
            v2 = t1 - tl
            c2 = v2.dot(v2)
            if c2 < 1e-18:
                return rl
            return rl - (2.0 / c2) * v2.dot(rl) * v2

        for i in range(m - 1):
            r = transport(N[i], R[i], R[i + 1], T[i], T[i + 1])
            r = r - T[i + 1] * T[i + 1].dot(r)
            N[i + 1] = r / np.linalg.norm(r)
        if closed and m > 2:
            r = transport(N[m - 1], R[m - 1], R[0], T[m - 1], T[0])
            r = r - T[0] * T[0].dot(r)
            r = r / np.linalg.norm(r)
            phi = math.atan2(float(np.cross(r, N[0]).dot(T[0])), float(r.dot(N[0])))
            seg = np.linalg.norm(np.diff(np.vstack([R, R[:1]]), axis=0), axis=1)
            s = np.concatenate([[0.0], np.cumsum(seg)[:-1]]) / max(seg.sum(), 1e-12)
            for i in range(m):
                th = phi * s[i]
                N[i] = N[i] * math.cos(th) + np.cross(T[i], N[i]) * math.sin(th)
    B = np.cross(T, N)
    return T, N, B, md, mk


def interp_sections(local, idx, m, closed, pos=None):
    """local : [(n,3)] sections (repère du rail), idx : stations d'attache (croissantes). Retourne (m, n, 3).
    pos : abscisse de chaque station (par défaut son numéro) pour interpoler selon la distance et non selon l'indice."""
    n = local[0].shape[0]
    out = np.zeros((m, n, 3))
    if len(local) == 1:
        out[:] = local[0]
        return out
    P = np.arange(m, dtype=np.float64) if pos is None else np.asarray(pos, dtype=np.float64)
    for k in range(m):
        if k <= idx[0]:
            out[k] = local[0]
        elif k >= idx[-1]:
            out[k] = local[-1]
        else:
            j = int(np.searchsorted(idx, k, side='right')) - 1
            span = max(P[idx[j + 1]] - P[idx[j]], 1e-12)
            t = min(max((P[k] - P[idx[j]]) / span, 0.0), 1.0)
            out[k] = local[j] * (1 - t) + local[j + 1] * t
    return out


def polyline_nearest(R, closed, pts):
    """Point le plus proche de chaque point de pts sur la polyligne R : (segment, paramètre, point, distance)."""
    A = R
    B = np.roll(R, -1, axis=0) if closed else R[1:]
    if not closed:
        A = R[:-1]
    ab = B - A
    l2 = np.maximum((ab * ab).sum(axis=1), 1e-30)
    out = []
    for p in np.atleast_2d(pts):
        t = np.clip(((p - A) * ab).sum(axis=1) / l2, 0.0, 1.0)
        q = A + ab * t[:, None]
        d = np.linalg.norm(q - p, axis=1)
        out.append((d, t, q))
    return A, B, out


def section_normal(S, closed):
    """Normale du plan d'un profil (Newell si fermé, sinon plan moyen)."""
    c = S - S.mean(axis=0)
    if closed:
        n = newell_normal(S)
        if np.linalg.norm(n) > 1e-12:
            return n / np.linalg.norm(n)
    try:
        return np.linalg.svd(c, full_matrices=False)[2][-1]
    except np.linalg.LinAlgError:
        return np.array((0.0, 0.0, 1.0))


def sweep1_surface(rail, sections, upright=False, miter=True, cap=True):
    """rail : (points, fermé) ; sections : [(points, fermé)]. Retourne ((V, F, closed), '') ou (None, message).
    Chaque profil est mesuré dans le repère de l'ARÊTE du rail qu'il traverse (et non dans celui, en biais, du sommet le plus proche) :
    l'épaisseur reste constante, y compris aux angles du rail."""
    R, rclosed = rail
    if len(sections) == 0:
        return None, "Sweep needs at least one cross-section"
    kinds = {c for _p, c in sections}
    if len(kinds) > 1:
        return None, "Sweep: mix of open and closed cross-sections"
    sclosed = kinds.pop()
    T, N, B, md, mk = rail_frames(R, rclosed, upright)
    m = len(R)
    n = max(len(p) for p, _c in sections)
    n = max(n, 3 if sclosed else 2)
    # angles du rail : le décalage le long du rail (composante T du profil) n'a pas de sens sur un coin mitré
    ta = R - np.roll(R, 1, axis=0)
    tb = np.roll(R, -1, axis=0) - R
    la, lb = np.linalg.norm(ta, axis=1), np.linalg.norm(tb, axis=1)
    cosang = (ta * tb).sum(axis=1) / np.maximum(la * lb, 1e-30)
    corner = cosang < 0.9
    if not rclosed:
        corner[0] = corner[-1] = False
    keep_t = np.where(corner, 0.0, 1.0)
    A_, B_ = None, None
    entries = []
    for p, _c in sections:
        S = refine_points(p, sclosed, n)
        c = S.mean(axis=0)
        A_, B_, near = polyline_nearest(R, rclosed, c)
        d_, t_, q_ = near[0]
        dmin = float(d_.min())
        nrm = section_normal(S, sclosed)
        tol = max(1e-6, 1e-6 * float(np.ptp(R, axis=0).max()))
        cands = np.nonzero(d_ <= dmin + tol)[0]
        segdir = (B_ - A_)[cands]
        segdir = segdir / np.maximum(np.linalg.norm(segdir, axis=1, keepdims=True), 1e-30)
        s = int(cands[int(np.argmax(np.abs(segdir @ nrm)))])
        q = q_[s]
        te = (B_[s] - A_[s])
        te = te / max(float(np.linalg.norm(te)), 1e-30)
        # station d'attache : sommet le plus proche du point d'attache
        k = int(np.argmin(np.linalg.norm(R - q, axis=1)))
        ne = N[k] - te * float(te.dot(N[k]))
        if np.linalg.norm(ne) < 1e-6:
            ne = np.cross(te, np.array((0.0, 0.0, 1.0)))
            if np.linalg.norm(ne) < 1e-6:
                ne = np.array((1.0, 0.0, 0.0))
        ne = ne / np.linalg.norm(ne)
        be = np.cross(te, ne)
        d = S - q
        entries.append((k, np.stack([d @ ne, d @ be, d @ te], axis=1)))
    entries.sort(key=lambda e: e[0])
    idx = [e[0] for e in entries]
    local = align_sections([e[1] for e in entries], sclosed)
    L = interp_sections(local, idx, m, rclosed)
    rows = (R[:, None, :] + L[:, :, 0:1] * N[:, None, :] + L[:, :, 1:2] * B[:, None, :]
            + (L[:, :, 2:3] * keep_t[:, None, None]) * T[:, None, :])
    if miter:
        d = rows - R[:, None, :]
        par = np.einsum('mnk,mk->mn', d, md)
        rows = rows + (par * (mk - 1.0)[:, None])[:, :, None] * md[:, None, :]
    V, F = grid_mesh(rows, sclosed, rclosed, cap)
    return (V, F, sclosed), ""


def polyline_project(R, closed, Q):
    """Projette les points Q sur la polyligne R : (abscisse curviligne, point projeté, longueur totale)."""
    A = R if closed else R[:-1]
    B = np.roll(R, -1, axis=0) if closed else R[1:]
    ab = B - A
    ln = np.linalg.norm(ab, axis=1)
    l2 = np.maximum(ln * ln, 1e-30)
    start = np.concatenate([[0.0], np.cumsum(ln)[:-1]])
    Q = np.atleast_2d(Q)
    S = np.zeros(len(Q))
    P = np.zeros((len(Q), 3))
    chunk = max(1, int(1.5e6 / max(len(A), 1)))
    for i0 in range(0, len(Q), chunk):
        q = Q[i0:i0 + chunk]
        t = np.clip(((q[:, None, :] - A[None]) * ab[None]).sum(axis=2) / l2[None], 0.0, 1.0)
        pts = A[None] + ab[None] * t[:, :, None]
        d = np.linalg.norm(pts - q[:, None, :], axis=2)
        j = d.argmin(axis=1)
        r = np.arange(len(q))
        S[i0:i0 + chunk] = start[j] + t[r, j] * ln[j]
        P[i0:i0 + chunk] = pts[r, j]
    return S, P, float(ln.sum())


def polyline_point(R, closed, s):
    """Point d'abscisse curviligne s (tableau) sur la polyligne R."""
    A = R if closed else R[:-1]
    B = np.roll(R, -1, axis=0) if closed else R[1:]
    ab = B - A
    ln = np.maximum(np.linalg.norm(ab, axis=1), 1e-30)
    start = np.concatenate([[0.0], np.cumsum(ln)[:-1]])
    s = np.asarray(s, dtype=np.float64)
    j = np.clip(np.searchsorted(start, s, side='right') - 1, 0, len(A) - 1)
    t = np.clip((s - start[j]) / ln[j], 0.0, 1.0)
    return A[j] + ab[j] * t[:, None]


def sweep2_stations(R1, c1, R2, c2, centers):
    """Stations (point du rail 1, point apparié du rail 2, abscisse sur le rail 1) :
    chaque point est apparié au point le plus proche de l'autre rail, donc les cordes restent perpendiculaires aux rails
    (rails parallèles / décalés, rectangles...). Si cet appariement n'est pas monotone, on retombe sur l'abscisse normalisée.
    Les sommets des deux rails et le point où chaque profil coupe le rail sont des stations."""
    A0 = refine_points(R1, c1, max(len(R1), 24))
    seg = np.linalg.norm((np.roll(A0, -1, axis=0) - A0) if c1 else (A0[1:] - A0[:-1]), axis=1)
    sA0 = np.concatenate([[0.0], np.cumsum(seg)[:-1]]) if c1 else np.concatenate([[0.0], np.cumsum(seg)])
    LA = float(seg.sum())
    Br = R2
    if not c1 and (np.linalg.norm(A0[0] - Br[0]) + np.linalg.norm(A0[-1] - Br[-1])
                   > np.linalg.norm(A0[0] - Br[-1]) + np.linalg.norm(A0[-1] - Br[0])):
        Br = Br[::-1]
    if c1 and float(newell_normal(A0).dot(newell_normal(Br))) < 0:
        Br = Br[::-1]                       # rails fermés tournant en sens inverse
    # candidats : échantillons du rail 1, sommets du rail 2 (projetés sur le rail 1), points d'attache des profils
    sB_, PB_, _LB = polyline_project(Br, c2, A0)
    sA_list = [sA0]
    PA_list = [A0]
    PB_list = [PB_]
    sv, qv, _l = polyline_project(A0, c1, Br)
    sA_list.append(sv)
    PA_list.append(qv)
    PB_list.append(Br)
    if len(centers):
        sc, qc, _l = polyline_project(A0, c1, np.array(centers))
        _sb, pbc, _lb = polyline_project(Br, c2, qc)
        sA_list.append(sc)
        PA_list.append(qc)
        PB_list.append(pbc)
    sA = np.concatenate(sA_list)
    PA = np.vstack(PA_list)
    PB = np.vstack(PB_list)
    if c1:
        sA = np.where(sA >= LA * (1 - 1e-9), 0.0, sA)
    order = np.argsort(sA, kind='stable')
    sA, PA, PB = sA[order], PA[order], PB[order]
    keep = [0]
    eps = max(1e-7 * LA, 1e-9)
    for i in range(1, len(sA)):
        if sA[i] - sA[keep[-1]] > eps:
            keep.append(i)
    sA, PA, PB = sA[keep], PA[keep], PB[keep]
    if not c1:
        PB[0], PB[-1] = Br[0], Br[-1]
    # contrôle : l'appariement par plus proche point doit avancer dans le même sens sur le rail 2
    sB, _p, LB = polyline_project(Br, c2, PB)
    good = True
    if c1:
        u = (sB - sB[0]) % LB
        good = bool(np.all(np.diff(u) >= -1e-6 * LB))
    else:
        good = bool(np.all(np.diff(sB) >= -1e-6 * LB))
    if not good:
        fr = sA / max(LA, 1e-30)
        if c1:
            s0 = float(sB[0])
            PB = polyline_point(Br, c2, (s0 + fr * LB) % LB)
        else:
            PB = polyline_point(Br, c2, fr * LB)
    return sA, PA, PB, LA


def sweep2_surface(rail1, rail2, sections, cap=True):
    """Deux rails : la section est déformée pour rester entre les deux rails.
    Largeur (entre les rails) mise à l'échelle avec l'écartement ; hauteur mise à l'échelle avec l'écartement mesuré
    perpendiculairement au rail (donc sans grossir aux coins mitrés)."""
    R1, c1 = rail1
    R2, c2 = rail2
    if len(sections) == 0:
        return None, "Sweep needs at least one cross-section"
    if c1 != c2:
        return None, "Sweep 2 rails: one rail is closed and the other open"
    kinds = {c for _p, c in sections}
    if len(kinds) > 1:
        return None, "Sweep: mix of open and closed cross-sections"
    sclosed = kinds.pop()
    n = max(max(len(p) for p, _c in sections), 3 if sclosed else 2)
    secs = [refine_points(p, sclosed, n) for p, _c in sections]
    sA, A, Bp, LA = sweep2_stations(R1, c1, R2, c2, [S.mean(axis=0) for S in secs])
    m = len(A)
    if m < 2:
        return None, "Sweep 2 rails: the rails are too short"
    T1, _N1, _B1, _md1, mk1 = rail_frames(A, c1, True)
    T2, _N2, _B2, _md2, mk2 = rail_frames(Bp, c2, True)
    flip = np.where((T1 * T2).sum(axis=1) < 0, -1.0, 1.0)
    T2 = T2 * flip[:, None]
    Tm = T1 + T2
    Tm = Tm / np.maximum(np.linalg.norm(Tm, axis=1, keepdims=True), 1e-12)
    chord = Bp - A
    cl = np.maximum(np.linalg.norm(chord, axis=1), 1e-9)
    e1 = chord / cl[:, None]
    f3 = np.cross(e1, Tm)
    bad = np.linalg.norm(f3, axis=1) < 1e-6
    f3[bad] = np.array((0.0, 0.0, 1.0))
    f3 = f3 / np.linalg.norm(f3, axis=1, keepdims=True)
    f2 = np.cross(f3, e1)
    mk = np.maximum(mk1, mk2)
    pd = cl / mk                                  # écartement perpendiculaire (aux coins mitrés la corde est plus longue que l'écartement)
    keep_t = np.where(mk > 1.03, 0.0, 1.0)         # pas de décalage le long du rail sur un coin mitré
    entries = []
    for S in secs:
        c = S.mean(axis=0)
        k = int(np.argmin(np.linalg.norm(A - polyline_project(A, c1, c)[1][0], axis=1)))
        d = S - A[k]
        entries.append((k, np.stack([d @ e1[k] / cl[k], d @ f2[k] / pd[k], d @ f3[k] / pd[k]], axis=1)))
    entries.sort(key=lambda e: e[0])
    idx = [e[0] for e in entries]
    local = align_sections([e[1] for e in entries], sclosed)
    L = interp_sections(local, idx, m, c1, sA)
    rows = (A[:, None, :] + L[:, :, 0:1] * (cl[:, None, None] * e1[:, None, :])
            + (L[:, :, 1:2] * (pd * keep_t)[:, None, None]) * f2[:, None, :]
            + (L[:, :, 2:3] * pd[:, None, None]) * f3[:, None, :])
    V, F = grid_mesh(rows, sclosed, c1, cap)
    return (V, F, sclosed), ""


# ---- Revolve ----

def rotation_matrix(axis, ang):
    a = np.array(axis, dtype=np.float64)
    a = a / np.linalg.norm(a)
    K = np.array(((0, -a[2], a[1]), (a[2], 0, -a[0]), (-a[1], a[0], 0)))
    return np.eye(3) + math.sin(ang) * K + (1 - math.cos(ang)) * (K @ K)


def revolve_surface(paths, origin, axis, angle_deg, cap=True):
    """Révolution des contours autour de l'axe (origin, axis). Retourne (sommets, faces)."""
    full = abs(angle_deg) >= 359.999
    ang = math.radians(max(-360.0, min(360.0, angle_deg)))
    steps = max(6, int(math.ceil(abs(ang) / (2 * math.pi) * 64)))
    o = np.array(origin, dtype=np.float64)
    allV, allF = [], []
    base = 0
    for P, closed in paths:
        rows = []
        count = steps if full else steps + 1
        for s in range(count):
            Rm = rotation_matrix(axis, ang * s / steps)
            rows.append((P - o) @ Rm.T + o)
        V, F = grid_mesh(np.array(rows), closed, full, cap and not full)
        allV.append(V)
        allF.extend([tuple(i + base for i in f) for f in F])
        base += len(V)
    return np.vstack(allV), allF


class DESSIN_OT_revolve(DessinTransform):
    bl_idname = "dessin.revolve"
    bl_label = "Revolve"
    bl_description = ("Revolves curves around an axis defined by two points: select the curves, Enter, "
                      "axis start, axis end, then Enter for a full circle or type the angle (C: cap ends, D: delete input)")

    TITLE = "Revolve"
    NEEDED = 3
    NUMFIELDS = 1
    HAS_CENTER = True
    HAS_MODE = True
    EDIT_OK = False
    MODES = ("keep the input curves", "delete the input curves")
    NO_SELECTION = "Select the curves to revolve first"

    def invoke(self, context, event):
        self.mode = 0
        self._paths = None
        result = super().invoke(context, event)
        self.center = True          # cap activé par défaut (profil fermé, angle < 360°)
        if 'RUNNING_MODAL' in result:
            self.refresh(context)
        return result

    def prompt(self):
        n = len(self.points)
        if n == 0:
            return "start of the revolve axis"
        if n == 1:
            return "end of the revolve axis   (Shift: orthogonal)"
        cap = "cap ON" if self.center else "cap OFF"
        mode = self.MODES[self.mode]
        return f"angle: type degrees then Enter, or Enter / click for 360°   [C: cap ends ({cap}), D: {mode}]"

    def capture_ghost(self, max_edges=0):
        self.ghost_pts = None
        self.ghost_batch = None

    def apply_live(self, xform):
        pass

    def restore(self):
        pass

    def handle_typing(self, event):
        return len(self.points) >= 2 and super().handle_typing(event)

    def profile_paths(self, context):
        if self._paths is None:
            dg = bpy.context.evaluated_depsgraph_get()
            paths = []
            for obj, _m in self.items:
                try:
                    paths.extend(object_paths(obj, dg))
                except ReferenceError:
                    pass
            self._paths = paths
        return self._paths

    def click(self, context):
        if not self.points:
            self._paths = None
        super().click(context)

    def reset_state(self):
        self._paths = None
        super().reset_state()

    def modal(self, context, event):
        if (not self.selecting and len(self.points) == 2 and event.value == 'PRESS'
                and event.type in {'RET', 'NUMPAD_ENTER', 'SPACE'} and not any(self.typed)):
            self.finish_shape(context)
            if self.finished:
                return self.exit(context)
            return {'RUNNING_MODAL'}
        return super().modal(context, event)

    def axis_end(self):
        a = self.points[0]
        b = self.points[1] if len(self.points) > 1 else self.cur
        d = b - a
        if len(self.points) == 1 and self.ortho:
            u, v, _ = plane_axes(self.axis)
            du, dv = d.dot(u), d.dot(v)
            d = u * du if abs(du) >= abs(dv) else v * dv
        return a, d

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        a, d = self.axis_end()
        if d.length < 1e-9:
            return [], [], "", None
        ext = d.normalized() * max(d.length, 1e-3)
        axis_line = [a - ext * 3.0, a + ext * 4.0]
        if len(self.points) == 1:
            return [], [axis_line], f"Axis length {self.fmt(d.length)}", None
        ang = self.typed_raw(0)
        angle = 360.0 if ang is None else max(-360.0, min(360.0, ang))
        guides = [axis_line]
        paths = self.profile_paths(bpy.context)
        if paths and abs(angle) > 1e-6:
            for k in range(1, 13):
                Rm = rotation_matrix(d, math.radians(angle) * k / 12.0)
                o = np.array(a)
                for P, closed in paths[:20]:
                    Q = (P - o) @ Rm.T + o
                    guides.append([Vector(q) for q in (np.vstack([Q, Q[:1]]) if closed else Q)])
        info = f"Angle {angle:g}°"
        return [], guides, info, ("revolve", a.copy(), d.copy(), angle, bool(self.center), self.mode == 1)

    def build(self, context, spec):
        _, o, d, angle, cap, delete = spec
        objs = [obj for obj, _m in self.items if obj.name in bpy.data.objects]
        dg = bpy.context.evaluated_depsgraph_get()
        made = []
        for obj in objs:
            paths = object_paths(obj, dg)
            if not paths:
                continue
            V, F = revolve_surface(paths, o, d, angle, cap)
            made.append(mesh_object_from_arrays(context, "Revolve", V, F, o, True))
        if not made:
            self.report({'WARNING'}, "Revolve works on curves (or outlines without faces)")
            self.committed = True
            return None
        if delete:
            delete_objects(objs)
            self.items = []
        deselect_all_objects(context)
        for ob in made:
            ob.select_set(True)
        context.view_layer.objects.active = made[-1]
        self.committed = True
        return None


# ---- Extrude (mode objet) : courbes / contours / faces -> volume ou surface ----

def outline_paths(obj, depsgraph):
    """Contours d'un objet : courbes et polylignes, ou bord (arêtes à une seule face) d'un maillage à faces."""
    try:
        if obj.type == 'MESH' and len(obj.data.polygons):
            ev = obj.evaluated_get(depsgraph)
            me = ev.to_mesh()
            try:
                bm = bmesh.new()
                bm.from_mesh(me)
                bm.transform(ev.matrix_world)
                bm.edges.ensure_lookup_table()
                bound = [e for e in bm.edges if len(e.link_faces) == 1]
                if not bound:
                    bm.free()
                    return []
                ids = {}
                verts, edges = [], []
                for e in bound:
                    pair = []
                    for v in e.verts:
                        if v.index not in ids:
                            ids[v.index] = len(verts)
                            verts.append(tuple(v.co))
                        pair.append(ids[v.index])
                    edges.append(tuple(pair))
                bm.free()
            finally:
                ev.to_mesh_clear()
            out = []
            for path, closed in wire_paths(len(verts), edges):
                if len(path) >= 2:
                    P = np.array([verts[i] for i in path], dtype=np.float64)
                    if closed and len(P) > 1 and np.linalg.norm(P[0] - P[-1]) <= 1e-9:
                        P = P[:-1]
                    out.append((P, bool(closed)))
            return out
    except (RuntimeError, ReferenceError):
        return []
    return object_paths(obj, depsgraph)


def extrude_surface(paths, vec, cap=True):
    """Extrusion des contours le long de vec : (sommets, faces). Les contours fermés peuvent être bouchés (volume) :
    les bouchons suivent les trous (un contour dans un autre donne un anneau, pas un couvercle plein)."""
    allV, allF = [], []
    base = 0
    v = np.array(vec, dtype=np.float64)
    closed_paths = []
    for P, closed in paths:
        rows = np.stack([P, P + v])
        V, F = grid_mesh(rows, closed, False, False)
        allV.append(V)
        allF.extend([tuple(i + base for i in f) for f in F])
        base += len(V)
        if closed and len(P) >= 3:
            closed_paths.append((P, closed))
    if cap and closed_paths:
        regions = []
        try:
            regions, _skipped = planar_surfaces(closed_paths)
        except (ValueError, RuntimeError, TypeError, np.linalg.LinAlgError):
            regions = []
        if len(regions) == 0 or sum(len(F) for _V, F in regions) == 0:       # contours non plans : bouchons simples, comme avant
            for P, _closed in closed_paths:
                n = len(P)
                allV.append(np.vstack([P, P + v]))
                allF.append(tuple(base + i for i in range(n - 1, -1, -1)))
                allF.append(tuple(base + n + i for i in range(n)))
                base += 2 * n
        else:
            for Vr, Fr in regions:
                Vr = np.asarray(Vr, dtype=np.float64)
                allV.append(Vr)
                allF.extend(tuple(i + base for i in reversed(f)) for f in Fr)       # bas
                base += len(Vr)
                allV.append(Vr + v)
                allF.extend(tuple(i + base for i in f) for f in Fr)                  # haut
                base += len(Vr)
    return np.vstack(allV), allF


class ExtrudeCrvLogic(DessinTransform):
    bl_idname = "dessin.extrude_crv"
    bl_label = "Extrude Straight"
    bl_description = ("Extrudes curves, outlines or flat surfaces into a volume: select them, Enter, base point, then the height "
                      "(mouse or typed value, Enter). C: cap the ends, D: delete the input")

    TITLE = "Extrude"
    NEEDED = 2
    NUMFIELDS = 1
    HAS_CENTER = True
    HAS_MODE = True
    EDIT_OK = False
    PLANAR = False      # les points accrochés gardent leur hauteur
    MODES = ("keep the input curves", "delete the input curves")
    NO_SELECTION = "Select the curves or flat surfaces to extrude first"

    def invoke(self, context, event):
        self.mode = 0
        self._paths = None
        result = super().invoke(context, event)
        self.center = True          # bouchons activés par défaut (contour fermé -> volume)
        if 'RUNNING_MODAL' in result:
            self.refresh(context)
        return result

    def prompt(self):
        if not self.points:
            return "base point"
        cap = "cap ON" if self.center else "cap OFF"
        return (f"height: move the mouse or type the value then Enter   "
                f"[C: cap the ends ({cap}), D: {self.MODES[self.mode]}, Shift: orthogonal]")

    def capture_ghost(self, max_edges=0):
        self.ghost_pts = None
        self.ghost_batch = None

    def apply_live(self, xform):
        pass

    def restore(self):
        pass

    def can_confirm_typed(self):
        return len(self.points) >= 1

    def handle_typing(self, event):
        return len(self.points) >= 1 and super().handle_typing(event)

    def profile_paths(self, context):
        if self._paths is None:
            dg = bpy.context.evaluated_depsgraph_get()
            paths = []
            for obj, _m in self.items:
                try:
                    paths.extend(outline_paths(obj, dg))
                except ReferenceError:
                    pass
            self._paths = paths
        return self._paths

    def click(self, context):
        if not self.points:
            self._paths = None
        super().click(context)

    def reset_state(self):
        self._paths = None
        super().reset_state()

    def height_axis(self):
        return plane_axes(self.axis)[2]

    def update_cursor(self, context, event):
        """La hauteur suit la souris sur la verticale du point de base (et non sur le plan de construction, où elle resterait nulle)."""
        super().update_cursor(context, event)
        if (getattr(self, "selecting", False) or not self.points or self.cur is None
                or self.region is None or self.mouse_over_ui(event)):
            return
        if self.snap_screen is not None:
            # point accroché : sa hauteur compte, même si « Project » le ramène d'habitude dans le plan de construction
            raw = getattr(self, "_snap_pt", None)
            if raw is not None:
                n = self.height_axis()
                p0 = self.points[0]
                self.cur = p0 + n * (raw - p0).dot(n)
                self.refresh(context)
            return
        try:
            region = self.region
            rv3d = region_rv3d(region, self.area)
            coord = Vector((event.mouse_x - region.x, event.mouse_y - region.y))
            ro = region_2d_to_origin_3d(region, rv3d, coord)
            rv = region_2d_to_vector_3d(region, rv3d, coord)
            n = self.height_axis()
            p0 = self.points[0]
            hit = geometry.intersect_line_line(ro, ro + rv, p0, p0 + n)
        except (AttributeError, ReferenceError, TypeError, RuntimeError):
            return
        if hit is not None:
            self.cur = hit[1].copy()
            self.refresh(context)

    def height_vec(self):
        n = self.height_axis()
        d = self.cur - self.points[0]
        h = d.dot(n)
        t = self.typed_value(0)
        if t is not None:
            h = t if t < 0 else abs(t) * (1.0 if h >= 0 else -1.0)
        return n * h

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        vec = self.height_vec()
        if vec.length < 1e-9:
            return [], [], "", None
        guides = []
        for P, closed in self.profile_paths(bpy.context)[:20]:
            top = [Vector(p) + vec for p in P]
            if closed:
                top.append(top[0])
            guides.append(top)
            step = max(1, len(P) // 24)
            for p in P[::step]:
                guides.append([Vector(p), Vector(p) + vec])
        info = f"Height {self.fmt(vec.length)}"
        return [], guides, info, ("extrude", self.points[0].copy(), vec.copy(), bool(self.center), self.mode == 1)

    def build(self, context, spec):
        _, origin, vec, cap, delete = spec
        objs = [obj for obj, _m in self.items if obj.name in bpy.data.objects]
        dg = bpy.context.evaluated_depsgraph_get()
        made = []
        for obj in objs:
            paths = outline_paths(obj, dg)
            if not paths:
                continue
            V, F = extrude_surface(paths, vec, cap)
            made.append(mesh_object_from_arrays(context, "Extrusion", V, F, origin, True))
        if not made:
            self.report({'WARNING'}, "Extrude works on curves, outlines and flat surfaces")
            self.committed = True
            return None
        if delete:
            delete_objects(objs)
            self.items = []
        deselect_all_objects(context)
        for ob in made:
            ob.select_set(True)
        context.view_layer.objects.active = made[-1]
        self.committed = True
        return None


class DESSIN_OT_extrude_crv(ExtrudeCrvLogic):
    """Classe enregistrée (les sous-classes héritent de ExtrudeCrvLogic, non enregistrée : Blender perd le poll d'un parent enregistré)."""
    bl_idname = "dessin.extrude_crv"
    bl_label = "Extrude Straight"
    bl_description = ("Extrudes curves, outlines or flat surfaces into a volume: select them, Enter, base point, then the height "
                      "(mouse or typed value, Enter). C: cap the ends, D: delete the input")



class DESSIN_OT_extrude_srf(ExtrudeCrvLogic):
    bl_idname = "dessin.extrude_srf"
    bl_label = "Extrude Surface"
    bl_description = ("Extrudes surfaces (faces) into a solid along their normal: select them, Enter, base point, then the height "
                      "(mouse or typed value, Enter). C: cap the ends, D: delete the input")
    NO_SELECTION = "Select the surfaces to extrude first"

    def _normal(self):
        """Normale moyenne (monde) des surfaces sélectionnées."""
        total = Vector((0.0, 0.0, 0.0))
        for obj, _m in self.items:
            try:
                if obj.type != 'MESH':
                    continue
                M = obj.matrix_world.to_3x3()
                nm = M.inverted_safe().transposed()
                for p in obj.data.polygons:
                    total += (nm @ p.normal) * p.area
            except ReferenceError:
                pass
        if total.length < 1e-12:
            return plane_axes(self.axis)[2]
        return total.normalized()

    def height_axis(self):
        return self._normal()

    def height_vec(self):
        n = self._normal()
        d = self.cur - self.points[0]
        h = d.dot(n)
        t = self.typed_value(0)
        if t is not None:
            h = t if t < 0 else abs(t) * (1.0 if h >= 0 else -1.0)
        return n * h

    def build(self, context, spec):
        _, origin, vec, cap, delete = spec
        objs = [obj for obj, _m in self.items if obj.name in bpy.data.objects and obj.type == 'MESH' and len(obj.data.polygons)]
        dg = bpy.context.evaluated_depsgraph_get()
        made = []
        for obj in objs:
            ev = obj.evaluated_get(dg)
            me = ev.to_mesh()
            try:
                bm = bmesh.new()
                bm.from_mesh(me)
            finally:
                ev.to_mesh_clear()
            bm.transform(ev.matrix_world)
            bm.faces.ensure_lookup_table()
            bound = [e for e in bm.edges if len(e.link_faces) == 1]
            geom = list(bm.faces) + list(bm.edges) + list(bm.verts)
            ext = bmesh.ops.extrude_face_region(bm, geom=geom)
            new_verts = [g for g in ext["geom"] if isinstance(g, bmesh.types.BMVert)]
            bmesh.ops.translate(bm, verts=new_verts, vec=vec)
            if not cap:
                # sans bouchon : on ne garde que la face translatée et les parois
                bmesh.ops.delete(bm, geom=[f for f in bm.faces if f not in
                                           {g for g in ext["geom"] if isinstance(g, bmesh.types.BMFace)}
                                           and all(v not in new_verts for v in f.verts)], context='FACES')
            bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
            V = [tuple(v.co) for v in bm.verts]
            idx = {v: i for i, v in enumerate(bm.verts)}
            F = [tuple(idx[v] for v in f.verts) for f in bm.faces]
            bm.free()
            made.append(mesh_object_from_arrays(context, "Extrusion", V, F, origin, False))
        if not made:
            self.report({'WARNING'}, "Extrude Surface works on surfaces (meshes with faces)")
            self.committed = True
            return None
        if delete:
            delete_objects(objs)
            self.items = []
        deselect_all_objects(context)
        for ob in made:
            ob.select_set(True)
        context.view_layer.objects.active = made[-1]
        self.committed = True
        return None


# ---- Loft / Sweep / Align (sélection par clics puis Entrée, avec une fenêtre d'options comme sur Rhino) ----

class _ProfileOp:
    """Aide commune : contours des objets sélectionnés (dans l'ordre des clics)."""

    @classmethod
    def poll(cls, context):
        return context.mode == 'OBJECT' and context.area is not None and context.area.type == 'VIEW_3D'

    def profiles(self, context):
        dg = context.evaluated_depsgraph_get()
        objs, profs = [], []
        for o in ordered_selection(context):
            p = object_profile(o, dg)
            if p is not None:
                objs.append(o)
                profs.append(p)
        return objs, profs

    def finish(self, context, name, built, origin, delete, objs):
        V, F, closed = built
        out = mesh_object_from_arrays(context, name, V, F, origin, True)
        if delete:
            delete_objects(objs)
        deselect_all_objects(context)
        out.select_set(True)
        context.view_layer.objects.active = out
        return out


