# ---- Surfaces : Planar Surface / Edge Surface / Thicken / Cap ----

def _plane_of(P):
    """(centre, normale unitaire, écart max au plan, aire) d'un contour fermé (n,3)."""
    n = newell_normal(P)
    ln = float(np.linalg.norm(n))
    if ln < 1e-14:
        return None
    n = n / ln
    c = P.mean(axis=0)
    return c, n, float(np.abs((P - c) @ n).max()), ln * 0.5


def _point_in_poly(pt, poly):
    """Point dans polygone 2D (lancer de rayon)."""
    x, y = pt
    inside = False
    n = len(poly)
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]
        xj, yj = poly[j]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-30) + xi:
            inside = not inside
        j = i
    return inside


def planar_surfaces(paths):
    """Contours fermés -> surfaces planes (trous gérés par imbrication paire / impaire).
    Retourne ([(sommets, faces)], nb de contours ignorés)."""
    loops = []
    skipped = 0
    for P, closed in paths:
        if not closed or len(P) < 3:
            skipped += 1
            continue
        pl = _plane_of(P)
        scale = float(np.ptp(P, axis=0).max())
        if pl is None or pl[2] > max(1e-3 * scale, 1e-7):
            skipped += 1
            continue
        loops.append((P, pl))
    loops.sort(key=lambda t: -t[1][3])
    out = []
    while loops:
        P0, (c, n, _d, _a) = loops[0]
        scale = float(np.ptp(P0, axis=0).max())
        group, rest = [], []
        for item in loops:
            P, (_c2, n2, _d2, _a2) = item
            if abs(float(n.dot(n2))) > 0.9999 and float(np.abs((P - c) @ n).max()) <= max(1e-3 * scale, 1e-7):
                group.append(item)
            else:
                rest.append(item)
        loops = rest
        u = P0[1] - P0[0]
        u = u - n * float(u.dot(n))
        u = u / (np.linalg.norm(u) or 1.0)
        v = np.cross(n, u)
        flat = [np.stack([(P - c) @ u, (P - c) @ v], axis=1) for P, _pl in group]
        depth, parent = [], []
        for i in range(len(group)):
            cont = [j for j in range(len(group)) if j != i and group[j][1][3] > group[i][1][3]
                    and _point_in_poly(flat[i][0], flat[j])]
            depth.append(len(cont))
            parent.append(min(cont, key=lambda j: group[j][1][3]) if cont else None)
        for i in range(len(group)):
            if depth[i] % 2:
                continue
            holes = [j for j in range(len(group)) if depth[j] == depth[i] + 1 and parent[j] == i]
            rings = [i] + holes
            if not holes:
                V = group[i][0]
                F = [tuple(range(len(V)))]
            else:
                polys = [[Vector((float(p[0]), float(p[1]), 0.0)) for p in flat[k]] for k in rings]
                tris = geometry.tessellate_polygon(polys)
                V = np.vstack([group[k][0] for k in rings])
                F = [tuple(t) for t in tris]
            out.append((np.array(V, dtype=np.float64), F))
    return out, skipped


class DESSIN_OT_planar_srf(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.planar_srf"
    bl_label = "Planar Surface"
    bl_description = ("Creates planar surfaces from closed planar curves (curves inside another one become holes): "
                      "click the curves (or select them first), then Enter / Space")
    bl_options = {'REGISTER', 'UNDO'}

    delete_input: bpy.props.BoolProperty(name="Delete input", default=False)

    def invoke(self, context, event):
        return self.execute(context)

    def execute(self, context):
        dg = context.evaluated_depsgraph_get()
        objs = ordered_selection(context)
        paths = []
        used = []
        for o in objs:
            p = object_paths(o, dg)
            if p:
                paths.extend(p)
                used.append(o)
        if not paths:
            self.report({'INFO'}, "Click the closed planar curves, then Enter")
            return {'CANCELLED'}
        made, skipped = planar_surfaces(paths)
        if not made:
            self.report({'WARNING'}, "Planar Surface needs closed, planar curves")
            return {'CANCELLED'}
        deselect_all_objects(context)
        last = None
        for V, F in made:
            last = mesh_object_from_arrays(context, "Planar Surface", V, F, V.mean(axis=0), False)
            last.select_set(True)
        if self.delete_input:
            delete_objects(used)
        context.view_layer.objects.active = last
        msg = f"{len(made)} planar surface(s) created"
        if skipped:
            msg += f", {skipped} curve(s) ignored (open or not planar)"
        self.report({'INFO'}, msg)
        return {'FINISHED'}


def resample_path(P, n):
    """n+1 points régulièrement répartis (longueur d'arc) sur la polyligne P (n,3), de P[0] à P[-1]."""
    seg = np.linalg.norm(np.diff(P, axis=0), axis=1)
    s = np.concatenate([[0.0], np.cumsum(seg)])
    t = np.linspace(0.0, s[-1], n + 1)
    return np.stack([np.interp(t, s, P[:, k]) for k in range(3)], axis=1)


def edge_surface(curves, segments=24):
    """2 courbes : surface réglée ; 3 ou 4 courbes bout à bout : carreau de Coons. Retourne ((V, F), message)."""
    curves = [np.asarray(c, dtype=np.float64) for c in curves]
    k = len(curves)
    lens = [path_length(c, False) for c in curves]
    if min(lens) < 1e-9:
        return None, "A curve is too short"
    if k == 2:
        a, b = curves
        if np.linalg.norm(a[0] - b[0]) + np.linalg.norm(a[-1] - b[-1]) > np.linalg.norm(a[0] - b[-1]) + np.linalg.norm(a[-1] - b[0]):
            b = b[::-1]
        A, C = resample_path(a, segments), resample_path(b, segments)
        rows = np.stack([(1 - v) * A + v * C for v in np.linspace(0.0, 1.0, 3)])
        return grid_mesh(rows, False, False, False), ""
    if k not in (3, 4):
        return None, "Edge Surface needs 2, 3 or 4 curves"
    tol = 0.02 * max(lens)
    chain = [curves[0]]
    left = list(range(1, k))
    while left:
        end = chain[-1][-1]
        best = None
        for j in left:
            for flip in (False, True):
                c = curves[j][::-1] if flip else curves[j]
                d = float(np.linalg.norm(c[0] - end))
                if best is None or d < best[0]:
                    best = (d, j, c)
        if best[0] > tol:
            return None, "The curves must touch end to end"
        chain.append(best[2])
        left.remove(best[1])
    if float(np.linalg.norm(chain[-1][-1] - chain[0][0])) > tol:
        return None, "The curves must form a closed chain of 3 or 4 edges"
    la = (path_length(chain[0], False) + (path_length(chain[2], False) if k == 4 else 0.0)) / (2 if k == 4 else 1)
    lb = (path_length(chain[1], False) + (path_length(chain[3], False) if k == 4 else 0.0)) / (2 if k == 4 else 1)
    if k == 3:
        lb = max(lb, path_length(chain[2], False))
    nu = int(max(2, segments))
    nv = int(min(400, max(2, round(segments * lb / max(la, 1e-9)))))
    A = resample_path(chain[0], nu)
    B = resample_path(chain[1], nv)
    if k == 4:
        C = resample_path(chain[2][::-1], nu)
        D = resample_path(chain[3][::-1], nv)
    else:
        C = np.tile(B[-1], (nu + 1, 1))
        D = resample_path(chain[2][::-1], nv)
    p00, p10, p01, p11 = A[0], A[-1], C[0], C[-1]
    rows = []
    for j in range(nv + 1):
        v = j / nv
        row = []
        for i in range(nu + 1):
            u = i / nu
            S = ((1 - v) * A[i] + v * C[i] + (1 - u) * D[j] + u * B[j]
                 - ((1 - u) * (1 - v) * p00 + u * (1 - v) * p10 + (1 - u) * v * p01 + u * v * p11))
            row.append(S)
        rows.append(row)
    return grid_mesh(np.array(rows), False, False, False), ""


class DESSIN_OT_edge_srf(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.edge_srf"
    bl_label = "Edge Surface"
    bl_description = ("Creates a surface from 2, 3 or 4 curves touching end to end: click the curves, then Enter / Space")
    bl_options = {'REGISTER', 'UNDO'}

    segments: bpy.props.IntProperty(name="Segments", default=24, min=2, max=400,
                                    description="Number of subdivisions along the first edge")
    delete_input: bpy.props.BoolProperty(name="Delete input", default=False)

    def invoke(self, context, event):
        return self.execute(context)

    def execute(self, context):
        dg = context.evaluated_depsgraph_get()
        objs, profs = self.profiles(context)
        if len(profs) < 2:
            self.report({'INFO'}, "Click 2, 3 or 4 curves, then Enter")
            return {'CANCELLED'}
        if len(profs) > 4:
            self.report({'WARNING'}, "Edge Surface works with 2 to 4 curves")
            return {'CANCELLED'}
        built, msg = edge_surface([p[0] for p in profs], self.segments)
        if built is None:
            self.report({'WARNING'}, msg)
            return {'CANCELLED'}
        V, F = built
        out = mesh_object_from_arrays(context, "Edge Surface", V, F, np.asarray(V).mean(axis=0), False)
        if self.delete_input:
            delete_objects(objs)
        deselect_all_objects(context)
        out.select_set(True)
        context.view_layer.objects.active = out
        return {'FINISHED'}


class DESSIN_OT_thicken(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.thicken"
    bl_label = "Thicken"
    bl_description = ("Gives a thickness to surfaces, making solids: click the surfaces (or select them first), Enter / Space, "
                      "then the thickness and the direction")
    bl_options = {'REGISTER', 'UNDO'}

    thickness: bpy.props.FloatProperty(name="Thickness", default=0.02, min=1e-6, subtype='DISTANCE', unit='LENGTH')
    direction: bpy.props.EnumProperty(name="Direction", default='NORMAL',
                                      items=(('NORMAL', "Along the normal", ""),
                                             ('OPPOSITE', "Opposite to the normal", ""),
                                             ('BOTH', "Both sides (centered)", "")))
    delete_input: bpy.props.BoolProperty(name="Delete input", default=True)

    def invoke(self, context, event):
        if not [o for o in context.selected_objects if o.type == 'MESH' and len(o.data.polygons)]:
            self.report({'INFO'}, "Click the surfaces to thicken, then Enter")
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self, width=300)

    def draw(self, context):
        col = self.layout.column()
        col.prop(self, "thickness")
        col.prop(self, "direction", text="")
        col.prop(self, "delete_input")

    def execute(self, context):
        targets = [o for o in context.selected_objects if o.type == 'MESH' and len(o.data.polygons)]
        if not targets:
            self.report({'INFO'}, "Click the surfaces to thicken, then Enter")
            return {'CANCELLED'}
        made = []
        for obj in targets:
            if self.direction == 'BOTH':
                me = offset_surface_mesh(obj, self.thickness * 0.5, True, True)
            else:
                me = offset_surface_mesh(obj, self.thickness * (1.0 if self.direction == 'NORMAL' else -1.0), True, False)
            new = bpy.data.objects.new("Thick " + obj.name, me)
            new.matrix_world = obj.matrix_world.copy()
            for c in (obj.users_collection or [context.scene.collection]):
                c.objects.link(new)
            made.append(new)
        if self.delete_input:
            delete_objects(targets)
        deselect_all_objects(context)
        for ob in made:
            ob.select_set(True)
        context.view_layer.objects.active = made[-1]
        return {'FINISHED'}


def _is_cutter(o):
    return o.type == 'CURVE' or (o.type == 'MESH' and len(o.data.polygons) == 0 and len(o.data.edges) > 0)


class DESSIN_OT_split_face(bpy.types.Operator):
    bl_idname = "dessin.split_face"
    bl_label = "Split Face"
    bl_description = ("Splits the faces of a surface along curves or polylines drawn on it, seen from the current view: "
                      "click the surface and the curves, then Enter / Space")
    bl_options = {'REGISTER', 'UNDO'}

    cut_through: bpy.props.BoolProperty(name="Through the whole object", default=False,
                                        description="Also cut the faces hidden behind the first one")
    separate: bpy.props.BoolProperty(name="Separate the pieces", default=False,
                                     description="Make the area inside the curves a separate object")
    delete_curves: bpy.props.BoolProperty(name="Delete the curves", default=False)

    @staticmethod
    def _view(context):
        area = context.area if (context.area and context.area.type == 'VIEW_3D') else None
        if area is None:
            for a in context.window.screen.areas:
                if a.type == 'VIEW_3D':
                    area = a
                    break
        if area is None:
            return None, None
        reg = next((r for r in area.regions if r.type == 'WINDOW'), None)
        return area, reg

    def invoke(self, context, event):
        sel = ordered_selection(context, ('MESH', 'CURVE'))
        if not [o for o in sel if not _is_cutter(o)] or not [o for o in sel if _is_cutter(o)]:
            self.report({'INFO'}, "Click the surface, then the curves drawn on it, then Enter")
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self, width=300)

    def draw(self, context):
        col = self.layout.column()
        col.prop(self, "cut_through")
        col.prop(self, "separate")
        col.prop(self, "delete_curves")

    def execute(self, context):
        sel = ordered_selection(context, ('MESH', 'CURVE'))
        cutters = [o for o in sel if _is_cutter(o)]
        targets = [o for o in sel if not _is_cutter(o)]
        if not targets or not cutters:
            self.report({'INFO'}, "Click the surface, then the curves drawn on it, then Enter")
            return {'CANCELLED'}
        area, reg = self._view(context)
        if area is None:
            self.report({'WARNING'}, "A 3D view is needed: the cut follows what you see")
            return {'CANCELLED'}
        win = context.window
        made, cut = [], 0
        for tgt in targets:
            for o in context.view_layer.objects:
                o.select_set(False)
            tgt.select_set(True)
            context.view_layer.objects.active = tgt
            before = len(tgt.data.polygons)
            try:
                bpy.ops.object.mode_set(mode='EDIT')
                bpy.ops.mesh.select_all(action='DESELECT')
                for c in cutters:
                    c.select_set(True)
                with context.temp_override(window=win, area=area, region=reg):
                    bpy.ops.mesh.knife_project(cut_through=self.cut_through)
                if self.separate:
                    bm = bmesh.from_edit_mesh(tgt.data)
                    if any(f.select for f in bm.faces):
                        names = {o.name for o in bpy.data.objects}
                        bpy.ops.mesh.separate(type='SELECTED')
                        made += [o for o in bpy.data.objects if o.name not in names]
            except RuntimeError as exc:
                self.report({'WARNING'}, "Cut failed on %s: %s" % (tgt.name, exc))
            finally:
                if context.object and context.object.mode != 'OBJECT':
                    bpy.ops.object.mode_set(mode='OBJECT')
            cut += max(0, len(tgt.data.polygons) - before)
        for o in context.view_layer.objects:
            o.select_set(False)
        if self.delete_curves:
            delete_objects(cutters)
        for o in targets + made:
            if o.name in bpy.data.objects:
                o.select_set(True)
        context.view_layer.objects.active = targets[0]
        if cut == 0 and not made:
            self.report({'WARNING'}, "Nothing was cut: the curves must be seen over the surface from the current view")
            return {'CANCELLED'}
        self.report({'INFO'}, "Face split")
        return {'FINISHED'}


def project_curve_paths(paths, targets, depsgraph, mode, both, view_dir):
    """Projette des contours (points monde) sur des maillages : liste de (points (n,3), fermé)."""
    from mathutils.bvhtree import BVHTree
    trees = []
    lo, hi = None, None
    for t in targets:
        try:
            tree = BVHTree.FromObject(t, depsgraph)
        except Exception:
            continue
        M = t.matrix_world.copy()
        trees.append((tree, M, M.inverted_safe()))
        bb = np.array([tuple(M @ Vector(c)) for c in t.bound_box])
        lo = bb.min(axis=0) if lo is None else np.minimum(lo, bb.min(axis=0))
        hi = bb.max(axis=0) if hi is None else np.maximum(hi, bb.max(axis=0))
    if not trees:
        return []
    diag = float(np.linalg.norm(hi - lo)) or 1.0
    step = diag / 150.0
    out = []
    for P, closed in paths:
        if mode == 'AUTO':
            pl = _plane_of(P) if len(P) >= 3 else None
            if pl is not None and pl[2] <= max(1e-3 * float(np.ptp(P, axis=0).max()), 1e-7):
                d = pl[1]
            else:
                d = np.array([0.0, 0.0, -1.0])
        elif mode == 'VIEW':
            d = np.array(view_dir, dtype=np.float64)
        else:
            d = {'X': np.array([1.0, 0, 0]), 'Y': np.array([0, 1.0, 0]), 'Z': np.array([0, 0, -1.0])}[mode]
        d = d / (np.linalg.norm(d) or 1.0)
        Q = [P[0]]
        n = len(P)
        for i in range(n if closed else n - 1):
            a, b = P[i], P[(i + 1) % n]
            k = max(1, min(200, int(math.ceil(float(np.linalg.norm(b - a)) / step))))
            for j in range(1, k + 1):
                Q.append(a + (b - a) * (j / k))
        if closed:
            Q = Q[:-1]
        hits = []
        for q in Q:
            best = None
            for tree, M, Mi in trees:
                o = Mi @ Vector(q)
                for sgn in ((1.0, -1.0) if both else (1.0,)):
                    dl = (Mi.to_3x3() @ Vector(d * sgn))
                    ln = dl.length
                    if ln < 1e-12:
                        continue
                    loc, nor, idx, dist = tree.ray_cast(o, dl / ln)
                    if loc is None:
                        continue
                    w = M @ loc
                    t = (w - Vector(q)).length
                    if best is None or t < best[0]:
                        best = (t, np.array(w))
            hits.append(None if best is None else best[1])
        if closed and all(h is not None for h in hits):
            out.append((np.array(hits), True))
            continue
        if closed:
            k0 = next(i for i, h in enumerate(hits) if h is None)
            hits = hits[k0:] + hits[:k0]
        chain = []
        for h in hits + [None]:
            if h is None:
                if len(chain) >= 2:
                    out.append((np.array(chain), False))
                chain = []
            else:
                chain.append(h)
    return out


class DESSIN_OT_project_curve(bpy.types.Operator):
    bl_idname = "dessin.project_curve"
    bl_label = "Project Curve"
    bl_description = ("Projects curves onto surfaces: click the curves, then the surface(s), then Enter / Space. "
                      "The projected curves can then be used with Split Face or Trim")
    bl_options = {'REGISTER', 'UNDO'}

    direction: bpy.props.EnumProperty(
        name="Direction", default='AUTO',
        items=(('AUTO', "Perpendicular to the curve's plane", "Falls back to straight down for non-planar curves"),
               ('Z', "Along Z (down)", ""), ('X', "Along X", ""), ('Y', "Along Y", ""),
               ('VIEW', "Current view", "")))
    both_ways: bpy.props.BoolProperty(name="Both ways", default=True,
                                      description="Also look behind the curve, not only in the projection direction")
    delete_input: bpy.props.BoolProperty(name="Delete the original curves", default=False)

    def _split(self, context):
        sel = ordered_selection(context, ('MESH', 'CURVE'))
        return [o for o in sel if _is_cutter(o)], [o for o in sel if not _is_cutter(o)]

    def invoke(self, context, event):
        cur, tgt = self._split(context)
        if not cur or not tgt:
            self.report({'INFO'}, "Click the curves, then the surface(s), then Enter")
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self, width=320)

    def draw(self, context):
        col = self.layout.column()
        col.prop(self, "direction", text="")
        col.prop(self, "both_ways")
        col.prop(self, "delete_input")

    def execute(self, context):
        cur, tgt = self._split(context)
        if not cur or not tgt:
            self.report({'INFO'}, "Click the curves, then the surface(s), then Enter")
            return {'CANCELLED'}
        dg = context.evaluated_depsgraph_get()
        view_dir = (0.0, 0.0, -1.0)
        rv = None
        if context.area and context.area.type == 'VIEW_3D':
            rv = context.area.spaces.active.region_3d
        else:
            for a in context.window.screen.areas:
                if a.type == 'VIEW_3D':
                    rv = a.spaces.active.region_3d
                    break
        if rv is not None:
            v = rv.view_rotation @ Vector((0.0, 0.0, -1.0))
            view_dir = (v.x, v.y, v.z)
        made = []
        for c in cur:
            paths = object_paths(c, dg)
            chains = project_curve_paths(paths, tgt, dg, self.direction, self.both_ways, view_dir)
            if chains:
                made.append((c, chains))
        if not made:
            self.report({'WARNING'}, "Nothing to project: the curves do not face the surface in this direction")
            return {'CANCELLED'}
        for o in context.view_layer.objects:
            o.select_set(False)
        last = None
        count = 0
        for c, chains in made:
            last = build_edge_object(context, "Projected " + c.name, [(Q, cl) for Q, cl in chains])
            last.select_set(True)
            count += len(chains)
        if self.delete_input:
            delete_objects([c for c, _ in made])
        context.view_layer.objects.active = last
        self.report({'INFO'}, "%d projected curve(s)" % count)
        return {'FINISHED'}


def patch_surface(P, density):
    """Surface de remplissage (membrane) dans un contour fermé 3D (n,3) monde. Retourne (V, F) ou None."""
    from mathutils.geometry import delaunay_2d_cdt
    V2v = Vector
    c = P.mean(axis=0)
    _u, _s, vt = np.linalg.svd(P - c)
    ax_u, ax_v, nrm = vt[0], vt[1], vt[2]
    diag = float(np.linalg.norm(np.ptp(P, axis=0))) or 1.0
    L = diag / max(6, density)
    # contour rééchantillonné
    B = []
    n = len(P)
    for i in range(n):
        a, b = P[i], P[(i + 1) % n]
        k = max(1, int(math.ceil(float(np.linalg.norm(b - a)) / L)))
        for j in range(k):
            B.append(a + (b - a) * (j / k))
    B = np.array(B)
    nb = len(B)
    uv = np.stack([(B - c) @ ax_u, (B - c) @ ax_v], axis=1)
    umin, vmin = uv.min(axis=0)
    umax, vmax = uv.max(axis=0)
    gu = np.arange(umin + L * 0.5, umax, L)
    gv = np.arange(vmin + L * 0.5, vmax, L)
    G = np.array([(x, y) for x in gu for y in gv]) if len(gu) and len(gv) else np.zeros((0, 2))
    if len(G):
        inside = np.zeros(len(G), dtype=bool)
        for i in range(nb):
            x1, y1 = uv[i]
            x2, y2 = uv[(i + 1) % nb]
            cond = ((y1 > G[:, 1]) != (y2 > G[:, 1]))
            xint = (x2 - x1) * (G[:, 1] - y1) / ((y2 - y1) or 1e-30) + x1
            inside ^= cond & (G[:, 0] < xint)
        dmin = np.min(np.linalg.norm(G[:, None, :] - uv[None, :, :], axis=2), axis=1)
        G = G[inside & (dmin > 0.6 * L)]
    pts2 = [V2v((float(x), float(y))) for x, y in uv] + [V2v((float(x), float(y))) for x, y in G]
    faces_in = [list(range(nb))]
    try:
        vo, eo, fo, ov, oe, of = delaunay_2d_cdt(pts2, [], faces_in, 1, 1e-7)
    except Exception:
        return None
    if not fo:
        return None
    ni = len(G)
    m = len(vo)
    # correspondance : sommets de sortie -> entrée
    mp = []
    for k in range(m):
        src = ov[k]
        mp.append(src[0] if src else -1)
    if any(s < 0 for s in mp):
        return None
    pos = np.zeros((m, 3))
    fixed = np.zeros(m, dtype=bool)
    for k, s in enumerate(mp):
        if s < nb:
            pos[k] = B[s]
            fixed[k] = True
        else:
            g = G[s - nb]
            pos[k] = c + ax_u * g[0] + ax_v * g[1]
    free = np.where(~fixed)[0]
    if len(free) > 3500:
        return None
    if len(free):
        idx = {int(v): i for i, v in enumerate(free)}
        nbrs = [set() for _ in range(m)]
        for f in fo:
            for i in range(len(f)):
                a, b = f[i], f[(i + 1) % len(f)]
                nbrs[a].add(b)
                nbrs[b].add(a)
        A = np.zeros((len(free), len(free)))
        rhs = np.zeros((len(free), 3))
        for v in free:
            i = idx[int(v)]
            A[i, i] = len(nbrs[v])
            for w in nbrs[v]:
                if fixed[w]:
                    rhs[i] += pos[w]
                else:
                    A[i, idx[int(w)]] -= 1.0
        try:
            sol = np.linalg.solve(A, rhs)
        except np.linalg.LinAlgError:
            return None
        pos[free] = sol
    F = [tuple(f) for f in fo]
    return pos, F


class DESSIN_OT_patch(bpy.types.Operator):
    bl_idname = "dessin.patch"
    bl_label = "Patch"
    bl_description = ("Fills a closed outline with a smooth surface (like a stretched membrane): click closed curves, "
                      "or a surface with a hole (its open edges are filled), then Enter / Space")
    bl_options = {'REGISTER', 'UNDO'}

    density: bpy.props.IntProperty(name="Density", default=24, min=8, max=80,
                                   description="Number of divisions across the outline: more = finer surface")
    delete_input: bpy.props.BoolProperty(name="Delete input", default=False)

    def _loops(self, context):
        dg = context.evaluated_depsgraph_get()
        loops, used = [], []
        for o in ordered_selection(context):
            got = False
            if o.type == 'MESH' and len(o.data.polygons):
                for lp in _surface_loops(o):
                    if lp['closed'] and len(lp['P']) >= 3:
                        loops.append(np.array(lp['P'], dtype=np.float64))
                        got = True
            else:
                for P, closed in object_paths(o, dg):
                    if closed and len(P) >= 3:
                        loops.append(np.array(P, dtype=np.float64))
                        got = True
            if got:
                used.append(o)
        return loops, used

    def invoke(self, context, event):
        loops, _u = self._loops(context)
        if not loops:
            self.report({'INFO'}, "Click closed curves (or a surface with a hole), then Enter")
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self, width=280)

    def draw(self, context):
        col = self.layout.column()
        col.prop(self, "density")
        col.prop(self, "delete_input")

    def execute(self, context):
        loops, used = self._loops(context)
        if not loops:
            self.report({'INFO'}, "Click closed curves (or a surface with a hole), then Enter")
            return {'CANCELLED'}
        for o in context.view_layer.objects:
            o.select_set(False)
        last, failed = None, 0
        for P in loops:
            r = patch_surface(P, self.density)
            if r is None:
                failed += 1
                continue
            V, F = r
            last = mesh_object_from_arrays(context, "Patch", V, F, V.mean(axis=0), True)
            last.select_set(True)
        if last is None:
            self.report({'WARNING'}, "Patch failed: the outline must be closed, not self-crossing, and not too complex")
            return {'CANCELLED'}
        if self.delete_input:
            delete_objects(used)
        context.view_layer.objects.active = last
        if failed:
            self.report({'WARNING'}, "%d outline(s) could not be filled" % failed)
        return {'FINISHED'}


def cap_mesh(me, planar_only=True):
    """Bouche les trous (bords ouverts) d'un maillage. Retourne (nb bouchés, nb ignorés)."""
    bm = bmesh.new()
    bm.from_mesh(me)
    bm.verts.ensure_lookup_table()
    bm.edges.ensure_lookup_table()
    bound = [e for e in bm.edges if len(e.link_faces) == 1]
    capped = skipped = 0
    if bound:
        ids = {}
        verts = []
        edges = []
        for e in bound:
            pair = []
            for v in e.verts:
                if v.index not in ids:
                    ids[v.index] = len(verts)
                    verts.append(v)
                pair.append(ids[v.index])
            edges.append(tuple(pair))
        for path, closed in wire_paths(len(verts), edges):
            if not closed or len(path) < 3:
                skipped += 1
                continue
            vs = [verts[i] for i in path]
            if vs[0] == vs[-1]:
                vs = vs[:-1]
            P = np.array([tuple(v.co) for v in vs])
            pl = _plane_of(P)
            scale = float(np.ptp(P, axis=0).max()) if len(P) else 0.0
            flat = pl is not None and pl[2] <= max(1e-4 * scale, 1e-7)
            if planar_only and not flat:
                skipped += 1
                continue
            # sens : l'arête du bord doit être parcourue à l'envers par la nouvelle face
            e0 = bm.edges.get((vs[0], vs[1]))
            if e0 is not None and e0.link_faces:
                f = e0.link_faces[0]
                for lp in f.loops:
                    if lp.vert == vs[0] and lp.link_loop_next.vert == vs[1]:
                        vs = vs[::-1]
                        break
                    if lp.vert == vs[1] and lp.link_loop_next.vert == vs[0]:
                        break
            try:
                if flat:
                    bm.faces.new(vs)
                else:
                    es = [bm.edges.get((vs[i], vs[(i + 1) % len(vs)])) for i in range(len(vs))]
                    bmesh.ops.triangle_fill(bm, use_beauty=True, use_dissolve=False, edges=[x for x in es if x])
                capped += 1
            except ValueError:
                skipped += 1
    bm.to_mesh(me)
    bm.free()
    me.update()
    return capped, skipped


class DESSIN_OT_cap(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.cap"
    bl_label = "Cap"
    bl_description = ("Closes the open ends of surfaces to make solids: click the objects (or select them first), Enter / Space")
    bl_options = {'REGISTER', 'UNDO'}

    planar_only: bpy.props.BoolProperty(name="Planar holes only", default=True,
                                        description="Only caps holes whose edge is flat (off: fills any hole with triangles)")

    def invoke(self, context, event):
        return self.execute(context)

    def execute(self, context):
        targets = [o for o in context.selected_objects if o.type == 'MESH' and len(o.data.polygons)]
        if not targets:
            self.report({'INFO'}, "Click the open surfaces to cap, then Enter")
            return {'CANCELLED'}
        done = skipped = 0
        for obj in targets:
            c, s = cap_mesh(obj.data, self.planar_only)
            done += c
            skipped += s
        if not done:
            self.report({'WARNING'}, "Nothing to cap" + (f" ({skipped} hole(s) not flat)" if skipped else ""))
            return {'CANCELLED'}
        self.report({'INFO'}, f"{done} hole(s) capped" + (f", {skipped} ignored" if skipped else ""))
        return {'FINISHED'}


# ---- Surfaces (lot 2) : Blend / Match / Rail Revolve / Shell ----

def _densify(P, closed, step):
    """Points régulièrement espacés (≈ step) le long d'une polyligne."""
    P = np.asarray(P, dtype=np.float64)
    if closed:
        P = np.vstack([P, P[:1]])
    L = path_length(P, False)
    n = int(min(4000, max(2, L / max(step, 1e-9))))
    return resample_path(P, n)


def _surface_loops(obj):
    """Bords d'un maillage à faces, en coordonnées monde :
    [{'ids': [indices de sommets], 'closed': bool, 'P': (n,3), 'out': (nseg,3) direction sortante de chaque segment}]"""
    me = obj.data
    M = np.array(obj.matrix_world, dtype=np.float64)
    co = np.empty(len(me.vertices) * 3)
    me.vertices.foreach_get('co', co)
    world = co.reshape(-1, 3) @ M[:3, :3].T + M[:3, 3]
    bm = bmesh.new()
    bm.from_mesh(me)
    bm.edges.ensure_lookup_table()
    outward = {}
    edges = []
    ids = {}
    verts = []
    for e in bm.edges:
        if len(e.link_faces) != 1:
            continue
        a, b = e.verts[0].index, e.verts[1].index
        fc = np.array(e.link_faces[0].calc_center_median(), dtype=np.float64) @ M[:3, :3].T + M[:3, 3]
        t = world[b] - world[a]
        ln = float(np.linalg.norm(t))
        if ln < 1e-12:
            continue
        t /= ln
        d = (world[a] + world[b]) * 0.5 - fc
        d = d - t * float(d.dot(t))
        dn = float(np.linalg.norm(d))
        outward[(min(a, b), max(a, b))] = d / dn if dn > 1e-12 else np.zeros(3)
        pair = []
        for v in (a, b):
            if v not in ids:
                ids[v] = len(verts)
                verts.append(v)
            pair.append(ids[v])
        edges.append(tuple(pair))
    bm.free()
    out = []
    for path, closed in wire_paths(len(verts), edges):
        vid = [verts[i] for i in path]
        if closed and len(vid) > 1 and vid[0] == vid[-1]:
            vid = vid[:-1]
        if len(vid) < 2:
            continue
        n = len(vid)
        nseg = n if closed else n - 1
        segs = np.array([outward.get((min(vid[i], vid[(i + 1) % n]), max(vid[i], vid[(i + 1) % n])), np.zeros(3))
                         for i in range(nseg)])
        out.append({'ids': vid, 'closed': bool(closed), 'P': world[vid], 'out': segs})
    return out


def _edge_candidates(obj, depsgraph):
    """Bords utilisables d'un objet : surface (bords + sens sortant) ou courbe (chemins, sans sens)."""
    if obj.type == 'MESH' and len(obj.data.polygons):
        return _surface_loops(obj)
    return [{'ids': None, 'closed': bool(c), 'P': np.asarray(P, dtype=np.float64), 'out': None}
            for P, c in object_paths(obj, depsgraph)]


def _facing_run(loop, other_pts, spacing):
    """Plus longue suite continue de segments de `loop` qui regardent `other_pts` (distance minimale).
    Retourne (indices de position dans loop['P'], segments sortants correspondants)."""
    P = loop['P']
    n = len(P)
    closed = loop['closed']
    nseg = n if closed else n - 1
    if nseg < 1:
        return None
    a = P[:nseg]
    b = P[(np.arange(nseg) + 1) % n]
    mids = (a + b) * 0.5
    d = np.empty(nseg)
    for s in range(0, nseg, 512):
        blk = mids[s:s + 512]
        d[s:s + 512] = np.sqrt(((blk[:, None, :] - other_pts[None, :, :]) ** 2).sum(axis=2)).min(axis=1)
    thr = float(d.min()) * 1.02 + spacing
    keep = d <= thr
    if keep.all():
        segs = list(range(nseg))
    else:
        if closed:
            s0 = int(np.argmin(keep))                      # un segment qui ne regarde pas : point de départ
            order = [(s0 + 1 + k) % nseg for k in range(nseg)]
        else:
            order = list(range(nseg))
        best, cur = [], []
        for i in order:
            if keep[i]:
                cur.append(i)
            else:
                if len(cur) > len(best):
                    best = cur
                cur = []
        if len(cur) > len(best):
            best = cur
        segs = best
    if not segs:
        return None
    idx = [segs[0]] + [(s + 1) % n for s in segs]
    return idx, (loop['out'][segs] if loop['out'] is not None else None)


def _blend_edges(objA, objB, depsgraph):
    """Choisit les deux bords qui se font face. Retourne (run A, run B) = (points (n,3), sortants (n-1,3) ou None)."""
    ca, cb = _edge_candidates(objA, depsgraph), _edge_candidates(objB, depsgraph)
    if not ca or not cb:
        return None
    allp = np.vstack([l['P'] for l in ca + cb])
    diag = float(np.linalg.norm(allp.max(axis=0) - allp.min(axis=0))) or 1.0
    step = diag / 250.0
    da = [_densify(l['P'], l['closed'], step) for l in ca]
    db = [_densify(l['P'], l['closed'], step) for l in cb]
    best = None
    for i, A in enumerate(da):
        for j, B in enumerate(db):
            d = float(np.sqrt(((A[::max(1, len(A) // 120), None, :] - B[None, ::max(1, len(B) // 120), :]) ** 2).sum(axis=2)).min())
            if best is None or d < best[0]:
                best = (d, i, j)
    _d, i, j = best
    ra = _facing_run(ca[i], db[j], step)
    rb = _facing_run(cb[j], da[i], step)
    if ra is None or rb is None:
        return None
    return (ca[i]['P'][ra[0]], ra[1]), (cb[j]['P'][rb[0]], rb[1])


def _nearest_dir(samples, run_pts, run_out):
    """Direction sortante du segment le plus proche de chaque échantillon."""
    if run_out is None:
        return np.zeros_like(samples)
    mids = (run_pts[:-1] + run_pts[1:]) * 0.5
    d = ((samples[:, None, :] - mids[None, :, :]) ** 2).sum(axis=2)
    return run_out[d.argmin(axis=1)]


def blend_surface(runA, runB, tangent=True, tension=1.0, segments=24, rows_n=12):
    """Surface de raccord entre deux bords : réglée (position) ou hermite (tangence avec les surfaces)."""
    (PA, oA), (PB, oB) = runA, runB
    if path_length(PA, False) < 1e-9 or path_length(PB, False) < 1e-9:
        return None, "An edge is too short"
    if np.linalg.norm(PA[0] - PB[0]) + np.linalg.norm(PA[-1] - PB[-1]) > np.linalg.norm(PA[0] - PB[-1]) + np.linalg.norm(PA[-1] - PB[0]):
        PB = PB[::-1]
        oB = oB[::-1] if oB is not None else None
    n = int(max(segments, 8))
    A = resample_path(PA, n)
    B = resample_path(PB, n)
    gap = np.linalg.norm(B - A, axis=1)
    if float(gap.max()) < 1e-9:
        return None, "The edges are already touching"
    rows = []
    ts = np.linspace(0.0, 1.0, int(max(rows_n, 2)) + 1) if tangent else np.array([0.0, 1.0])
    if tangent:
        dA = _nearest_dir(A, PA, oA)
        dB = _nearest_dir(B, PB if oB is not None else PB, oB)
        L = (gap * float(tension))[:, None]
        # un sens sortant opposé à la direction du raccord est inversé (surface dont les normales sont à l'envers)
        flipA = (dA * (B - A)).sum(axis=1) < 0
        flipB = (dB * (A - B)).sum(axis=1) < 0
        dA[flipA] *= -1.0
        dB[flipB] *= -1.0
    for t in ts:
        if tangent:
            h00, h10, h01, h11 = 2 * t ** 3 - 3 * t ** 2 + 1, t ** 3 - 2 * t ** 2 + t, -2 * t ** 3 + 3 * t ** 2, t ** 3 - t ** 2
            rows.append(h00 * A + h10 * dA * L + h01 * B - h11 * dB * L)
        else:
            rows.append((1 - t) * A + t * B)
    return grid_mesh(np.array(rows), False, False, False), ""


_BLEND = {"on": False, "last": None}
BLEND_COLORS = {"hover": (1.0, 0.85, 0.2, 1.0), "A": (1.0, 0.35, 0.25, 1.0), "B": (0.25, 0.8, 1.0, 1.0)}


def _blend_collect(context):
    """Bords utilisables de tous les objets visibles (surfaces : bords ouverts ; courbes : chemins)."""
    dg = context.evaluated_depsgraph_get()
    loops = []
    for ob in context.visible_objects:
        if ob.type not in {'MESH', 'CURVE'} or "dessin_cotation" in ob.keys():
            continue
        try:
            cands = _edge_candidates(ob, dg)
        except (RuntimeError, ReferenceError, ValueError, TypeError, AttributeError):
            continue
        for l in cands:
            if len(l['P']) >= 2:
                loops.append(dict(l, obj=ob.name))
        if len(loops) > 4000:
            break
    return loops


def _blend_run(loop, segs):
    """Plus longue suite continue de segments choisis. Retourne (points (n,3), sortants ou None)."""
    P = np.asarray(loop['P'], dtype=np.float64)
    n = len(P)
    closed = loop['closed']
    nseg = n if closed else n - 1
    keep = np.zeros(nseg, dtype=bool)
    for s in segs:
        if 0 <= s < nseg:
            keep[s] = True
    if not keep.any():
        return None
    if keep.all():
        order = list(range(nseg))
    elif closed:
        s0 = int(np.argmin(keep))
        order = [(s0 + 1 + k) % nseg for k in range(nseg)]
    else:
        order = list(range(nseg))
    best, cur = [], []
    for i in order:
        if keep[i]:
            cur.append(i)
        else:
            if len(cur) > len(best):
                best = cur
            cur = []
    if len(cur) > len(best):
        best = cur
    idx = [best[0]] + [(s + 1) % n for s in best]
    out = np.asarray(loop['out'], dtype=np.float64)[best] if loop['out'] is not None else None
    return P[idx], out


def blend_surface2(runA, runB, contA='TANGENT', contB='TANGENT', tenA=1.0, tenB=1.0, segments=24, rows_n=12):
    """Raccord entre deux bords, continuité réglable de chaque côté (position / tangence / courbure approchée)."""
    (PA, oA), (PB, oB) = runA, runB
    if path_length(PA, False) < 1e-9 or path_length(PB, False) < 1e-9:
        return None, "An edge is too short"
    if np.linalg.norm(PA[0] - PB[0]) + np.linalg.norm(PA[-1] - PB[-1]) > np.linalg.norm(PA[0] - PB[-1]) + np.linalg.norm(PA[-1] - PB[0]):
        PB = PB[::-1]
        oB = oB[::-1] if oB is not None else None
    n = int(max(segments, 8))
    A = resample_path(PA, n)
    B = resample_path(PB, n)
    chord = B - A
    gap = np.linalg.norm(chord, axis=1)
    if float(gap.max()) < 1e-9:
        return None, "The edges are already touching"
    unit = chord / np.maximum(gap, 1e-12)[:, None]
    if contA == 'POSITION' and contB == 'POSITION':
        ts = np.array([0.0, 1.0])
        return grid_mesh(np.array([(1 - t) * A + t * B for t in ts]), False, False, False), ""
    dA = _nearest_dir(A, PA, oA) if contA != 'POSITION' else np.zeros_like(A)
    dB = _nearest_dir(B, PB, oB) if contB != 'POSITION' else np.zeros_like(B)
    flipA = (dA * chord).sum(axis=1) < 0
    flipB = (dB * -chord).sum(axis=1) < 0
    dA[flipA] *= -1.0
    dB[flipB] *= -1.0
    badA = np.linalg.norm(dA, axis=1) < 1e-9          # côté sans direction (position, courbe) : on suit la corde
    badB = np.linalg.norm(dB, axis=1) < 1e-9
    dA[badA] = unit[badA]
    dB[badB] = -unit[badB]
    TA = dA * (gap * float(tenA))[:, None]
    TB = -dB * (gap * float(tenB))[:, None]            # sens de parcours à l'arrivée
    quintic = contA == 'CURVATURE' or contB == 'CURVATURE'
    rows = []
    for t in np.linspace(0.0, 1.0, int(max(rows_n, 2)) + 1):
        if quintic:
            H0 = 1 - 10 * t ** 3 + 15 * t ** 4 - 6 * t ** 5
            H1 = t - 6 * t ** 3 + 8 * t ** 4 - 3 * t ** 5
            H4 = -4 * t ** 3 + 7 * t ** 4 - 3 * t ** 5
            H5 = 10 * t ** 3 - 15 * t ** 4 + 6 * t ** 5
            rows.append(H0 * A + H1 * TA + H4 * TB + H5 * B)
        else:
            h00, h10, h01, h11 = 2 * t ** 3 - 3 * t ** 2 + 1, t ** 3 - 2 * t ** 2 + t, -2 * t ** 3 + 3 * t ** 2, t ** 3 - t ** 2
            rows.append(h00 * A + h10 * TA + h01 * B + h11 * TB)
    return grid_mesh(np.array(rows), False, False, False), ""


def blend_draw_cb(op):
    """Surligne l'arête survolée et les arêtes déjà choisies (1er bord, 2e bord)."""
    try:
        loops = op.loops
        layers = [("hover", op.hover_pts()), ("A", op.pick_pts(0)), ("B", op.pick_pts(1))]
    except (AttributeError, ReferenceError, RuntimeError):
        return
    shader = get_shader('3D')
    shader.bind()
    gpu.state.blend_set('ALPHA')
    gpu.state.depth_test_set('NONE')
    for key, pts in layers:
        if not pts:
            continue
        gpu.state.line_width_set(5.0 if key == "hover" else 4.0)
        shader.uniform_float("color", BLEND_COLORS[key])
        batch_for_shader(shader, 'LINES', {"pos": pts}).draw(shader)
    gpu.state.line_width_set(1.0)


class DESSIN_OT_blend_srf(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.blend_srf"
    bl_label = "Blend Surface"
    bl_description = ("Creates a smooth surface between two edges, like Rhino: click the first edge (C: chain the connected edges), "
                      "Enter, click the second edge, Enter. Then adjust the continuity and tension of each side in the panel")
    bl_options = {'REGISTER', 'UNDO'}

    cont_a: bpy.props.EnumProperty(name="Continuity 1", default='TANGENT',
                                   items=(('POSITION', "Position", "The surface touches the first edge"),
                                          ('TANGENT', "Tangency", "Leaves the first surface along its own direction"),
                                          ('CURVATURE', "Curvature (approximate)", "Smoother start: tangency with a flat curvature profile")))
    cont_b: bpy.props.EnumProperty(name="Continuity 2", default='TANGENT',
                                   items=(('POSITION', "Position", "The surface touches the second edge"),
                                          ('TANGENT', "Tangency", "Reaches the second surface along its own direction"),
                                          ('CURVATURE', "Curvature (approximate)", "Smoother end: tangency with a flat curvature profile")))
    tension_a: bpy.props.FloatProperty(name="Tension 1", default=1.0, min=0.0, soft_max=3.0,
                                       description="Length of the tangent on the first side (1: the distance between the edges)")
    tension_b: bpy.props.FloatProperty(name="Tension 2", default=1.0, min=0.0, soft_max=3.0,
                                       description="Length of the tangent on the second side")
    lock: bpy.props.BoolProperty(name="Lock tensions", default=True, description="Tension 2 follows tension 1")
    segments: bpy.props.IntProperty(name="Segments", default=24, min=4, max=400)
    steps: bpy.props.IntProperty(name="Rows", default=12, min=2, max=100, description="Subdivisions across the blend")
    delete_input: bpy.props.BoolProperty(name="Delete input", default=False)

    # ---- sélection interactive des bords ----
    def invoke(self, context, event):
        if _BLEND["on"]:
            return {'CANCELLED', 'PASS_THROUGH'}
        if event.type == 'LEFTMOUSE' and event.value == 'PRESS' and context.area is not None and cmd_click_idle(context, event):
            return {'CANCELLED'}
        region = find_window_region(context.area, event.mouse_x, event.mouse_y)
        if region is None and event.type == 'MOUSEMOVE':
            return {'CANCELLED', 'PASS_THROUGH'}
        self.area = context.area
        self.region = region or next((r for r in context.area.regions if r.type == 'WINDOW'), None)
        if self.region is None:
            return {'CANCELLED'}
        self.loops = _blend_collect(context)
        if not self.loops:
            self.report({'INFO'}, "No open edge found: blend needs surfaces with open edges or curves")
            return {'CANCELLED'}
        segA, segB, lid, sid = [], [], [], []
        for li, l in enumerate(self.loops):
            P = np.asarray(l['P'], dtype=np.float64)
            n = len(P)
            nseg = n if l['closed'] else n - 1
            segA.append(P[:nseg])
            segB.append(P[(np.arange(nseg) + 1) % n])
            lid.append(np.full(nseg, li))
            sid.append(np.arange(nseg))
        self.SA, self.SB = np.vstack(segA), np.vstack(segB)
        self.LID, self.SID = np.concatenate(lid), np.concatenate(sid)
        self.phase = 0
        self.picks = [None, None]
        self.chain = True
        self.hover = None
        self.mouse = (event.mouse_x - self.region.x, event.mouse_y - self.region.y)
        _BLEND["on"] = True
        self.handle = bpy.types.SpaceView3D.draw_handler_add(blend_draw_cb, (self,), 'WINDOW', 'POST_VIEW')
        context.window_manager.modal_handler_add(self)
        self.update_hover()
        if event.type == 'LEFTMOUSE':
            self.click(event)
        self.prompt()
        return {'RUNNING_MODAL'}

    def prompt(self):
        which = "first" if self.phase == 0 else "second"
        txt = (f"Blend Surface: select the {which} edge   [ChainEdges: {'Yes' if self.chain else 'No'} (C)  ·  Shift: add  ·  Ctrl: remove  ·  "
               f"Enter: done  ·  Backspace: clear  ·  Esc: cancel]")
        set_prompt(self.area, txt)

    def end_modal(self, context):
        if getattr(self, "handle", None) is not None:
            bpy.types.SpaceView3D.draw_handler_remove(self.handle, 'WINDOW')
            self.handle = None
        _BLEND["on"] = False
        set_prompt(self.area, "")
        try:
            self.area.tag_redraw()
        except (AttributeError, ReferenceError):
            pass

    def update_hover(self):
        self.hover = None
        rv3d = region_rv3d(self.region, self.area)
        if rv3d is None or not len(self.SA):
            return
        persp = np.array(rv3d.perspective_matrix, dtype=np.float64)
        ax, ay, oka = _project_region(self.SA, persp, self.region)
        bx, by, okb = _project_region(self.SB, persp, self.region)
        mx, my = self.mouse
        dx, dy = bx - ax, by - ay
        ll = np.maximum(dx * dx + dy * dy, 1e-12)
        t = np.clip(((mx - ax) * dx + (my - ay) * dy) / ll, 0.0, 1.0)
        d = np.hypot(ax + dx * t - mx, ay + dy * t - my)
        d = np.where(oka & okb, d, 1e9)
        k = int(d.argmin())
        if d[k] <= 14.0 * px_scale():
            self.hover = (int(self.LID[k]), int(self.SID[k]))

    def segs_of(self, li, si):
        l = self.loops[li]
        n = len(l['P'])
        nseg = n if l['closed'] else n - 1
        return set(range(nseg)) if self.chain else {si}

    def seg_points(self, li, segs):
        l = self.loops[li]
        P = np.asarray(l['P'], dtype=np.float64)
        n = len(P)
        pts = []
        for s in sorted(segs):
            pts.append(tuple(P[s]))
            pts.append(tuple(P[(s + 1) % n]))
        return pts

    def hover_pts(self):
        if self.hover is None:
            return []
        li, si = self.hover
        return self.seg_points(li, self.segs_of(li, si))

    def pick_pts(self, phase):
        p = self.picks[phase]
        return self.seg_points(p['li'], p['segs']) if p else []

    def click(self, event):
        mx, my = event.mouse_x - self.region.x, event.mouse_y - self.region.y
        self.mouse = (mx, my)
        self.update_hover()
        if self.hover is None:
            return
        li, si = self.hover
        segs = self.segs_of(li, si)
        cur = self.picks[self.phase]
        if cur is not None and cur['li'] == li and event.ctrl:
            cur['segs'] -= segs
            if not cur['segs']:
                self.picks[self.phase] = None
        elif cur is not None and cur['li'] == li and event.shift:
            cur['segs'] |= segs
        else:
            self.picks[self.phase] = {'li': li, 'segs': set(segs)}

    def modal(self, context, event):
        et, ev = event.type, event.value
        try:
            self.area.tag_redraw()
        except ReferenceError:
            self.end_modal(context)
            return {'CANCELLED'}
        if et == 'ESC' and ev == 'PRESS':
            self.end_modal(context)
            back_to_idle()
            return {'CANCELLED'}
        if et == 'MOUSEMOVE':
            self.mouse = (event.mouse_x - self.region.x, event.mouse_y - self.region.y)
            self.update_hover()
            return {'PASS_THROUGH'}
        if et == 'LEFTMOUSE' and ev == 'PRESS':
            if event.alt or event.oskey:
                return {'PASS_THROUGH'}
            if find_window_region(self.area, event.mouse_x, event.mouse_y) is None or cmd_hit(self.area, event.mouse_x, event.mouse_y) is not None:
                return {'PASS_THROUGH'}
            self.click(event)
            return {'RUNNING_MODAL'}
        if et == 'C' and ev == 'PRESS' and not (event.ctrl or event.alt or event.oskey):
            self.chain = not self.chain
            self.prompt()
            return {'RUNNING_MODAL'}
        if et == 'BACK_SPACE' and ev == 'PRESS':
            self.picks[self.phase] = None
            return {'RUNNING_MODAL'}
        if et in {'RET', 'NUMPAD_ENTER', 'SPACE'} and ev == 'PRESS':
            if self.picks[self.phase] is None:
                self.report({'INFO'}, "Click an edge first")
                return {'RUNNING_MODAL'}
            if self.phase == 0:
                self.phase = 1
                self.prompt()
                return {'RUNNING_MODAL'}
            runs = [_blend_run(self.loops[p['li']], p['segs']) for p in self.picks]
            names = [self.loops[p['li']]['obj'] for p in self.picks]
            if runs[0] is None or runs[1] is None:
                self.report({'WARNING'}, "No usable edge in the selection")
                return {'RUNNING_MODAL'}
            _BLEND["last"] = (runs[0], runs[1], names)
            self.end_modal(context)
            res = self.execute(context)
            if 'FINISHED' in res:
                idle_tool()
            return res
        return {'PASS_THROUGH'}

    def draw(self, context):
        col = self.layout.column()
        col.prop(self, "cont_a", text="1")
        col.prop(self, "cont_b", text="2")
        col.prop(self, "lock")
        col.prop(self, "tension_a", text="Tension 1")
        sub = col.column()
        sub.enabled = not self.lock
        sub.prop(self, "tension_b", text="Tension 2")
        col.prop(self, "segments")
        col.prop(self, "steps")
        col.prop(self, "delete_input")

    def execute(self, context):
        last = _BLEND["last"]
        if last is None:
            self.report({'WARNING'}, "Pick the two edges first")
            return {'CANCELLED'}
        runA, runB, names = last
        tb = self.tension_a if self.lock else self.tension_b
        built, msg = blend_surface2(runA, runB, self.cont_a, self.cont_b, self.tension_a, tb, self.segments, self.steps)
        if built is None:
            self.report({'WARNING'}, msg)
            return {'CANCELLED'}
        V, F = built
        out = mesh_object_from_arrays(context, "Blend Surface", V, F, np.asarray(V).mean(axis=0), False)
        if self.delete_input:
            delete_objects([bpy.data.objects[n] for n in set(names) if n in bpy.data.objects])
        deselect_all_objects(context)
        out.select_set(True)
        context.view_layer.objects.active = out
        return {'FINISHED'}


def _closest_on_polyline(pt, P):
    """Point le plus proche de pt sur la polyligne P (n,3)."""
    a, b = P[:-1], P[1:]
    ab = b - a
    ll = np.maximum((ab * ab).sum(axis=1), 1e-24)
    t = np.clip(((pt - a) * ab).sum(axis=1) / ll, 0.0, 1.0)
    q = a + ab * t[:, None]
    return q[((q - pt) ** 2).sum(axis=1).argmin()]


class DESSIN_OT_match_srf(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.match_srf"
    bl_label = "Match Surface"
    bl_description = ("Moves the edge of the first clicked surface onto the facing edge of the second one (optionally keeping "
                      "tangent continuity): click the surface to change, then the target, then Enter / Space")
    bl_options = {'REGISTER', 'UNDO'}

    continuity: bpy.props.EnumProperty(name="Continuity", default='POSITION',
                                       items=(('POSITION', "Position", "The edge touches the target edge"),
                                              ('TANGENT', "Tangent", "The next row of points also follows the target surface")))

    def invoke(self, context, event):
        objs = ordered_selection(context)
        if len(objs) != 2 or objs[0].type != 'MESH' or not len(objs[0].data.polygons):
            self.report({'INFO'}, "Click the surface to change, then the target surface (or curve), then Enter")
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self, width=280)

    def draw(self, context):
        self.layout.prop(self, "continuity", text="")

    def execute(self, context):
        objs = ordered_selection(context)
        if len(objs) != 2 or objs[0].type != 'MESH' or not len(objs[0].data.polygons):
            self.report({'WARNING'}, "Select the surface to change, then the target")
            return {'CANCELLED'}
        src, dst = objs
        dg = context.evaluated_depsgraph_get()
        loops = _surface_loops(src)
        cands = _edge_candidates(dst, dg)
        if not loops or not cands:
            self.report({'WARNING'}, "No open edge found")
            return {'CANCELLED'}
        allp = np.vstack([l['P'] for l in loops + cands])
        diag = float(np.linalg.norm(allp.max(axis=0) - allp.min(axis=0))) or 1.0
        step = diag / 250.0
        dd = [_densify(l['P'], l['closed'], step) for l in cands]
        best = None
        for i, l in enumerate(loops):
            A = _densify(l['P'], l['closed'], step)
            for j, B in enumerate(dd):
                d = float(np.sqrt(((A[::max(1, len(A) // 120), None, :] - B[None, ::max(1, len(B) // 120), :]) ** 2).sum(axis=2)).min())
                if best is None or d < best[0]:
                    best = (d, i, j)
        _d, i, j = best
        runA = _facing_run(loops[i], dd[j], step)
        runB = _facing_run(cands[j], _densify(loops[i]['P'], loops[i]['closed'], step), step)
        if runA is None or runB is None:
            self.report({'WARNING'}, "No facing edges found")
            return {'CANCELLED'}
        pos, _outA = runA
        ids = [loops[i]['ids'][k] for k in pos]
        PB, oB = cands[j]['P'][runB[0]], runB[1]
        me = src.data
        M = np.array(src.matrix_world, dtype=np.float64)
        Mi = np.linalg.inv(M)
        co = np.empty(len(me.vertices) * 3)
        me.vertices.foreach_get('co', co)
        co = co.reshape(-1, 3)
        world = co @ M[:3, :3].T + M[:3, 3]
        new = world.copy()
        moved = {}
        for vid in ids:
            q = _closest_on_polyline(world[vid], PB)
            moved[vid] = q
            new[vid] = q
        if self.continuity == 'TANGENT' and oB is not None:
            mids = (PB[:-1] + PB[1:]) * 0.5
            nbr = {}
            for e in me.edges:
                a, b = e.vertices
                if a in moved and b not in moved:
                    nbr.setdefault(b, []).append(a)
                elif b in moved and a not in moved:
                    nbr.setdefault(a, []).append(b)
            for v, srcs in nbr.items():
                s = srcs[0]
                q = moved[s]
                k = int(((mids - q) ** 2).sum(axis=1).argmin())
                direction = oB[k]                      # la surface cible se prolonge dans le sens sortant de son bord
                length = float(np.linalg.norm(world[v] - world[s]))
                if float(np.linalg.norm(direction)) > 1e-9:
                    new[v] = q + direction * length
        loc = new @ Mi[:3, :3].T + Mi[:3, 3]
        me.vertices.foreach_set('co', loc.ravel())
        me.update()
        self.report({'INFO'}, f"{len(ids)} point(s) matched")
        return {'FINISHED'}


def rail_revolve(profile, pclosed, rail, origin, axis, cap=True, steps=96):
    """Révolution du profil autour de l'axe, guidée par le rail : le rayon (et la hauteur) du profil suivent ceux du rail.
    Retourne ((V, F), message)."""
    a = np.asarray(axis, dtype=np.float64)
    a = a / np.linalg.norm(a)
    helper = np.array([1.0, 0.0, 0.0]) if abs(a[0]) < 0.9 else np.array([0.0, 1.0, 0.0])
    e1 = np.cross(a, helper)
    e1 /= np.linalg.norm(e1)
    e2 = np.cross(a, e1)
    o = np.asarray(origin, dtype=np.float64)

    def cyl(P):
        rel = np.asarray(P, dtype=np.float64) - o
        return np.hypot(rel @ e1, rel @ e2), np.arctan2(rel @ e2, rel @ e1), rel @ a

    rr, rphi, rh = cyl(rail)
    rphi = np.unwrap(rphi)
    if len(rphi) < 2 or abs(rphi[-1] - rphi[0]) < math.radians(1.0):
        return None, "The rail must go around the axis"
    if rphi[-1] < rphi[0]:
        rr, rphi, rh = rr[::-1], rphi[::-1], rh[::-1]
    dphi = np.diff(rphi)
    if (dphi < -1e-6).any():
        return None, "The rail must go around the axis in a single direction"
    keep = np.concatenate([[True], dphi > 1e-9])
    rr, rphi, rh = rr[keep], rphi[keep], rh[keep]
    span = float(rphi[-1] - rphi[0])
    full = span >= 2 * math.pi * 0.995
    if span > 2 * math.pi:
        span = 2 * math.pi
    if rr[0] < 1e-9:
        return None, "The rail starts on the axis"
    pr, pphi, ph = cyl(profile)
    pphi = np.unwrap(pphi)
    pphi = pphi - pphi[0]
    n_rows = int(max(steps, 8))
    phis = rphi[0] + np.linspace(0.0, span, n_rows + 1)
    if full:
        phis = phis[:-1]
    rows = []
    for ph_i in phis:
        k = float(np.interp(ph_i, rphi, rr)) / float(rr[0])
        dh = float(np.interp(ph_i, rphi, rh)) - float(rh[0])
        ang = pphi + (ph_i - rphi[0]) + math.atan2(float((np.asarray(profile[0]) - o) @ e2), float((np.asarray(profile[0]) - o) @ e1))
        rows.append(o + (pr * k * np.cos(ang))[:, None] * e1 + (pr * k * np.sin(ang))[:, None] * e2 + (ph + dh)[:, None] * a)
    return grid_mesh(np.array(rows), bool(pclosed), bool(full), bool(cap and not full)), ""


class DESSIN_OT_rail_revolve(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.rail_revolve"
    bl_label = "Rail Revolve"
    bl_description = ("Revolves a profile around an axis while a rail curve controls the radius: click the profile, then the rail "
                      "(then optionally a straight line for the axis), then Enter / Space")
    bl_options = {'REGISTER', 'UNDO'}

    axis: bpy.props.EnumProperty(name="Axis", default='Z',
                                 items=(('Z', "Z axis", "Vertical axis through the centre of the rail"),
                                        ('X', "X axis", "Axis along X through the centre of the rail"),
                                        ('Y', "Y axis", "Axis along Y through the centre of the rail"),
                                        ('LINE', "Third curve", "A straight third curve gives the axis")))
    steps: bpy.props.IntProperty(name="Segments", default=96, min=8, max=720)
    cap: bpy.props.BoolProperty(name="Cap ends", default=True)
    delete_input: bpy.props.BoolProperty(name="Delete input", default=False)

    def invoke(self, context, event):
        objs, profs = self.profiles(context)
        if len(profs) < 2:
            self.report({'INFO'}, "Click the profile, then the rail (then an axis line), then Enter")
            return {'CANCELLED'}
        self.axis = 'LINE' if len(profs) >= 3 else ('Z' if self.axis == 'LINE' else self.axis)
        return context.window_manager.invoke_props_dialog(self, width=300)

    def draw(self, context):
        col = self.layout.column()
        col.prop(self, "axis", text="")
        col.prop(self, "steps")
        col.prop(self, "cap")
        col.prop(self, "delete_input")

    def execute(self, context):
        objs, profs = self.profiles(context)
        if len(profs) < 2:
            self.report({'WARNING'}, "Select the profile and the rail")
            return {'CANCELLED'}
        profile, pclosed = profs[0][0], bool(profs[0][1])
        rail = profs[1][0]
        if self.axis == 'LINE' and len(profs) >= 3:
            ax = profs[2][0]
            axis = ax[-1] - ax[0]
            if float(np.linalg.norm(axis)) < 1e-9:
                self.report({'WARNING'}, "The axis line is too short")
                return {'CANCELLED'}
            origin = ax[0]
        else:
            axis = np.array({'X': (1.0, 0.0, 0.0), 'Y': (0.0, 1.0, 0.0)}.get(self.axis, (0.0, 0.0, 1.0)))
            c = (np.asarray(rail).min(axis=0) + np.asarray(rail).max(axis=0)) * 0.5
            origin = c - axis * float(c.dot(axis))
        built, msg = rail_revolve(profile, pclosed, rail, origin, axis, self.cap, self.steps)
        if built is None:
            self.report({'WARNING'}, msg)
            return {'CANCELLED'}
        V, F = built
        out = mesh_object_from_arrays(context, "Rail Revolve", V, F, np.asarray(origin), True)
        if self.delete_input:
            delete_objects(objs)
        deselect_all_objects(context)
        out.select_set(True)
        context.view_layer.objects.active = out
        return {'FINISHED'}


class DESSIN_OT_shell(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.shell"
    bl_label = "Shell"
    bl_description = ("Hollows out solids, keeping a wall thickness: click the solids (or select them first), Enter / Space, then the "
                      "thickness and the face(s) to remove")
    bl_options = {'REGISTER', 'UNDO'}

    thickness: bpy.props.FloatProperty(name="Wall thickness", default=0.02, min=1e-6, subtype='DISTANCE', unit='LENGTH')
    side: bpy.props.EnumProperty(name="Wall", default='INSIDE',
                                 items=(('INSIDE', "Inside", "The outer shape stays the same"),
                                        ('OUTSIDE', "Outside", "The inner shape stays the same")))
    open_face: bpy.props.EnumProperty(name="Open face", default='TOP',
                                      items=(('NONE', "None (closed cavity)", "Hollow without any opening"),
                                             ('TOP', "Top", "Removes the top face"),
                                             ('BOTTOM', "Bottom", "Removes the bottom face"),
                                             ('LARGEST', "Largest face", "Removes the face with the largest area"),
                                             ('SELECTED', "Selected faces", "Removes the faces selected in Edit Mode")))
    delete_input: bpy.props.BoolProperty(name="Delete input", default=True)

    def invoke(self, context, event):
        if not [o for o in context.selected_objects if o.type == 'MESH' and len(o.data.polygons)]:
            self.report({'INFO'}, "Click the solids to hollow out, then Enter")
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self, width=300)

    def draw(self, context):
        col = self.layout.column()
        col.prop(self, "thickness")
        col.prop(self, "side", expand=True)
        col.prop(self, "open_face", text="")
        col.prop(self, "delete_input")

    def execute(self, context):
        targets = [o for o in context.selected_objects if o.type == 'MESH' and len(o.data.polygons)]
        if not targets:
            self.report({'INFO'}, "Click the solids to hollow out, then Enter")
            return {'CANCELLED'}
        made = []
        for obj in targets:
            me = shell_mesh(obj, self.thickness, self.side == 'INSIDE', self.open_face)
            new = bpy.data.objects.new("Shell " + obj.name, me)
            new.matrix_world = obj.matrix_world.copy()
            for c in (obj.users_collection or [context.scene.collection]):
                c.objects.link(new)
            made.append(new)
        if self.delete_input:
            delete_objects(targets)
        deselect_all_objects(context)
        for ob in made:
            ob.select_set(True)
        context.view_layer.objects.active = made[-1]
        return {'FINISHED'}


def shell_mesh(obj, thickness, inside, open_face):
    """Maillage évidé : retire la ou les faces d'ouverture puis donne une épaisseur de paroi."""
    me = obj.data
    bm = bmesh.new()
    bm.from_mesh(me)
    bm.faces.ensure_lookup_table()
    closed_solid = all(len(e.link_faces) == 2 for e in bm.edges)
    if closed_solid:
        bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    sx = obj.matrix_world.to_3x3()
    remove = []
    if open_face == 'SELECTED':
        remove = [f for f in bm.faces if me.polygons[f.index].select]
    elif open_face in ('TOP', 'BOTTOM'):
        sign = 1.0 if open_face == 'TOP' else -1.0
        cand = []
        for f in bm.faces:
            nw = (sx @ f.normal).normalized()
            if nw.z * sign > 0.9:
                cand.append((f, (obj.matrix_world @ f.calc_center_median()).z * sign))
        if cand:
            best = max(z for _f, z in cand)
            tol = 1e-4 * max(1.0, abs(best))
            remove = [f for f, z in cand if z >= best - tol]
    elif open_face == 'LARGEST':
        remove = [max(bm.faces, key=lambda f: f.calc_area())]
    if remove:
        bmesh.ops.delete(bm, geom=remove, context='FACES_ONLY')
        bm.faces.ensure_lookup_table()
        loose = [e for e in bm.edges if not e.link_faces]
        if loose:
            bmesh.ops.delete(bm, geom=loose, context='EDGES')
        loose_v = [v for v in bm.verts if not v.link_edges]
        if loose_v:
            bmesh.ops.delete(bm, geom=loose_v, context='VERTS')
    t = abs(thickness) if inside else -abs(thickness)
    bmesh.ops.solidify(bm, geom=list(bm.faces), thickness=t)
    out = bpy.data.meshes.new("Shell " + me.name)
    bm.to_mesh(out)
    bm.free()
    for m in me.materials:
        out.materials.append(m)
    return out


def object_bounds(obj):
    """(min, max) de la boîte englobante de l'objet, en coordonnées monde."""
    mw = obj.matrix_world
    pts = np.array([tuple(mw @ Vector(c)) for c in obj.bound_box])
    return pts.min(axis=0), pts.max(axis=0)


_ALIGN_ITEMS = lambda a, b, c: (('NONE', "None", "Do not move along this axis"),
                                ('MIN', a, ""), ('CENTER', b, ""), ('MAX', c, ""))


class DESSIN_OT_align(_ProfileOp, bpy.types.Operator):
    bl_idname = "dessin.align"
    bl_label = "Align"
    bl_description = ("Aligns the selected objects along their bounding boxes (left / center / right, front / center / back, "
                      "bottom / center / top) on the selection, the last clicked object or the world origin")
    bl_options = {'REGISTER', 'UNDO'}

    x_mode: bpy.props.EnumProperty(name="X", default='NONE', items=_ALIGN_ITEMS("Left", "Center", "Right"))
    y_mode: bpy.props.EnumProperty(name="Y", default='NONE', items=_ALIGN_ITEMS("Front", "Center", "Back"))
    z_mode: bpy.props.EnumProperty(name="Z", default='NONE', items=_ALIGN_ITEMS("Bottom", "Center", "Top"))
    reference: bpy.props.EnumProperty(name="Align to", default='SELECTION',
                                      items=(('SELECTION', "Selection", "Bounding box of all the selected objects"),
                                             ('ACTIVE', "Last clicked object", "The last clicked object stays in place"),
                                             ('WORLD', "World origin", "Align on the world axes")))

    def invoke(self, context, event):
        if not context.selected_objects:
            self.report({'INFO'}, "Click the objects to align, then Enter")
            return {'CANCELLED'}
        return context.window_manager.invoke_props_dialog(self, width=320)

    def draw(self, context):
        col = self.layout.column()
        col.label(text="Align along:")
        for prop in ("x_mode", "y_mode", "z_mode"):
            row = col.row()
            row.prop(self, prop, expand=True)
        col.separator()
        col.prop(self, "reference")

    def execute(self, context):
        objs = [o for o in context.selected_objects]
        modes = (self.x_mode, self.y_mode, self.z_mode)
        if not objs or all(m == 'NONE' for m in modes):
            self.report({'INFO'}, "Choose at least one alignment")
            return {'CANCELLED'}
        bounds = {o.name: object_bounds(o) for o in objs}
        if self.reference == 'SELECTION':
            lo = np.min([b[0] for b in bounds.values()], axis=0)
            hi = np.max([b[1] for b in bounds.values()], axis=0)
        elif self.reference == 'ACTIVE':
            act = context.view_layer.objects.active
            if act is None or act.name not in bounds:
                act = objs[-1]
            lo, hi = bounds[act.name]
            objs = [o for o in objs if o is not act]
        else:
            lo = hi = np.zeros(3)
        ref = {'MIN': lo, 'CENTER': (lo + hi) * 0.5, 'MAX': hi}
        moved = 0
        for o in objs:
            b0, b1 = bounds[o.name]
            mine = {'MIN': b0, 'CENTER': (b0 + b1) * 0.5, 'MAX': b1}
            delta = Vector((0.0, 0.0, 0.0))
            for k, m in enumerate(modes):
                if m != 'NONE':
                    delta[k] = float(ref[m][k] - mine[m][k])
            if delta.length > 1e-12:
                mw = o.matrix_world.copy()
                mw.translation += delta
                o.matrix_world = mw
                moved += 1
        self.report({'INFO'}, f"Aligned {moved} object(s)")
        return {'FINISHED'}


# --------------------------------------------------------------------------
# Make2D : dessin 2D (lignes visibles / cachées) des objets sélectionnés, selon une vue du plugin
# --------------------------------------------------------------------------

MAKE2D_LIMIT = 60000          # arêtes candidates maximum (au-delà : on prévient)


def named_view_rotation(scene, name):
    """Rotation (quaternion) d'une vue nommée du plugin : vue enregistrée, sinon vue de base."""
    entry = find_view(scene, name)
    if entry is not None:
        return Quaternion_(entry.rot)
    axis = dict(BASE_VIEWS).get(name)
    return _axis_quat(axis)


def make2d_view_items(self, context):
    scene = context.scene
    items = [(n, view_label(scene, n), "") for n, _a in BASE_VIEWS]
    items += [(v.name, v.name, "") for v in scene.dessin_views if not v.base]
    make2d_view_items.cache = items
    return items


make2d_view_items.cache = []


def mesh_world_data(obj, depsgraph):
    """(sommets monde [Vector], triangles, bmesh monde) d'un objet, d'après sa forme évaluée (modificateurs compris)."""
    ev = obj.evaluated_get(depsgraph)
    me = ev.to_mesh()
    bm = bmesh.new()
    bm.from_mesh(me)
    ev.to_mesh_clear()
    bm.transform(obj.matrix_world)
    bm.normal_update()
    return bm


def make2d_collect(objs, depsgraph):
    """Rassemble les maillages des objets : bmesh monde par objet + arbre BVH global (occultation)."""
    from mathutils.bvhtree import BVHTree
    bms, verts, tris = [], [], []
    for o in objs:
        try:
            bm = mesh_world_data(o, depsgraph)
        except (RuntimeError, AttributeError, TypeError):
            continue
        bms.append((o, bm))
        base = len(verts)
        verts.extend(v.co.copy() for v in bm.verts)
        for lt in bm.calc_loop_triangles():
            tris.append(tuple(base + l.vert.index for l in lt))
    bvh = BVHTree.FromPolygons(verts, tris, epsilon=0.0) if tris else None
    return bms, bvh, verts


def make2d_project(bms, bvh, quat, diag, tangent=False, hidden=False, sharp_deg=25.0):
    """Projette les arêtes caractéristiques selon la rotation `quat` (projection parallèle, l'observateur regarde vers -Z de la vue).
    Retourne {objet: ([segments visibles (a, b)], [segments cachés])} avec a, b = points 2D (u, v)."""
    from mathutils import Vector
    right = quat @ Vector((1.0, 0.0, 0.0))
    up = quat @ Vector((0.0, 1.0, 0.0))
    look = quat @ Vector((0.0, 0.0, -1.0))
    toward = -look                          # vers l'observateur
    eps = max(diag * 1e-5, 1e-9)
    far = diag * 4.0 + 1.0
    sharp = math.radians(sharp_deg)
    tan_min = math.radians(1.0)

    def visible(p):
        if bvh is None:
            return True
        return bvh.ray_cast(p + toward * eps, toward, far)[0] is None

    def uv(p):
        return (p.dot(right), p.dot(up))

    out = {}
    for obj, bm in bms:
        vis_segs, hid_segs = [], []
        for e in bm.edges:
            faces = e.link_faces
            nf = len(faces)
            keep = False
            if nf != 2:
                keep = True                                  # bord, arête libre ou non-variété
            else:
                f0, f1 = faces
                front0, front1 = f0.normal.dot(look) < 0.0, f1.normal.dot(look) < 0.0
                if front0 != front1:
                    keep = True                              # silhouette
                else:
                    ang = e.calc_face_angle(0.0)
                    if ang >= sharp or not e.smooth:
                        keep = True                          # arête vive
                    elif tangent and ang >= tan_min:
                        keep = True                          # arête tangente (surfaces lisses)
            if not keep:
                continue
            a, b = e.verts[0].co, e.verts[1].co
            ua, ub = uv(a), uv(b)
            l2d = math.hypot(ub[0] - ua[0], ub[1] - ua[1])
            if l2d < diag * 1e-7:
                continue                                     # arête dans l'axe de la vue
            n = max(2, min(40, int(l2d / (diag * 0.02)) + 2))
            ts = [i / (n - 1) for i in range(n)]
            vs = [visible(a.lerp(b, t)) for t in ts]
            # frontières de visibilité par dichotomie
            cuts = [0.0]
            states = [vs[0]]
            for i in range(n - 1):
                if vs[i] != vs[i + 1]:
                    lo, hi = ts[i], ts[i + 1]
                    s_lo = vs[i]
                    for _k in range(14):
                        mid = (lo + hi) * 0.5
                        if visible(a.lerp(b, mid)) == s_lo:
                            lo = mid
                        else:
                            hi = mid
                    cuts.append((lo + hi) * 0.5)
                    states.append(vs[i + 1])
            cuts.append(1.0)
            for k, state in enumerate(states):
                t0, t1 = cuts[k], cuts[k + 1]
                if t1 - t0 <= 1e-9:
                    continue
                seg = (uv(a.lerp(b, t0)), uv(a.lerp(b, t1)))
                if state:
                    vis_segs.append(seg)
                elif hidden:
                    hid_segs.append(seg)
        out[obj] = (vis_segs, hid_segs)
    return out


def merge_segments(segs, tol):
    """Chaîne les segments 2D en polylignes : [(points [(u, v)], fermé)]."""
    index, pts, edges, seen = {}, [], [], set()
    for a, b in segs:
        ids = []
        for p in (a, b):
            key = (round(p[0] / tol), round(p[1] / tol))
            if key not in index:
                index[key] = len(pts)
                pts.append(p)
            ids.append(index[key])
        if ids[0] == ids[1]:
            continue
        k = (min(ids), max(ids))
        if k in seen:
            continue
        seen.add(k)
        edges.append((ids[0], ids[1]))
    paths = []
    for path, closed in wire_paths(len(pts), edges):
        P = [pts[i] for i in path]
        if closed and len(P) > 1 and abs(P[0][0] - P[-1][0]) + abs(P[0][1] - P[-1][1]) <= tol * 2:
            P = P[:-1]
        if len(P) >= 2:
            paths.append((P, bool(closed) and len(P) >= 3))
    return paths


def bbox_2d(segs):
    xs = [p[0] for s in segs for p in s]
    ys = [p[1] for s in segs for p in s]
    return (min(xs), min(ys), max(xs), max(ys)) if xs else None


def new_poly_curve(name, paths, place):
    """Courbe à plusieurs splines POLY. place(u, v) -> (x, y, z) monde."""
    cu = bpy.data.curves.new(name, 'CURVE')
    cu.dimensions = '3D'
    for P, closed in paths:
        sp = cu.splines.new('POLY')
        sp.points.add(len(P) - 1)
        for pt, (u, v) in zip(sp.points, P):
            x, y, z = place(u, v)
            pt.co = (x, y, z, 1.0)
        sp.use_cyclic_u = closed
    return cu


def output_collection(context, name):
    name = name.strip() or "Make2D"
    col = bpy.data.collections.get(name)
    if col is None:
        col = bpy.data.collections.new(name)
        context.scene.collection.children.link(col)
    elif col.name not in context.scene.collection.children_recursive and col not in context.scene.collection.children_recursive:
        try:
            context.scene.collection.children.link(col)
        except RuntimeError:
            pass
    return col


class DESSIN_OT_make2d(bpy.types.Operator):
    bl_idname = "dessin.make2d"
    bl_label = "Make 2D"
    bl_description = ("Creates a 2D drawing (visible and hidden lines) of the selected objects as seen from one of the named views, "
                      "or as a third / first angle projection")
    bl_options = {'REGISTER', 'UNDO'}

    view: bpy.props.EnumProperty(name="View", items=make2d_view_items)
    projection: bpy.props.EnumProperty(
        name="Projection", default='VIEW',
        items=(('VIEW', "View", "Parallel projection seen from the chosen view"),
               ('THIRD', "Third angle projection", "Front, with Top above and Right on the right"),
               ('FIRST', "First angle projection", "Front, with Top below and Right on the left")))
    tangent_edges: bpy.props.BoolProperty(
        name="Tangent edges", default=False,
        description="Also draws the edges between smooth surfaces (can add many lines on finely tessellated meshes)")
    hidden_lines: bpy.props.BoolProperty(name="Hidden lines", default=False,
                                         description="Also creates the hidden lines, as separate grey objects")
    viewport_rect: bpy.props.BoolProperty(name="Viewport rectangle", default=False,
                                          description="Adds a rectangle around each drawing")
    group_output: bpy.props.BoolProperty(name="Group output", default=False,
                                         description="Parents the results of each view to an Empty so they move together")
    place_beside: bpy.props.BoolProperty(name="Place beside the objects", default=True,
                                         description="Puts the drawing flat on the ground (XY), to the right of the objects. Off: at the world origin")
    sharp_angle: bpy.props.FloatProperty(name="Sharp edge angle", default=math.radians(25.0), min=0.0, max=math.pi,
                                         subtype='ANGLE', description="Edges between faces that make a larger angle are drawn")
    collection_name: bpy.props.StringProperty(name="Collection name", default="Make2D")

    @classmethod
    def poll(cls, context):
        return context.mode == 'OBJECT' and context.area is not None and context.area.type == 'VIEW_3D'

    def invoke(self, context, event):
        objs = ordered_selection(context)
        if not objs:
            self.report({'INFO'}, "Click the objects, then Enter")
            return {'CANCELLED'}
        names = [i[0] for i in make2d_view_items(self, context)]
        cur = current_view_name(context)
        self.view = cur if cur in names else "Top"
        return context.window_manager.invoke_props_dialog(self, width=340)

    def draw(self, context):
        layout = self.layout
        layout.label(text="View")
        layout.prop(self, "view", text="")
        layout.label(text="Projection")
        col = layout.column(align=True)
        col.prop(self, "projection", expand=True)
        layout.label(text="Options")
        col = layout.column(align=True)
        col.prop(self, "tangent_edges")
        col.prop(self, "hidden_lines")
        col.prop(self, "viewport_rect")
        col.prop(self, "group_output")
        col.prop(self, "place_beside")
        col.prop(self, "sharp_angle")
        layout.label(text="Collection name")
        layout.prop(self, "collection_name", text="")
        if self.projection != 'VIEW':
            layout.label(text="Top / Front / Right are used (the view above is ignored)", icon='INFO')

    def execute(self, context):
        scene = context.scene
        objs = ordered_selection(context)
        if not objs:
            self.report({'INFO'}, "Select objects first")
            return {'CANCELLED'}
        depsgraph = context.evaluated_depsgraph_get() if hasattr(context, "evaluated_depsgraph_get") else bpy.context.evaluated_depsgraph_get()
        bms, bvh, verts = make2d_collect(objs, depsgraph)
        try:
            if not bms or not verts:
                self.report({'WARNING'}, "No geometry to project")
                return {'CANCELLED'}
            P = np.array([tuple(v) for v in verts])
            lo, hi = P.min(axis=0), P.max(axis=0)
            diag = float(np.linalg.norm(hi - lo)) or 1.0
            if sum(len(bm.edges) for _o, bm in bms) > MAKE2D_LIMIT:
                self.report({'WARNING'}, "Very heavy model: Make 2D may take a while")
            if self.projection == 'VIEW':
                views = [(self.view, named_view_rotation(scene, self.view))]
            else:
                views = [(n, _axis_quat(a)) for n, a in (("Front", 'FRONT'), ("Top", 'TOP'), ("Right", 'RIGHT'))]
            results = {}
            for vname, quat in views:
                res = make2d_project(bms, bvh, quat, diag, self.tangent_edges, self.hidden_lines, self.sharp_angle)
                allsegs = [s for vis, hid in res.values() for s in vis + hid]
                results[vname] = (res, bbox_2d(allsegs))
        finally:
            for _o, bm in bms:
                bm.free()
        if all(b is None for _r, b in results.values()):
            self.report({'WARNING'}, "Nothing to draw in this view")
            return {'CANCELLED'}
        gap = diag * 0.1
        offsets = self.layout_offsets(results, lo, hi, gap)
        col = output_collection(context, self.collection_name)
        made = []
        for vname, (res, bb) in results.items():
            if bb is None:
                continue
            ox, oy = offsets[vname]
            place = (lambda ox, oy: (lambda u, v: (u + ox, v + oy, 0.0)))(ox, oy)
            tol = max(diag * 1e-6, 1e-9)
            label = view_label(scene, vname) if vname in dict(BASE_VIEWS) or find_view(scene, vname) else vname
            parent = None
            if self.group_output:
                parent = bpy.data.objects.new(f"Make2D {label}", None)
                parent.empty_display_type = 'PLAIN_AXES'
                parent.empty_display_size = diag * 0.02
                col.objects.link(parent)
                made.append(parent)
            for obj, (vis, hid) in res.items():
                for suffix, segs, grey in ((label, vis, False), (f"{label} hidden", hid, True)):
                    paths = merge_segments(segs, tol)
                    if not paths:
                        continue
                    cu = new_poly_curve(f"{obj.name} {suffix}", paths, place)
                    o = bpy.data.objects.new(cu.name, cu)
                    if grey:
                        o.color = (0.5, 0.5, 0.5, 1.0)
                    col.objects.link(o)
                    if parent is not None:
                        o.parent = parent
                    made.append(o)
            if self.viewport_rect:
                pad = diag * 0.02
                x0, y0, x1, y1 = bb[0] - pad, bb[1] - pad, bb[2] + pad, bb[3] + pad
                cu = new_poly_curve(f"Make2D {label} frame", [([(x0, y0), (x1, y0), (x1, y1), (x0, y1)], True)], place)
                o = bpy.data.objects.new(cu.name, cu)
                col.objects.link(o)
                if parent is not None:
                    o.parent = parent
                made.append(o)
        for o in context.selected_objects:
            o.select_set(False)
        for o in made:
            o.select_set(True)
        if made:
            context.view_layer.objects.active = made[0]
        self.report({'INFO'}, f"Make 2D: {len(made)} object(s) in '{col.name}'")
        return {'FINISHED'}

    def layout_offsets(self, results, lo, hi, gap):
        """Décalage (x, y) de chaque dessin : à droite des objets, vues en croix pour les projections à 3 vues."""
        if not self.place_beside:
            return {n: (0.0, 0.0) for n in results}
        def bb(n):
            return results[n][1]
        if self.projection == 'VIEW':
            n = next(iter(results))
            b = bb(n)
            if b is None:
                return {n: (0.0, 0.0)}
            return {n: (hi[0] + gap - b[0], lo[1] - b[1])}
        fb = bb("Front") or (0.0, 0.0, 0.0, 0.0)
        x0 = hi[0] + gap - fb[0]
        y0 = lo[1] - fb[1]
        offs = {"Front": (x0, y0)}
        tb, rb = bb("Top"), bb("Right")
        if tb is not None:
            if self.projection == 'THIRD':
                offs["Top"] = (x0, y0 + fb[3] + gap - tb[1])
            else:
                offs["Top"] = (x0, y0 + fb[1] - gap - tb[3])
        if rb is not None:
            if self.projection == 'THIRD':
                offs["Right"] = (x0 + fb[2] + gap - rb[0], y0)
            else:
                offs["Right"] = (x0 + fb[0] - gap - rb[2], y0)
        return offs


# --------------------------------------------------------------------------
# Lumières et caméra : on les pose avec la souris (clic, glisser pour la taille / la direction)
# --------------------------------------------------------------------------

class LightBase(DessinBase):
    """Base des outils lumière / caméra (classe non enregistrée) : objets, pas de mode édition."""

    EDIT_OK = False
    DATA_NAME = "Light"
    LIGHT_TYPE = 'POINT'
    ENERGY = 1000.0

    def new_light(self, context, loc, rot=None, name=None):
        data = bpy.data.lights.new(name or self.DATA_NAME, self.LIGHT_TYPE)
        data.energy = self.ENERGY
        obj = _link_object(context, name or self.DATA_NAME, data)
        obj.location = loc
        if rot is not None:
            obj.rotation_euler = rot.to_euler()
        return obj

    def aim_quat(self, a, b):
        """Rotation qui oriente l'axe -Z de l'objet de a vers b (lumières et caméras regardent vers -Z)."""
        d = b - a
        if d.length < 1e-9:
            d = Vector((0.0, 0.0, -1.0))
        return d.to_track_quat('-Z', 'Y')


class DESSIN_OT_light_point(LightBase):
    bl_idname = "dessin.light_point"
    bl_label = "Point Light"
    bl_description = "Places a point light: click its position, then drag / click to set its radius (or type the radius)"

    TITLE = "Point Light"
    NEEDED = 2
    NUMFIELDS = 1

    def prompt(self):
        if not self.points:
            return "position of the light"
        return "radius (drag, or type the radius then Enter)"

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        c = self.points[0]
        u, v, _ = plane_axes(self.axis)
        d = self.cur - c
        r = math.hypot(d.dot(u), d.dot(v))
        t = self.typed_value(0)
        if t is not None:
            r = abs(t)
        prev = arc_samples(c, u, v, r, 0.0, TAU, 64) if r > 1e-9 else []
        return prev, [], f"Radius {self.fmt(r)}", ("point", c.copy(), r)

    def build(self, context, spec):
        _, c, r = spec
        obj = self.new_light(context, c)
        if r > 1e-6:
            obj.data.shadow_soft_size = r


class DESSIN_OT_light_spot(LightBase):
    bl_idname = "dessin.light_spot"
    bl_label = "Spot Light"
    bl_description = ("Places a spot light: its position, the point it aims at, then the radius of the cone at that point "
                      "(drag, or type the radius)")

    TITLE = "Spot Light"
    NEEDED = 3
    NUMFIELDS = 1
    PLANAR = False
    LIGHT_TYPE = 'SPOT'

    def prompt(self):
        n = len(self.points)
        if n == 0:
            return "position of the spot"
        if n == 1:
            return "target point (where the spot aims)"
        return "radius of the cone at the target (drag, or type the radius then Enter)"

    def compute(self):
        n = len(self.points)
        if n == 0 or self.cur is None:
            return [], [], "", None
        p0 = self.points[0]
        if n == 1:
            return [], [[p0, self.cur]], f"Distance {self.fmt((self.cur - p0).length)}", None
        p1 = self.points[1]
        axis = p1 - p0
        L = axis.length
        if L < 1e-9:
            return [], [], "", None
        f = axis / L
        r = (self.cur - p0).cross(f).length
        t = self.typed_value(0)
        if t is not None:
            r = abs(t)
        ang = 2.0 * math.atan2(r, L) if r > 1e-9 else math.radians(45.0)
        ang = max(math.radians(1.0), min(math.radians(179.0), ang))
        rr = L * math.tan(ang / 2.0)
        a = f.orthogonal().normalized()
        b = f.cross(a)
        ring = [p1 + (a * math.cos(TAU * i / 48) + b * math.sin(TAU * i / 48)) * rr for i in range(49)]
        guides = [[p0, p1]] + [[p0, ring[k]] for k in (0, 12, 24, 36)]
        info = f"Cone {math.degrees(ang):.1f}°   Radius {self.fmt(rr)}"
        return ring, guides, info, ("spot", p0.copy(), p1.copy(), ang)

    def build(self, context, spec):
        _, p0, p1, ang = spec
        obj = self.new_light(context, p0, self.aim_quat(p0, p1))
        obj.data.spot_size = ang
        obj.data.spot_blend = 0.15


class DESSIN_OT_light_sun(LightBase):
    bl_idname = "dessin.light_sun"
    bl_label = "Sun Light"
    bl_description = "Places a sun light: click its position, then the point it aims at (the direction of the light)"

    TITLE = "Sun Light"
    NEEDED = 2
    NUMFIELDS = 0
    PLANAR = False
    LIGHT_TYPE = 'SUN'
    ENERGY = 3.0

    def prompt(self):
        return "position of the sun" if not self.points else "target point (direction of the light)"

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        p0 = self.points[0]
        d = self.cur - p0
        if d.length < 1e-9:
            return [], [], "", None
        f = d.normalized()
        tip = self.cur
        a = f.orthogonal().normalized() * (d.length * 0.08)
        guides = [[p0, tip], [tip, tip - f * (d.length * 0.15) + a], [tip, tip - f * (d.length * 0.15) - a]]
        return [], guides, f"Direction ({f.x:.2f}, {f.y:.2f}, {f.z:.2f})", ("sun", p0.copy(), tip.copy())

    def build(self, context, spec):
        _, p0, p1 = spec
        self.new_light(context, p0, self.aim_quat(p0, p1))


class DESSIN_OT_light_area(LightBase):
    bl_idname = "dessin.light_area"
    bl_label = "Area Light"
    bl_description = ("Places a rectangular area light like a rectangle: two opposite corners (or type width, Tab, height); "
                      "it lights away from the construction plane (F: flip, C: from center)")

    TITLE = "Area Light"
    PROP = (1,)
    NEEDED = 2
    NUMFIELDS = 2
    HAS_CENTER = True
    HAS_FLIP = True
    LIGHT_TYPE = 'AREA'
    ENERGY = 1000.0

    def prompt(self):
        if not self.points:
            return "first corner" + (" (center)" if self.center else "") + "   [C: from center]"
        return "opposite corner   (Shift: square, or type width, Tab, height, Enter)   [F: flip the light direction]"

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        o = self.points[0]
        u, v, n = plane_axes(self.axis)
        d = self.cur - o
        du, dv = d.dot(u), d.dot(v)
        w = self.sized(0, 2 * du if self.center else du, du)
        h = self.sized(1, 2 * dv if self.center else dv, dv)
        if abs(w) < 1e-9 or abs(h) < 1e-9:
            return [], [], "", None
        a0, b0 = (-w / 2.0, -h / 2.0) if self.center else (0.0, 0.0)
        corners = [o + u * (a0 + x) + v * (b0 + y) for x, y in ((0, 0), (w, 0), (w, h), (0, h))]
        c = o + u * (a0 + w / 2.0) + v * (b0 + h / 2.0)
        emit = n if self.flip else -n
        tip = c + emit * (min(abs(w), abs(h)) * 0.5)
        info = f"Width {self.fmt(abs(w))}   Height {self.fmt(abs(h))}"
        return corners + [corners[0]], [[c, tip]], info, ("area", c, u.copy(), v.copy(), n.copy(), abs(w), abs(h), bool(self.flip))

    def build(self, context, spec):
        _, c, u, v, n, w, h, flip = spec
        z = -n if flip else n                      # une lumière surface éclaire vers -Z local
        vv = -v if flip else v                     # repère direct
        rot = Matrix((u, vv, z)).transposed()
        obj = self.new_light(context, c, rot)
        obj.data.shape = 'RECTANGLE'
        obj.data.size = w
        obj.data.size_y = h


def camera_frustum(p0, p1, lens, aim=None):
    """(coins du cadre, guides) d'une caméra en p0 qui regarde vers p1 (ou dans la direction aim), à la focale donnée."""
    d = (p1 - p0) if aim is None else aim
    L = d.length
    f = d / L if L > 1e-9 else Vector((0.0, 0.0, -1.0))
    right = f.cross(Vector((0.0, 0.0, 1.0)))
    if right.length < 1e-6:
        right = Vector((1.0, 0.0, 0.0))
    right.normalize()
    up = right.cross(f)
    w = L * 36.0 / lens
    h = w * 9.0 / 16.0
    c = p0 + f * L
    corners = [c + right * sx * w / 2.0 + up * sy * h / 2.0 for sx, sy in ((-1, -1), (1, -1), (1, 1), (-1, 1))]
    return corners, [[p0, k] for k in corners]


class DESSIN_OT_camera(LightBase):
    bl_idname = "dessin.camera_add"
    bl_label = "Camera"
    bl_description = ("Places a camera (50 mm, like Blender's own): a first click for its position, a second click to aim it "
                      "in steps of 90° (Shift: free aim)")

    TITLE = "Camera"
    NEEDED = 2
    NUMFIELDS = 0
    PLANAR = False
    LENS = 50.0
    SIZE = 1.0

    def prompt(self):
        if not self.points:
            return "position of the camera (50 mm)"
        return "click to set the direction (steps of 90°)   (Shift: free aim)"

    def aim(self, p0):
        """Direction de visée : l'axe du plan de construction le plus proche du curseur (cran de 90°), ou libre avec Maj."""
        u, v, _ = plane_axes(self.axis)
        if not self.points or self.cur is None:
            return v.copy()
        d = self.cur - p0
        if d.length < 1e-9:
            return v.copy()
        if self.shift:
            return d.normalized()
        du, dv = d.dot(u), d.dot(v)
        if abs(du) >= abs(dv):
            return u * (1.0 if du >= 0 else -1.0)
        return v * (1.0 if dv >= 0 else -1.0)

    def compute(self):
        if self.cur is None:
            return [], [], "", None
        p0 = self.points[0] if self.points else self.cur
        f = self.aim(p0)
        L = self.SIZE * self.LENS / 36.0
        corners, guides = camera_frustum(p0, p0, self.LENS, f * L)
        info = f"Focal length {self.LENS:g} mm   Direction ({f.x:.2f}, {f.y:.2f}, {f.z:.2f})"
        spec = ("camera", p0.copy(), f.copy()) if self.points else None
        return corners + [corners[0]], guides, info, spec

    def build(self, context, spec):
        _, p0, f = spec
        cam = bpy.data.cameras.new("Camera")
        cam.lens = self.LENS
        obj = _link_object(context, "Camera", cam)
        obj.location = p0
        obj.rotation_euler = f.to_track_quat('-Z', 'Y').to_euler()
        if context.scene.camera is None:
            context.scene.camera = obj


class DESSIN_OT_camera_target(LightBase):
    bl_idname = "dessin.camera_target"
    bl_label = "Camera with Target"
    bl_description = ("Places a camera (50 mm) with a first click and an Empty with a second click: the camera follows the Empty "
                      "(Track To), so moving the Empty re-aims the camera")

    TITLE = "Camera with Target"
    NEEDED = 2
    NUMFIELDS = 0
    PLANAR = False
    LENS = 50.0

    def prompt(self):
        if not self.points:
            return "click to place the camera (50 mm)"
        return "click to place the target Empty (the camera looks at it)"

    def compute(self):
        if not self.points or self.cur is None:
            return [], [], "", None
        p0 = self.points[0]
        L = (self.cur - p0).length
        if L < 1e-9:
            return [], [], "", None
        corners, guides = camera_frustum(p0, self.cur, self.LENS)
        info = f"Focal length {self.LENS:g} mm   Distance {self.fmt(L)}"
        return corners + [corners[0]], guides + [[p0, self.cur]], info, ("camera", p0.copy(), self.cur.copy(), self.LENS, L)

    def build(self, context, spec):
        _, p0, p1, lens, L = spec
        cam = bpy.data.cameras.new("Camera")
        cam.lens = lens
        size = 1.0                      # taille d'affichage par défaut de Blender, comme l'outil Camera
        cam.display_size = size
        obj = _link_object(context, "Camera", cam)
        obj.location = p0
        obj.rotation_euler = self.aim_quat(p0, p1).to_euler()
        target = bpy.data.objects.new("Camera Target", None)
        target.empty_display_type = 'PLAIN_AXES'
        target.empty_display_size = 0.5
        target.location = p1
        context.view_layer.active_layer_collection.collection.objects.link(target)
        con = obj.constraints.new('TRACK_TO')
        con.target = target
        con.track_axis = 'TRACK_NEGATIVE_Z'
        con.up_axis = 'UP_Y'
        target.select_set(True)
        if context.scene.camera is None:
            context.scene.camera = obj


_GUMBALL_TOOLS = ("builtin.select", "builtin.select_box", "builtin.select_circle", "builtin.select_lasso",
                  "dessin.selection_boite_tool", "dessin.selection_lasso_tool",
                  "dessin.selection_rect_tool", "dessin.selection_cercle_tool")


def _gz_set(gz, **kw):
    for k, v in kw.items():
        try:
            setattr(gz, k, v)
        except (AttributeError, TypeError, ValueError):
            pass


def _axis_matrix(origin, axis, scale):
    q = Vector((0.0, 0.0, 1.0)).rotation_difference(axis)
    return Matrix.Translation(origin) @ q.to_matrix().to_4x4() @ Matrix.Scale(scale, 4)


_GB_FLAT = {"t": 0.0, "sig": None, "res": frozenset()}


def gumball_flat_axes(context, axes):
    """Indices des axes du Gumball le long desquels la sélection n'a aucune épaisseur (ex. un Plane en Z) : pas d'échelle possible."""
    sig = None
    try:
        now = time.monotonic()
        sig = (context.mode, tuple(round(c, 4) for a in axes for c in a))
        if sig == _GB_FLAT["sig"] and now - _GB_FLAT["t"] < 0.25:
            return _GB_FLAT["res"]
        pts = []
        if context.mode in {'EDIT_MESH', 'EDIT_CURVE'}:
            sel = edit_selection(context) if context.mode == 'EDIT_MESH' else curve_edit_selection(context)
            if not sel:
                return frozenset()
            allp = np.vstack([w for _o, _i, w in sel])
            if len(allp) > 20000:
                allp = allp[::max(1, len(allp) // 20000)]
            pts = allp
        else:
            sel = expand_groups(context, context.selected_objects)
            lst = []
            for o in sel:
                if o.type == 'EMPTY' or not o.bound_box:
                    lst.append(tuple(o.matrix_world.translation))
                else:
                    mw = o.matrix_world
                    lst += [tuple(mw @ Vector(c)) for c in o.bound_box]
            if not lst:
                return frozenset()
            pts = np.array(lst, dtype=float)
        ext = pts.max(axis=0) - pts.min(axis=0)
        diag = float(np.linalg.norm(ext)) or 1.0
        flat = set()
        for i in range(3):
            d = np.array([axes[i].x, axes[i].y, axes[i].z])
            pr = pts @ d
            if float(pr.max() - pr.min()) <= max(1e-6, diag * 1e-5):
                flat.add(i)
        res = frozenset(flat) if len(flat) < 3 else frozenset()
    except (AttributeError, RuntimeError, ReferenceError, TypeError, ValueError):
        res = frozenset()
    _GB_FLAT.update(t=time.monotonic(), sig=sig, res=res)
    return res



class DESSIN_GGT_gumball(bpy.types.GizmoGroup):
    bl_idname = "DESSIN_GGT_gumball"
    bl_label = "Gumball"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'WINDOW'
    bl_options = {'3D', 'PERSISTENT'}

    @classmethod
    def poll(cls, context):
        try:
            if not context.scene.dessin.gumball or foreign_modal(context):
                return False
            if context.mode == 'OBJECT':
                if not context.selected_objects:
                    return False
            elif context.mode == 'EDIT_MESH':
                if not any(o.data.total_vert_sel > 0 for o in context.objects_in_mode_unique_data if o.type == 'MESH'):
                    return False
            elif context.mode == 'EDIT_CURVE':
                if not any(o.type == 'CURVE' for o in context.objects_in_mode_unique_data):
                    return False
            else:
                return False
            tool = context.workspace.tools.from_space_view3d_mode(context.mode, create=False)
        except (AttributeError, RuntimeError, TypeError):
            return False
        return tool is None or tool.idname in _GUMBALL_TOOLS

    def setup(self, context):
        self.gz_move, self.gz_scale, self.gz_rot = [], [], []
        self.gz_ext = None
        for a in range(3):
            col = GUMBALL_COLORS[a]
            for store, kind, gtype, style in ((self.gz_move, 'MOVE', "GIZMO_GT_arrow_3d", 'NORMAL'),
                                              (self.gz_scale, 'SCALE', "GIZMO_GT_arrow_3d", 'BOX'),
                                              (self.gz_rot, 'ROTATE', "GIZMO_GT_dial_3d", None)):
                gz = self.gizmos.new(gtype)
                props = gz.target_set_operator(DESSIN_OT_gumball.bl_idname)
                props.kind = kind
                props.axis = a
                _gz_set(gz, color=col, alpha=0.9, color_highlight=(1.0, 0.85, 0.2), alpha_highlight=1.0,
                        use_draw_modal=True, use_draw_scale=False, scale_basis=1.0)
                if style is not None:
                    _gz_set(gz, draw_style=style)
                else:
                    _gz_set(gz, draw_options={'CLIP'}, line_width=float(pref("gumball_line")))
                store.append(gz)

    def place(self, context):
        pivot, top = gumball_selection_cached(context)
        rv3d, region = context.region_data, context.region
        every = self.gz_move + self.gz_scale + self.gz_rot
        if pivot is None or not top or rv3d is None or region is None:
            for gz in every:
                gz.hide = True
            return
        v = rv3d.perspective_matrix @ Vector((pivot.x, pivot.y, pivot.z, 1.0))
        proj = rv3d.window_matrix[0][0] or 1.0
        px = max(abs(v.w), 1e-6) / (0.5 * region.width * proj)      # unités monde par pixel au centre
        px *= gumball_k(context)
        axes = gumball_axes(context)
        for a in range(3):
            d = axes[a]
            self.gz_move[a].matrix_basis = _axis_matrix(pivot, d, GUMBALL_PX * px)
            self.gz_scale[a].matrix_basis = _axis_matrix(pivot, -d, GUMBALL_PX * 0.98 * px)
            self.gz_rot[a].matrix_basis = _axis_matrix(pivot, d, GUMBALL_PX * 0.62 * px)
        lw = float(pref("gumball_line"))
        for gz in self.gz_rot:
            _gz_set(gz, line_width=lw)
        for gz in every:
            gz.hide = False
        flat = gumball_flat_axes(context, axes)
        for a in flat:
            self.gz_scale[a].hide = True

    def refresh(self, context):
        self.place(context)

    def draw_prepare(self, context):
        self.place(context)
        try:
            sp = context.space_data
            if (native_gizmos_hidden() and not _NATIVE_GIZMOS["pending"]
                    and (sp.show_gizmo_object_translate or sp.show_gizmo_object_rotate or sp.show_gizmo_object_scale)):
                _NATIVE_GIZMOS["pending"] = True
                bpy.app.timers.register(_native_gizmos_off, first_interval=0.0)
        except (AttributeError, ReferenceError, RuntimeError):
            pass


_NATIVE_GIZMOS = {"pending": False}


def _native_gizmos_off():
    """Coupe les gizmos Déplacer / Pivoter / Échelle de Blender (le Gumball les remplace) dans toutes les vues 3D."""
    _NATIVE_GIZMOS["pending"] = False
    if not native_gizmos_hidden():
        return None
    try:
        for win in bpy.context.window_manager.windows:
            for area in win.screen.areas:
                if area.type != 'VIEW_3D':
                    continue
                for sp in area.spaces:
                    if sp.type == 'VIEW_3D':
                        for attr in ("show_gizmo_object_translate", "show_gizmo_object_rotate", "show_gizmo_object_scale"):
                            if getattr(sp, attr, False):
                                setattr(sp, attr, False)
    except (AttributeError, RuntimeError, ReferenceError):
        pass
    return None


def native_gizmos_hidden():
    """Les gizmos natifs sont masqués (le Gumball les remplace) tant qu'aucun outil Move / Rotate / Scale / Transform de Blender n'est affiché."""
    return not any(pref(k) for k in ("show_tool_move", "show_tool_rotate", "show_tool_scale", "show_tool_transform"))


def _update_native_gizmos():
    """Réglage « Hide Blender's gizmos » : coché = on les coupe tout de suite ; décoché = on les réaffiche dans toutes les vues 3D."""
    on = native_gizmos_hidden()
    try:
        for win in bpy.context.window_manager.windows:
            for area in win.screen.areas:
                if area.type != 'VIEW_3D':
                    continue
                for sp in area.spaces:
                    if sp.type == 'VIEW_3D':
                        for attr in ("show_gizmo_object_translate", "show_gizmo_object_rotate", "show_gizmo_object_scale"):
                            if hasattr(sp, attr):
                                setattr(sp, attr, not on)
                area.tag_redraw()
    except (AttributeError, RuntimeError, ReferenceError):
        pass


EXT_BALL_ENABLED = False   # poignée d'extrusion orange du Gumball : retirée pour l'instant (clic non fiable)
EXT_BALL_R = 5.0      # rayon de la boule d'extrusion (pixels, avant échelle de l'interface)


def ext_ball_px():
    return EXT_BALL_R * px_scale(0.3)      # échelle atténuée : sur écran Retina la boule restait énorme
_EXT_BALL = {"handle": None, "hover": False}


def foreign_modal(context):
    """True si une commande modale de Blender (Loop Cut, Knife, Bevel...) est en cours : le Gumball s'efface alors et
    ne touche pas au maillage en édition pendant qu'elle travaille."""
    try:
        for op in context.window.modal_operators:
            if not op.bl_idname.startswith("DESSIN_OT"):
                return True
    except (AttributeError, RuntimeError, ReferenceError):
        pass
    return False


def extrude_ball_pos(context, region=None, rv3d=None):
    """Position écran (région, pixels) de la boule d'extrusion, ou None quand elle n'est pas affichée.
    Elle est sur la flèche du Gumball la plus proche de la normale des faces / arêtes sélectionnées."""
    if not EXT_BALL_ENABLED:
        return None
    try:
        if context.mode != 'EDIT_MESH' or not context.scene.dessin.gumball or foreign_modal(context):
            return None
        tool = context.workspace.tools.from_space_view3d_mode(context.mode, create=False)
        if tool is not None and tool.idname not in _GUMBALL_TOOLS:
            return None
        rv3d = rv3d or context.region_data
        region = region or context.region
        if rv3d is None or region is None or region.type != 'WINDOW':
            return None
        nf, ne = extrude_info(context)
        if not (nf or ne):
            return None
        pivot, top = gumball_selection_cached(context)
        if pivot is None or not top:
            return None
        nd = extrude_direction(context) or Vector((0.0, 0.0, 1.0))
    except (AttributeError, RuntimeError, ReferenceError, TypeError):
        return None
    v = rv3d.perspective_matrix @ Vector((pivot.x, pivot.y, pivot.z, 1.0))
    proj = rv3d.window_matrix[0][0] or 1.0
    px = max(abs(v.w), 1e-6) / (0.5 * region.width * proj) * gumball_k(context)
    axis = max(range(3), key=lambda k: abs(AXES3[k].dot(nd)))
    a_dir = AXES3[axis] * (1.0 if AXES3[axis].dot(nd) >= 0 else -1.0)
    line = a_dir if a_dir.dot(nd) > 0.966 else nd       # normale oblique : sur la normale elle-même
    return project_px(rv3d, region, pivot + line * (0.45 * GUMBALL_PX * px))


def draw_extrude_ball():
    context = bpy.context
    pos = extrude_ball_pos(context)
    if pos is None:
        return
    r = ext_ball_px()
    shader = get_shader('2D')
    gpu.state.blend_set('ALPHA')
    shader.bind()
    n = 28
    ring = [(pos.x + r * math.cos(TAU * i / n), pos.y + r * math.sin(TAU * i / n)) for i in range(n)]
    fan = []
    for i in range(n):
        fan += [(pos.x, pos.y), ring[i], ring[(i + 1) % n]]
    col = (1.0, 0.85, 0.3, 1.0) if _EXT_BALL["hover"] else (1.0, 0.65, 0.12, 1.0)
    shader.uniform_float("color", col)
    batch_for_shader(shader, 'TRIS', {"pos": fan}).draw(shader)
    shader.uniform_float("color", (1.0, 1.0, 1.0, 0.9))
    gpu.state.line_width_set(1.5)
    batch_for_shader(shader, 'LINE_LOOP', {"pos": ring}).draw(shader)
    gpu.state.line_width_set(1.0)
    gpu.state.blend_set('NONE')


def extrude_ball_hit(context, mx, my, region=None, rv3d=None):
    """True si le point (région) tombe sur la boule d'extrusion."""
    pos = extrude_ball_pos(context, region, rv3d)
    return pos is not None and (pos - Vector((mx, my))).length <= ext_ball_px() + 4.0 * px_scale(0.5)


def gumball_handle_at(context, mx, my, region, rv3d):
    """(type, axe) de la poignée du Gumball sous le point (région, pixels), ou None.
    Sert quand Alt est maintenu : Blender n'active alors pas toujours les poignées lui-même."""
    try:
        if not context.scene.dessin.gumball or foreign_modal(context):
            return None
        pivot, top = gumball_selection_cached(context)
    except (AttributeError, RuntimeError, ReferenceError, TypeError):
        return None
    if pivot is None or not top or rv3d is None or region is None:
        return None
    v = rv3d.perspective_matrix @ Vector((pivot.x, pivot.y, pivot.z, 1.0))
    proj = rv3d.window_matrix[0][0] or 1.0
    px = max(abs(v.w), 1e-6) / (0.5 * region.width * proj) * gumball_k(context)
    m = Vector((mx, my))
    sp = project_px(rv3d, region, pivot)
    if sp is None:
        return None
    sc = px_scale()
    best, best_d = None, 1e9

    def seg_dist(a, b):
        ab = b - a
        l2 = ab.length_squared
        t = 0.0 if l2 < 1e-9 else max(0.0, min(1.0, (m - a).dot(ab) / l2))
        return (a + ab * t - m).length

    axes = gumball_axes(context)
    flat = gumball_flat_axes(context, axes)
    for a in range(3):
        d = axes[a]
        tip = project_px(rv3d, region, pivot + d * (GUMBALL_PX * px))
        if tip is not None:
            dist = seg_dist(sp, tip)
            if dist <= 9.0 * sc and dist < best_d:
                best, best_d = ('MOVE', a), dist
        tip2 = project_px(rv3d, region, pivot - d * (GUMBALL_PX * 0.98 * px))
        if tip2 is not None and a not in flat:
            dist = seg_dist(sp, tip2)
            if dist <= 9.0 * sc and dist < best_d:
                best, best_d = ('SCALE', a), dist
        bu = d.orthogonal().normalized()
        bv = d.cross(bu)
        R = GUMBALL_PX * 0.62 * px
        ring = []
        for i in range(49):
            ang = TAU * i / 48
            q = project_px(rv3d, region, pivot + (bu * math.cos(ang) + bv * math.sin(ang)) * R)
            ring.append(q)
        for q0, q1 in zip(ring, ring[1:]):
            if q0 is None or q1 is None:
                continue
            dist = seg_dist(q0, q1)
            if dist <= 6.0 * sc and dist < best_d - 3.0 * sc:     # une flèche garde la priorité près du centre
                best, best_d = ('ROTATE', a), dist
    return best


